// 「프로그래밍기능사 통합 정리서·필기 모의고사집·실기 모의고사집」(2026년 11월 8일 기준) 내용
window.WQ=[{"id":"w1-01","r":1,"n":1,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int a = 5, b = 2;\n      printf(\"%d\", a / b + a % b);\n      return 0;\n}","o":["1","2","3","4"],"a":2,"e":"정수형 나눗셈이므로 a / b는 5 / 2 = 2(소수점 이하 버림)이고, a % b는 5를 2로 나눈 나머지인 1이다. 따라서 2 + 1 = 3이 출력된다."},{"id":"w1-02","r":1,"n":2,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"public class Test {\n      public static void main(String[] args) {\n           int[] arr = {1, 2, 3, 4, 5};\n           int sum = 0;\n           for (int i = 0; i < arr.length; i++) {\n               if (i % 2 == 0) sum += arr[i];\n           }\n           System.out.println(sum);\n      }\n}","o":["6","9","12","15"],"a":1,"e":"인덱스 i가 짝수(0, 2, 4)일 때만 배열 값을 더한다. arr[0]=1, arr[2]=3, arr[4]=5이 므로 합은 1+3+5=9이다."},{"id":"w1-03","r":1,"n":3,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"def func(n):\n       if n <= 1:\n           return 1\n       return n * func(n-1)\n\nprint(func(5))","o":["24","60","100","120"],"a":3,"e":"func 함수는 재귀 호출을 이용한 팩토리얼 계산 함수이다. func(5) = 5×4×3×2×1 = 120이다."},{"id":"w1-04","r":1,"n":4,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n       int x = 10;\n       int *p = &x;\n       *p = *p + 5;\n       printf(\"%d\", x);\n       return 0;\n}","o":["5","10","15","20"],"a":2,"e":"포인터 p는 변수 x의 주소를 저장하므로 *p는 x와 같은 메모리를 가리킨다. *p = *p + 5는 x의 값을 10에서 15로 변경하므로 15가 출력된다."},{"id":"w1-05","r":1,"n":5,"s":"P","q":"다음 중 C언어에서 정수형 변수를 선언할 때 사용하는 자료형이 아닌 것은?","code":"","o":["int","long","float","short"],"a":2,"e":"int, long, short는 모두 정수형 자료형이며, float은 실수(소수점)를 표현하는 실수형 자료형이다."},{"id":"w1-06","r":1,"n":6,"s":"P","q":"다음 중 Java의 접근 제어자(Access Modifier)가 아닌 것은?","code":"","o":["public","private","protected","static"],"a":3,"e":"public, private, protected는 클래스나 멤버의 접근 범위를 지정하는 접근 제어자이다. static은 접근 범위와 무관하게 클래스 차원의 멤버임을 나타내는 제어자로, 접근 제어자로 분류되지 않는다."},{"id":"w1-07","r":1,"n":7,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"lst = [10, 20, 30, 40, 50]\nprint(lst[1:4])","o":["[10, 20, 30]","[20, 30, 40]","[20, 30, 40, 50]","[30, 40, 50]"],"a":1,"e":"슬라이싱 lst[1:4]는 인덱스 1번부터 3번까지(4번 미포함)의 요소를 반환하므로 [20, 30, 40]이 출력된다."},{"id":"w1-08","r":1,"n":8,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int i, sum = 0;\n      for (i = 1; i <= 10; i++) {\n            if (i % 3 == 0) continue;\n            sum += i;\n      }\n      printf(\"%d\", sum);\n      return 0;\n}","o":["37","45","52","55"],"a":0,"e":"1부터 10까지의 합은 55이다. continue문에 의해 3의 배수(3, 6, 9)는 sum에 더해지지 않으므로 55 - (3+6+9) = 55 - 18 = 37이 출력된다."},{"id":"w1-09","r":1,"n":9,"s":"P","q":"위 Java 코드의 실행 결과는?","code":"String str = \"Hello\";\nSystem.out.println(str.charAt(1));","o":["H","e","l","o"],"a":1,"e":"문자열의 인덱스는 0부터 시작하므로 charAt(1)은 두 번째 문자인 'e'를 반환한다."},{"id":"w1-10","r":1,"n":10,"s":"P","q":"C언어에서 서로 다른 자료형의 변수들을 하나로 묶어 새로운 자료형을 정의할 때 사용하는 키워드는?","code":"","o":["union","struct","enum","typedef"],"a":1,"e":"struct는 서로 다른 자료형의 변수(멤버)들을 하나의 묶음으로 정의하는 구조체 선언 키워드이다. union은 메모리를 공유하는 공용체, enum은 열거형을 정의하는 키워드이다."},{"id":"w1-11","r":1,"n":11,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"d = {'a': 1, 'b': 2, 'c': 3}\nd['b'] = 20\nprint(sum(d.values()))","o":["6","23","24","43"],"a":2,"e":"d['b'] = 20으로 값이 변경되어 딕셔너리는 {'a':1, 'b':20, 'c':3}이 된다. values()의 합은 1+20+3=24이다."},{"id":"w1-12","r":1,"n":12,"s":"P","q":"다음 중 Java에서 예외 처리를 위해 사용하는 키워드가 아닌 것은?","code":"","o":["try","catch","finally","switch"],"a":3,"e":"try, catch, finally는 예외 처리 구문을 구성하는 키워드이다. switch는 다중 분기(조건 분기)를 위한 제어문으로 예외 처리와 관련이 없다."},{"id":"w1-13","r":1,"n":13,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n       int arr[5] = {1, 2, 3, 4, 5};\n       int *p = arr;\n       printf(\"%d\", *(p + 2));\n       return 0;\n}","o":["1","2","3","4"],"a":2,"e":"배열 이름 arr은 배열의 첫 번째 요소의 주소와 같으므로 포인터 p는 arr[0]을 가리킨다. *(p+2)는 arr[2]의 값인 3을 의미한다."},{"id":"w1-14","r":1,"n":14,"s":"P","q":"웹 페이지에서 다른 페이지로 이동하는 하이퍼링크를 만들 때 사용하는 HTML 태그는?","code":"","o":["<a>","<img>","<div>","<table>"],"a":0,"e":"<a> 태그는 anchor의 약자로, href 속성을 이용해 다른 페이지나 위치로 이동하는 하이퍼링크를 생성한다. <img>는 이미지 삽입, <div>는 구획 설정, <table>은 표를 만드는 태그이다."},{"id":"w1-15","r":1,"n":15,"s":"P","q":"CSS에서 텍스트(글자)의 색상을 지정할 때 사용하는 속성은?","code":"","o":["background-color","color","font-size","text-align"],"a":1,"e":"color 속성은 글자 색상을 지정한다. background-color는 배경색, font-size는 글자 크기, text-align은 텍스트 정렬 방식을 지정하는 속성이다."},{"id":"w1-16","r":1,"n":16,"s":"A","q":"윈도우 운영체제에서 응답하지 않는 프로그램을 강제로 종료할 때 사용하는 기능은?","code":"","o":["작업 관리자","제어판","파일 탐색기","디스크 정리"],"a":0,"e":"작업 관리자(Task Manager)는 실행 중인 프로세스와 프로그램의 상태를 확인하고 응답하지 않는 프로그램을 강제 종료할 수 있는 기능을 제공한다."},{"id":"w1-17","r":1,"n":17,"s":"A","q":"다음 중 파일 압축 프로그램에 해당하지 않는 것은?","code":"","o":["알집","반디집","7-Zip","알약"],"a":3,"e":"알집, 반디집, 7-Zip은 파일을 압축하거나 해제하는 압축 유틸리티이다. 알약은 컴퓨터 바이러스를 검사하고 치료하는 백신 프로그램이다."},{"id":"w1-18","r":1,"n":18,"s":"A","q":"대부분의 응용 프로그램에서 단축키 Ctrl+Z를 눌렀을 때 수행되는 기능은?","code":"","o":["실행 취소","다시 실행","복사","붙여넣기"],"a":0,"e":"Ctrl+Z는 직전에 수행한 작업을 취소하는 실행 취소(Undo) 기능의 단축키이다. 다시 실행은 일반적으로 Ctrl+Y이다."},{"id":"w1-19","r":1,"n":19,"s":"A","q":"스프레드시트 프로그램에서 지정된 범위의 합계를 구할 때 사용하는 함수는?","code":"","o":["SUM","AVERAGE","COUNT","MAX"],"a":0,"e":"SUM 함수는 지정한 셀 범위의 합계를 계산한다. AVERAGE는 평균, COUNT는 개 수, MAX는 최댓값을 구하는 함수이다."},{"id":"w1-20","r":1,"n":20,"s":"A","q":"다음 중 일반적으로 스프레드시트 프로그램에서 제공하는 기능으로, 워드프로세서의 기본 기능이 아닌 것은?","code":"","o":["맞춤법 검사","매크로","상용구","피벗 테이블"],"a":3,"e":"맞춤법 검사, 매크로, 상용구는 워드프로세서에서도 널리 제공되는 기능이다. 피벗 테이블은 대량의 데이터를 요약·분석하는 스프레드시트 프로그램의 대표적인 기능이다."},{"id":"w1-21","r":1,"n":21,"s":"A","q":"다음 중 유틸리티 프로그램의 일반적인 목적으로 옳지 않은 것은?","code":"","o":["파일 압축","바이러스 검사","시스템 최적화","프로그래밍 언어 컴파일"],"a":3,"e":"유틸리티 프로그램은 파일 압축, 바이러스 검사, 시스템 최적화 등 컴퓨터 관리와 성능 향상을 돕는 프로그램이다. 프로그래밍 언어를 기계어로 번역(컴파일)하는 것은 컴파일러의 역할이다."},{"id":"w1-22","r":1,"n":22,"s":"A","q":"인터넷에서 사람이 이해하기 쉬운 도메인 이름을 컴퓨터가 인식하는 IP 주소로 변환해주는 시스템은?","code":"","o":["DNS","FTP","HTTP","DHCP"],"a":0,"e":"DNS(Domain Name System)는 도메인 이름과 IP 주소를 매핑하여 상호 변환해주는 시스템이다."},{"id":"w1-23","r":1,"n":23,"s":"A","q":"다음 중 전자우편(이메일)과 관련된 프로토콜이 아닌 것은?","code":"","o":["SMTP","POP3","IMAP","FTP"],"a":3,"e":"SMTP는 메일 발송, POP3와 IMAP은 메일 수신에 사용되는 프로토콜이다. FTP는 파일 전송을 위한 프로토콜로 전자우편과 직접적인 관련이 없다."},{"id":"w1-24","r":1,"n":24,"s":"A","q":"윈도우 탐색기에서 서로 떨어져 있는 여러 개의 파일을 동시에 선택할 때 함께 눌러야 하는 키는?","code":"","o":["Ctrl","Alt","Tab","Esc"],"a":0,"e":"Ctrl 키를 누른 상태로 파일을 클릭하면 떨어져 있는 여러 파일을 동시에 선택할 수 있다. 인접한 범위를 한 번에 선택할 때는 Shift 키를 사용한다."},{"id":"w1-25","r":1,"n":25,"s":"A","q":"다음 중 압축 파일의 확장자로 옳지 않은 것은?","code":"","o":[".zip",".rar",".7z",".exe"],"a":3,"e":".zip, .rar, .7z는 대표적인 압축 파일 확장자이다. .exe는 실행 파일의 확장자이다."},{"id":"w1-26","r":1,"n":26,"s":"A","q":"스프레드시트에서 지정한 조건에 맞는 값들만 골라 합산하는 함수는?","code":"","o":["SUMIF","VLOOKUP","COUNTA","ROUND"],"a":0,"e":"SUMIF 함수는 조건 범위와 조건, 합계 범위를 지정하여 조건을 만족하는 값들만 합산한다. VLOOKUP은 값 검색, COUNTA는 비어있지 않은 셀의 개수, ROUND는 반올림 함수이다."},{"id":"w1-27","r":1,"n":27,"s":"A","q":"다음 중 인터넷 기반의 클라우드 저장소 서비스가 아닌 것은?","code":"","o":["구글 드라이브","원드라이브","드롭박스","포토샵"],"a":3,"e":"구글 드라이브, 원드라이브, 드롭박스는 파일을 온라인에 저장하고 동기화하는 클라우드 저장소 서비스이다. 포토샵은 이미지 편집 소프트웨어이다."},{"id":"w1-28","r":1,"n":28,"s":"A","q":"다음 중 전원이 꺼져도 저장된 내용이 유지되는 비휘발성 기억장치에 해당하는 것은?","code":"","o":["RAM","HDD","캐시메모리","레지스터"],"a":1,"e":"HDD(하드디스크)는 전원이 차단되어도 데이터가 유지되는 비휘발성 보조기억장치이다. RAM, 캐시메모리, 레지스터는 전원이 꺼지면 저장된 내용이 사라지는 휘발성 기억장치이다."},{"id":"w1-29","r":1,"n":29,"s":"A","q":"다음 중 운영체제(Operating System)의 일반적인 기능에 해당하지 않는 것은?","code":"","o":["프로세스 관리","기억장치 관리","파일 관리","웹 페이지 디자인"],"a":3,"e":"운영체제는 프로세스 관리, 기억장치 관리, 파일 관리, 장치 관리 등을 담당한다. 웹 페이지 디자인은 운영체제의 기능이 아니라 응용 소프트웨어(웹 디자인 도구)의 영역이다."},{"id":"w1-30","r":1,"n":30,"s":"A","q":"대부분의 인터넷 브라우저에서 바로 이전에 보던 페이지로 이동할 때 사용하는 단축키는?","code":"","o":["Alt+왼쪽 화살표","Ctrl+P","F5","Ctrl+D"],"a":0,"e":"Alt+왼쪽 화살표는 브라우저에서 이전 페이지로 이동하는 단축키이다. Ctrl+P는 인쇄, F5는 새로고침, Ctrl+D는 즐겨찾기 추가 단축키이다."},{"id":"w1-31","r":1,"n":31,"s":"S","q":"다음 중 테이블 자체를 완전히 삭제할 때 사용하는 SQL 명령어는?","code":"","o":["DROP TABLE","DELETE","TRUNCATE","ALTER"],"a":0,"e":"DROP TABLE은 테이블의 구조와 데이터를 모두 삭제하는 명령어이다. DELETE는 데이터(행)만 삭제하며 테이블 구조는 남고, TRUNCATE는 데이터만 빠르게 전체 삭제하지만 테이블은 유지된다. ALTER는 테이블 구조를 변경하는 명령어이다."},{"id":"w1-32","r":1,"n":32,"s":"S","q":"위 SQL문의 실행 결과 반환되는 행(row)의 수는?\n다음과 같은 EMPLOYEE 테이블이 있다. NAME(김철수, 영업부, 3000) / (이영희, 개발부, 3500) / (박민수, 영업부, 2800) / (최지훈, 개발부, 4000)","code":"SELECT * FROM EMPLOYEE WHERE DEPT = '영업부';","o":["1행","2행","3행","4행"],"a":1,"e":"DEPT가 '영업부'인 행은 김철수, 박민수 두 명이므로 결과는 2행이 반환된다."},{"id":"w1-33","r":1,"n":33,"s":"S","q":"위 SQL문의 실행 결과는?\n문제 32와 동일한 EMPLOYEE 테이블을 사용한다.","code":"SELECT AVG(SALARY) FROM EMPLOYEE WHERE DEPT = '개발부';","o":["3500","3750","3800","4000"],"a":1,"e":"개발부는 이영희(3500), 최지훈(4000) 두 명이다. 평균은 (3500+4000)/2 = 3750이다."},{"id":"w1-34","r":1,"n":34,"s":"S","q":"다음 중 SQL의 DML(데이터 조작어)에 해당하지 않는 명령어는?","code":"","o":["SELECT","INSERT","UPDATE","CREATE"],"a":3,"e":"SELECT, INSERT, UPDATE, DELETE는 데이터를 조작하는 DML 명령어이다. CREATE는 테이블이나 데이터베이스 객체를 정의하는 DDL(데이터 정의어) 명령어이다."},{"id":"w1-35","r":1,"n":35,"s":"S","q":"기본키(Primary Key)의 특징으로 옳지 않은 것은?","code":"","o":["NULL 값을 허용하지 않는다","중복된 값을 허용하지 않는다","테이블당 여러 개를 지정할 수 있다","각 행(레코드)을 유일하게 식별한다"],"a":2,"e":"기본키는 한 테이블에 오직 하나만 지정할 수 있다. NULL 값과 중복 값을 허용하지 않으며, 각 행을 유일하게 식별하는 역할을 한다."},{"id":"w1-36","r":1,"n":36,"s":"S","q":"두 테이블에서 조인 조건을 만족하는(공통된 값을 가진) 행만 결합하여 반환하는 조인 방식은?","code":"","o":["INNER JOIN","LEFT OUTER JOIN","RIGHT OUTER JOIN","FULL OUTER JOIN"],"a":0,"e":"INNER JOIN(내부 조인)은 두 테이블에서 조인 조건을 만족하는 행만 결합하여 반환한다. OUTER JOIN 계열은 조건을 만족하지 않는 행도 NULL을 채워 포함시킨다."},{"id":"w1-37","r":1,"n":37,"s":"S","q":"다음 중 SQL의 집계 함수(Aggregate Function)에 해당하지 않는 것은?","code":"","o":["SUM","COUNT","AVG","WHERE"],"a":3,"e":"SUM, COUNT, AVG, MAX, MIN은 그룹화된 데이터에 대해 계산을 수행하는 집계 함수이다. WHERE는 조건을 지정하는 절이며 함수가 아니다."},{"id":"w1-38","r":1,"n":38,"s":"S","q":"GROUP BY로 그룹화된 결과에 대해 조건을 적용할 때 사용하는 절은?","code":"","o":["WHERE","HAVING","ORDER BY","DISTINCT"],"a":1,"e":"HAVING 절은 GROUP BY로 그룹화된 결과(집계 결과)에 조건을 적용한다. WHERE 절은 그룹화 이전의 개별 행에 조건을 적용한다는 점에서 차이가 있다."},{"id":"w1-39","r":1,"n":39,"s":"S","q":"SQL에서 조회 결과를 특정 컬럼 기준으로 오름차순 정렬할 때 사용하는 절은?","code":"","o":["GROUP BY","ORDER BY ASC","HAVING","DISTINCT"],"a":1,"e":"ORDER BY 절은 결과를 정렬하며, ASC는 오름차순(기본값), DESC는 내림차순을 의미한다."},{"id":"w1-40","r":1,"n":40,"s":"S","q":"다음 중 SQL의 DCL(데이터 제어어)에 해당하는 명령어는?","code":"","o":["SELECT","GRANT","INSERT","ALTER"],"a":1,"e":"GRANT는 사용자에게 권한을 부여하는 DCL 명령어이다. REVOKE와 함께 대표적인 DCL 명령어로 분류된다."},{"id":"w1-41","r":1,"n":41,"s":"S","q":"트랜잭션 수행 중 발생한 변경 사항을 취소하고 이전 상태로 되돌리는 명령어는?","code":"","o":["COMMIT","ROLLBACK","SAVEPOINT","GRANT"],"a":1,"e":"ROLLBACK은 트랜잭션에서 수행한 변경 사항을 취소하고 트랜잭션 시작 이전(또는 지정된 저장점)의 상태로 되돌리는 TCL(트랜잭션 제어어) 명령어이다."},{"id":"w1-42","r":1,"n":42,"s":"S","q":"중복된 값은 허용하지 않지만, 기본키로 지정되지 않은 일반 컬럼에도 적용할 수 있는 제약조건은?","code":"","o":["PRIMARY KEY","UNIQUE","FOREIGN KEY","CHECK"],"a":1,"e":"UNIQUE 제약조건은 해당 컬럼에 중복된 값이 입력되는 것을 방지하며, 기본키가 아닌 컬럼에도 자유롭게 지정할 수 있다."},{"id":"w1-43","r":1,"n":43,"s":"S","q":"다른 SQL문 내부에 포함되어 함께 실행되는 SELECT문을 무엇이라 하는가?","code":"","o":["트리거","서브쿼리","뷰","인덱스"],"a":1,"e":"서브쿼리(Subquery)는 하나의 SQL문 안에 포함된 또 다른 SELECT문으로, 메인 쿼리의 조건을 계산하거나 값을 제공하는 역할을 한다."},{"id":"w1-44","r":1,"n":44,"s":"S","q":"인덱스(Index)를 생성하여 얻는 가장 주된 효과는?","code":"","o":["데이터 조회 속도 향상","데이터 삭제 편의성 증가","테이블 자동 생성","데이터 자동 압축"],"a":0,"e":"인덱스는 특정 컬럼에 대한 검색을 빠르게 하기 위한 자료구조로, 데이터 조회 (SELECT) 속도를 크게 향상시킨다. 다만 인덱스가 많아지면 데이터 삽입·수정·삭제 속도는 오히려 저하될 수 있다."},{"id":"w1-45","r":1,"n":45,"s":"S","q":"실제 데이터를 저장하지 않고, 하나 이상의 테이블로부터 정의되는 가상의 테이블은?","code":"","o":["인덱스","트리거","뷰(VIEW)","스키마"],"a":2,"e":"뷰(VIEW)는 하나 이상의 테이블(또는 다른 뷰)을 기반으로 정의된 가상의 테이블로, 실제 데이터를 저장하지 않고 SELECT문의 결과를 보여주는 역할을 한다."},{"id":"w1-46","r":1,"n":46,"s":"I","q":"프로세스의 상태 중, CPU를 할당받아 명령을 실제로 수행하고 있는 상태는?","code":"","o":["준비(Ready)","실행(Running)","대기(Waiting)","종료(Terminated)"],"a":1,"e":"실행(Running) 상태는 프로세스가 CPU를 할당받아 실제로 명령을 처리하고 있는 상태를 의미한다. 준비 상태는 CPU 할당을 기다리는 상태, 대기 상태는 입출력 등의 이벤트를 기다리는 상태이다."},{"id":"w1-47","r":1,"n":47,"s":"I","q":"OSI 7계층 중, 여러 네트워크 간의 최적 경로 설정(라우팅)을 담당하는 계층은?","code":"","o":["물리 계층","데이터링크 계층","네트워크 계층","전송 계층"],"a":2,"e":"네트워크 계층(3계층)은 IP 주소를 기반으로 데이터의 경로를 설정하는 라우팅 기능을 담당한다."},{"id":"w1-48","r":1,"n":48,"s":"I","q":"TCP/IP 프로토콜 중, 연결형 통신으로 신뢰성 있는 데이터 전송을 보장하는 프로토콜은?","code":"","o":["TCP","UDP","IP","ARP"],"a":0,"e":"TCP는 3-way handshake를 통해 연결을 확립하고, 순서 제어와 오류 검출·재전송 을 수행하여 신뢰성 있는 데이터 전송을 보장한다. UDP는 비연결형으로 속도는 빠르지만 신뢰성을 보장하지 않는다."},{"id":"w1-49","r":1,"n":49,"s":"I","q":"데이터베이스 정규화(Normalization)의 목적으로 옳지 않은 것은?","code":"","o":["데이터 중복 최소화","삽입/삭제/갱신 이상 방지","데이터 무결성 유지","조회 속도의 무조건적인 향상"],"a":3,"e":"정규화는 데이터 중복을 최소화하고 삽입·삭제·갱신 이상을 방지하여 데이터 무결성 을 유지하는 것이 목적이다. 다만 정규화가 지나치면 조인이 늘어나 오히려 조회 속도가 저하될 수 있으므로, 조회 속도를 무조건적으로 향상시킨다는 설명은 옳지 않다."},{"id":"w1-50","r":1,"n":50,"s":"I","q":"소프트웨어 생명주기 모델 중, 폭포수(Waterfall) 모델의 특징으로 옳은 것은?","code":"","o":["각 단계가 순차적으로 진행된다","반복적 개발이 기본 원칙이다","요구사항 변경이 자유롭다","애자일 방법론의 한 종류이다"],"a":0,"e":"폭포수 모델은 요구사항 분석-설계-구현-테스트-유지보수의 각 단계를 순차적으로 진행하며, 이전 단계로 되돌아가기 어려운 특징을 갖는다."},{"id":"w1-51","r":1,"n":51,"s":"I","q":"다음 중 보조기억장치에 해당하는 것은?","code":"","o":["RAM","캐시메모리","HDD","레지스터"],"a":2,"e":"HDD(하드디스크)는 대용량 데이터를 영구적으로 저장하는 보조기억장치이다. RAM, 캐시메모리, 레지스터는 CPU와 가깝게 위치한 주기억장치 또는 그 이상 고속의 기억장치이다."},{"id":"w1-52","r":1,"n":52,"s":"I","q":"프로세스 스케줄링 기법 중, 준비 큐에 도착한 순서대로 CPU를 할당하는 가장 단순한 기법은?","code":"","o":["FCFS","SJF","라운드로빈","우선순위"],"a":0,"e":"FCFS(First Come First Served)는 준비 큐에 먼저 도착한 프로세스에게 먼저 CPU를 할당하는 비선점 스케줄링 기법이다."},{"id":"w1-53","r":1,"n":53,"s":"I","q":"네트워크 장비 중, 서로 다른 네트워크를 연결하며 IP 주소를 기반으로 최적의 경로를 선택하는 장비는?","code":"","o":["허브","스위치","라우터","리피터"],"a":2,"e":"라우터는 서로 다른 네트워크(LAN과 LAN, 또는 LAN과 인터넷)를 연결하고, IP 주소를 기준으로 최적의 경로를 선택하여 패킷을 전달하는 장비이다."},{"id":"w1-54","r":1,"n":54,"s":"I","q":"관계형 데이터베이스에서 한 테이블의 외래키(Foreign Key)가 참조하는 대상은 일반적으로 무엇인가?","code":"","o":["다른 테이블의 기본키","자기 테이블의 인덱스","뷰(VIEW)","트리거"],"a":0,"e":"외래키는 다른 테이블의 기본키(또는 유일하게 식별 가능한 컬럼)를 참조하여 두 테이블 간의 관계를 나타내는 제약조건이다."},{"id":"w1-55","r":1,"n":55,"s":"I","q":"클라우드 컴퓨팅 서비스 모델 중, 운영체제와 애플리케이션 실행·개발 환경까지 함께 제공하는 모델은?","code":"","o":["IaaS","PaaS","SaaS","DaaS"],"a":1,"e":"PaaS(Platform as a Service)는 하드웨어 인프라뿐만 아니라 운영체제와 개발·실 행 환경(플랫폼)까지 제공하는 서비스 모델이다. IaaS는 인프라만, SaaS는 완성된 소프트웨어까지 제공한다."},{"id":"w1-56","r":1,"n":56,"s":"I","q":"빅데이터의 대표적인 특징을 설명하는 3V에 해당하지 않는 것은?","code":"","o":["Volume","Velocity","Variety","Virtualization"],"a":3,"e":"빅데이터의 3V는 데이터의 양(Volume), 생성·처리 속도(Velocity), 형태의 다양성 (Variety)을 의미한다. Virtualization(가상화)은 3V에 포함되지 않는다."},{"id":"w1-57","r":1,"n":57,"s":"I","q":"IP 주소 고갈 문제를 해결하기 위해 등장한, 기존 IPv4를 대체하는 128비트 주소 체계는?","code":"","o":["IPv6","MAC 주소","서브넷 마스크","포트 번호"],"a":0,"e":"IPv6는 32비트인 IPv4의 주소 고갈 문제를 해결하기 위해 등장한 128비트 주소 체계로, 훨씬 더 많은 수의 주소를 제공한다."},{"id":"w1-58","r":1,"n":58,"s":"I","q":"다음 중 화이트박스 테스트 기법에 해당하는 것은?","code":"","o":["동등 분할","경계값 분석","기초 경로 검사","결정 테이블"],"a":2,"e":"기초 경로 검사(Basic Path Testing)는 프로그램 내부의 논리적 흐름(순환 복잡도) 을 기반으로 하는 화이트박스 테스트 기법이다. 동등 분할, 경계값 분석, 결정 테이블은 명세를 기반으로 하는 블랙박스 테스트 기법이다."},{"id":"w1-59","r":1,"n":59,"s":"I","q":"운영체제의 메모리 관리 기법 중, 프로세스와 메모리를 일정한 크기의 블록(페이지) 단위로 나누어 관리하는 기법은?","code":"","o":["페이징(Paging)","세그멘테이션(Segmentation)","스와핑(Swapping)","캐싱(Caching)"],"a":0,"e":"페이징은 프로세스와 물리 메모리를 동일한 크기의 페이지·프레임 단위로 나누어 관리하는 기법이다. 세그멘테이션은 논리적 의미 단위(가변 크기)로 나누어 관리하는 기법이다."},{"id":"w1-60","r":1,"n":60,"s":"I","q":"다음 중 최신 IT 기술 동향에 해당하지 않는 것은?","code":"","o":["인공지능(AI)","사물인터넷(IoT)","블록체인","플로피디스크"],"a":3,"e":"인공지능, 사물인터넷, 블록체인은 최근 주목받는 IT 기술 동향이다. 플로피디스크는 과거에 사용되던 저용량 이동식 저장 매체로, 현재는 거의 사용되지 않는 구식 기술이다."},{"id":"w2-01","r":2,"n":1,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int arr[5] = {2, 4, 6, 8, 10};\n      int sum = 0;\n      for (int i = 0; i < 5; i++) sum += arr[i];\n      printf(\"%d\", sum / 5);\n      return 0;\n}","o":["5","6","7","8"],"a":1,"e":"배열의 합은 2+4+6+8+10=30이다. 정수형 나눗셈이므로 30 / 5 = 6이 출력된다."},{"id":"w2-02","r":2,"n":2,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"class Animal {\n      void sound() { System.out.println(\"동물 소리\"); }\n}\nclass Dog extends Animal {\n      void sound() { System.out.println(\"멍멍\"); }\n}\npublic class Test {\n      public static void main(String[] args) {\n           Animal a = new Dog();\n           a.sound();\n      }\n}","o":["동물 소리","멍멍","컴파일 오류","아무것도 출력되지 않음"],"a":1,"e":"참조 변수 a의 타입은 Animal이지만 실제 객체는 Dog이다. 오버라이딩(재정의)된 메서드는 실제 객체(Dog)의 것이 호출되는 다형성이 적용되어 \"멍멍\"이 출력된다."},{"id":"w2-03","r":2,"n":3,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"nums = [1, 2, 3, 4, 5]\nresult = [x * 2 for x in nums if x % 2 == 0]\nprint(result)","o":["[2, 4, 6, 8, 10]","[4, 8]","[2, 4]","[1, 3, 5]"],"a":1,"e":"리스트 컴프리헨션에서 x % 2 == 0 조건을 만족하는 짝수(2, 4)만 선택하여 2배로 만든다. 결과는 [4, 8]이다."},{"id":"w2-04","r":2,"n":4,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\n#include <string.h>\nint main() {\n      char str[20] = \"Hello\";\n      strcat(str, \" World\");\n      printf(\"%d\", strlen(str));\n      return 0;\n}","o":["5","6","10","11"],"a":3,"e":"strcat 함수는 str 뒤에 \" World\"를 이어 붙여 \"Hello World\"를 만든다. strlen로 계산한 이 문자열의 길이는 공백을 포함하여 11이다."},{"id":"w2-05","r":2,"n":5,"s":"P","q":"다음 중 Java에서 배열의 크기(길이)를 구할 때 사용하는 것은?","code":"","o":["length","length()","size","size()"],"a":0,"e":"Java에서 배열은 length라는 속성(필드)을 통해 크기를 확인한다. 문자열은 length() 메서드, 컬렉션(List 등)은 size() 메서드를 사용한다는 점에서 구분해야 한다."},{"id":"w2-06","r":2,"n":6,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"def fib(n):\n       if n <= 1:\n           return n\n       return fib(n-1) + fib(n-2)\n\nprint(fib(6))","o":["5","6","8","13"],"a":2,"e":"피보나치 수열은 0,1,1,2,3,5,8,...이다. fib(6)은 여섯 번째 항(0번째부터 시작)인 8이다."},{"id":"w2-07","r":2,"n":7,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n       int a = 2, b = 3, c = 4;\n       int result = a + b * c;\n       printf(\"%d\", result);\n       return 0;\n}","o":["14","20","24","9"],"a":0,"e":"연산자 우선순위에 따라 곱셈(*)이 덧셈(+)보다 먼저 계산된다. b*c = 12이고, a + 12 = 2 + 12 = 14이다."},{"id":"w2-08","r":2,"n":8,"s":"P","q":"다음 중 Java의 원시 자료형(Primitive Type)에 해당하지 않는 것은?","code":"","o":["int","boolean","String","double"],"a":2,"e":"int, boolean, double은 Java의 8가지 원시 자료형에 포함된다. String은 클래스로 정의된 참조 자료형(객체)이다."},{"id":"w2-09","r":2,"n":9,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"a = \"10\"\nb = 5\nprint(int(a) + b)","o":["105","15","10","오류 발생"],"a":1,"e":"int(a)는 문자열 \"10\"을 정수 10으로 형변환한다. 10 + 5 = 15가 출력된다."},{"id":"w2-10","r":2,"n":10,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int x = 2;\n      switch (x) {\n            case 1: printf(\"one\"); break;\n            case 2: printf(\"two\");\n            case 3: printf(\"three\"); break;\n            default: printf(\"default\");\n      }\n      return 0;\n}","o":["two","twothree","onetwothree","default"],"a":1,"e":"x가 2이므로 case 2로 진입하여 \"two\"를 출력한다. case 2에는 break문이 없으므로 아래의 case 3까지 순차적으로 실행(fall-through)되어 \"three\"도 출력된다. 결과는 \"twothree\"이다."},{"id":"w2-11","r":2,"n":11,"s":"P","q":"Java에서 두 문자열 변수의 내용이 같은지 올바르게 비교하는 방법은?","code":"","o":["== 연산자 사용","equals() 메서드 사용","compareTo()의 반환값만으로 판단","length()로만 비교"],"a":1,"e":"Java의 == 연산자는 객체의 참조(주소)를 비교하므로 문자열의 내용 비교에는 적합 하지 않다. 문자열의 내용이 같은지 비교할 때는 equals() 메서드를 사용해야 한다."},{"id":"w2-12","r":2,"n":12,"s":"P","q":"다음 중 Python의 튜플(tuple)에 대한 설명으로 옳은 것은?","code":"","o":["값을 변경할 수 있다","소괄호 ( )를 사용해 생성한다","항목의 순서가 없다","중복된 값을 허용하지 않는다"],"a":1,"e":"튜플은 소괄호를 사용해 생성하는 자료형으로, 리스트와 달리 한 번 생성되면 값을 변경할 수 없는 불변(immutable) 자료형이다. 순서가 있으며 중복된 값도 허용한다."},{"id":"w2-13","r":2,"n":13,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int arr[2][3] = {{1, 2, 3}, {4, 5, 6}};\n      printf(\"%d\", arr[1][2]);\n      return 0;\n}","o":["3","4","5","6"],"a":3,"e":"arr[1]은 두 번째 행인 {4, 5, 6}이며, arr[1][2]는 그 행의 세 번째(인덱스 2) 값인 6 이다."},{"id":"w2-14","r":2,"n":14,"s":"P","q":"사용자로부터 텍스트를 입력받는 입력창을 만들 때 사용하는 HTML 코드는?","code":"","o":["<input type=\"text\">","<select>","<label>","<form>"],"a":0,"e":"<input type=\"text\">는 한 줄의 텍스트를 입력받는 입력창을 생성한다. <select> 는 드롭다운 목록, <label>은 입력 요소의 이름표, <form>은 입력 요소들을 묶는 폼 태그이다."},{"id":"w2-15","r":2,"n":15,"s":"P","q":"CSS에서 id 속성 값이 'header'인 요소 하나만 선택할 때 사용하는 선택자는?","code":"","o":[".header","#header","header","*header"],"a":1,"e":"CSS에서 id 선택자는 '#' 기호를 사용한다. 클래스 선택자는 '.'(마침표)를 사용하며, 태그 이름만 쓰면 해당 태그 전체를 선택하는 것이다."},{"id":"w2-16","r":2,"n":16,"s":"A","q":"워드프로세서에서 자주 사용하는 문자나 문구를 미리 등록해 두고 필요할 때 간단히 불러와 사용하는 기능은?","code":"","o":["매크로","상용구","맞춤법 검사","메일 머지"],"a":1,"e":"상용구는 자주 쓰는 단어나 문장을 미리 등록해두고 짧은 코드로 빠르게 불러와 입력 하는 기능이다."},{"id":"w2-17","r":2,"n":17,"s":"A","q":"다음 중 백신(안티바이러스) 프로그램의 주요 기능으로 옳지 않은 것은?","code":"","o":["바이러스 검사","실시간 감시","악성코드 치료","파일 압축"],"a":3,"e":"백신 프로그램은 바이러스 검사, 실시간 감시, 악성코드 치료 및 격리 기능을 제공한다. 파일 압축은 별도의 압축 유틸리티의 기능이다."},{"id":"w2-18","r":2,"n":18,"s":"A","q":"대부분의 프로그램에서 Ctrl+C를 누른 후 Ctrl+V를 누르면 수행되는 작업은?","code":"","o":["복사 후 붙여넣기","잘라내기 후 붙여넣기","실행 취소 후 다시 실행","저장 후 인쇄"],"a":0,"e":"Ctrl+C는 복사(Copy), Ctrl+V는 붙여넣기(Paste)의 단축키이다. 두 동작을 연속으로 수행하면 선택한 내용을 복사한 뒤 원하는 위치에 붙여넣게 된다."},{"id":"w2-19","r":2,"n":19,"s":"A","q":"스프레드시트에서 특정 값을 첫 번째 열에서 찾아 같은 행의 다른 열 값을 반환하는 함수는?","code":"","o":["VLOOKUP","SUM","IF","COUNT"],"a":0,"e":"VLOOKUP 함수는 지정한 범위의 첫 번째 열에서 찾을 값을 검색한 뒤, 같은 행의 지정한 열 번호에 있는 값을 반환한다."},{"id":"w2-20","r":2,"n":20,"s":"A","q":"다음 중 프레젠테이션 프로그램의 일반적인 기능으로 옳지 않은 것은?","code":"","o":["슬라이드 전환 효과","애니메이션 효과","매크로 레코딩","수식 자동 재계산"],"a":3,"e":"슬라이드 전환 효과, 애니메이션, 매크로는 프레젠테이션 프로그램에서도 사용되는 기능이다. 수식을 입력하고 값이 변경될 때 자동으로 재계산하는 기능은 스프레드시트 프로그램의 핵심 기능이다."},{"id":"w2-21","r":2,"n":21,"s":"A","q":"PC의 저장 공간을 확보하기 위해 임시 파일이나 불필요한 파일을 찾아 삭제하는 윈도우 기본 유틸리티는?","code":"","o":["디스크 정리","장치 관리자","작업 관리자","제어판"],"a":0,"e":"디스크 정리(Disk Cleanup)는 임시 파일, 휴지통 파일, 다운로드한 프로그램 파일 등 불필요한 파일을 찾아 삭제하여 저장 공간을 확보해 주는 윈도우 기본 유틸리티이다."},{"id":"w2-22","r":2,"n":22,"s":"A","q":"웹 주소(URL)에서 'https'의 's'가 의미하는 것은?","code":"","o":["속도(Speed)","보안(Secure)","서버(Server)","시스템(System)"],"a":1,"e":"'https'의 's'는 Secure(보안)를 의미하며, SSL/TLS 프로토콜을 통해 데이터를 암호화하여 안전하게 통신함을 나타낸다."},{"id":"w2-23","r":2,"n":23,"s":"A","q":"다음 중 무선 네트워크 접속 방식이 아닌 것은?","code":"","o":["Wi-Fi","블루투스","LTE","RJ-45 커넥터"],"a":3,"e":"Wi-Fi, 블루투스, LTE는 무선으로 데이터를 주고받는 통신 방식이다. RJ-45는 유선랜(이더넷) 케이블에 사용되는 커넥터이다."},{"id":"w2-24","r":2,"n":24,"s":"A","q":"윈도우에서 열려 있는 모든 창을 한 번에 최소화하여 바탕화면을 표시할 때 사용하는 단축키는?","code":"","o":["Win+D","Win+E","Win+L","Win+R"],"a":0,"e":"Win+D는 열려 있는 모든 창을 최소화하고 바탕화면을 표시하는 단축키이다. Win+E는 파일 탐색기 실행, Win+L은 화면 잠금, Win+R은 실행 창을 여는 단축키이다."},{"id":"w2-25","r":2,"n":25,"s":"A","q":"다음 중 컴퓨터 파일 시스템의 종류에 해당하지 않는 것은?","code":"","o":["FAT32","NTFS","exFAT","HTTP"],"a":3,"e":"FAT32, NTFS, exFAT는 저장장치의 파일을 관리하는 파일 시스템이다. HTTP는 웹에서 데이터를 주고받는 통신 프로토콜로 파일 시스템이 아니다."},{"id":"w2-26","r":2,"n":26,"s":"A","q":"스프레드시트에서 셀 안에 입력된 긴 텍스트를 셀 너비에 맞추어 여러 줄로 표시하는 기능은?","code":"","o":["텍스트 줄바꿈","셀 병합","조건부 서식","자동 필터"],"a":0,"e":"텍스트 줄바꿈(Wrap Text) 기능은 셀 너비를 넘는 긴 텍스트를 셀 안에서 여러 줄로 나누어 표시해 준다."},{"id":"w2-27","r":2,"n":27,"s":"A","q":"다음 중 컴퓨터 바이러스 감염 경로로 가장 거리가 먼 것은?","code":"","o":["이메일 첨부파일 실행","불법 다운로드 파일 실행","정품 소프트웨어의 정상적인 설치","출처가 불분명한 USB 저장장치 연결"],"a":2,"e":"이메일 첨부파일, 불법 다운로드, 출처가 불분명한 USB는 대표적인 바이러스 감염경로이다. 정식 인증된 정품 소프트웨어를 정상적인 절차로 설치하는 것은 감염 경로로 보기 어렵다."},{"id":"w2-28","r":2,"n":28,"s":"A","q":"운영체제가 여러 프로그램을 짧은 시간 간격으로 번갈아 실행시켜 동시에 실행되는 것처럼 보이게 하는 기능은?","code":"","o":["멀티태스킹","싱글태스킹","부팅","포맷"],"a":0,"e":"멀티태스킹(다중 작업)은 CPU 시간을 짧게 나누어 여러 프로그램에 번갈아 할당함으로써 사용자에게는 여러 프로그램이 동시에 실행되는 것처럼 보이게 하는 기능이다."},{"id":"w2-29","r":2,"n":29,"s":"A","q":"다음 중 모니터 해상도를 나타낼 때 사용하는 단위로 옳은 것은?","code":"","o":["픽셀(Pixel)","헤르츠(Hz)","바이트(Byte)","비트(bit)"],"a":0,"e":"모니터 해상도는 가로×세로의 픽셀(Pixel) 수로 표현한다(예: 1920×1080). 헤르츠는 주사율, 바이트·비트는 데이터의 용량 단위이다."},{"id":"w2-30","r":2,"n":30,"s":"A","q":"다음 중 개인정보 보호를 위한 올바른 행동으로 옳지 않은 것은?","code":"","o":["정기적인 비밀번호 변경","출처가 불분명한 첨부파일 실행","백신 프로그램 최신 업데이트 유지","공용 PC 사용 후 로그아웃 철저히 하기"],"a":1,"e":"정기적인 비밀번호 변경, 백신 최신화, 로그아웃 철저는 개인정보 보호를 위한 바람직 한 행동이다. 출처가 불분명한 첨부파일을 실행하는 것은 악성코드 감염과 개인정보 유출의 위험이 큰 행동이다."},{"id":"w2-31","r":2,"n":31,"s":"S","q":"위 SQL문의 실행 결과는?\n다음과 같은 STUDENT 테이블이 있다. (홍길동, 컴퓨터공학, 85) / (김영수, 전자공학, 90) / (이미나, 컴퓨터공학, 78) / (박서준, 전자공학, 95)","code":"SELECT COUNT(*) FROM STUDENT WHERE MAJOR = '컴퓨터공학';","o":["1","2","3","4"],"a":1,"e":"MAJOR가 '컴퓨터공학'인 학생은 홍길동, 이미나 두 명이므로 COUNT(*)의 결과는 2이다."},{"id":"w2-32","r":2,"n":32,"s":"S","q":"위 SQL문의 실행 결과는?\n문제 31과 동일한 STUDENT 테이블을 사용한다.","code":"SELECT MAX(SCORE) FROM STUDENT;","o":["85","90","95","348"],"a":2,"e":"SCORE 값 85, 90, 78, 95 중 최댓값은 95이다."},{"id":"w2-33","r":2,"n":33,"s":"S","q":"특정 컬럼에 NOT NULL 제약조건을 설정했을 때 나타나는 효과는?","code":"","o":["해당 컬럼에 NULL 값 입력을 허용하지 않는다","해당 컬럼에 중복 값을 허용하지 않는다","해당 컬럼이 자동으로 기본키가 된다","해당 컬럼의 값을 자동으로 채워준다"],"a":0,"e":"NOT NULL 제약조건은 해당 컬럼에 값이 반드시 입력되어야 하며 NULL(빈 값) 입력을 허용하지 않도록 강제하는 제약조건이다."},{"id":"w2-34","r":2,"n":34,"s":"S","q":"다음 중 가변 길이의 문자열 데이터를 저장하기 위해 사용하는 SQL 데이터 타입은?","code":"","o":["INT","VARCHAR","DATE","FLOAT"],"a":1,"e":"VARCHAR는 가변 길이 문자열을 저장하는 데이터 타입이다. INT는 정수형, DATE 는 날짜형, FLOAT는 실수형 데이터 타입이다."},{"id":"w2-35","r":2,"n":35,"s":"S","q":"SQL에서 조회 결과 중 중복된 행을 제거하고 유일한 값만 조회할 때 SELECT문에 사용하는 키워드는?","code":"","o":["DISTINCT","UNIQUE","ONLY","SINGLE"],"a":0,"e":"DISTINCT 키워드를 SELECT문에 사용하면 조회 결과에서 중복된 행을 제거하고 유일한 값만 반환한다."},{"id":"w2-36","r":2,"n":36,"s":"S","q":"하나의 테이블을 마치 두 개의 테이블처럼 자기 자신과 조인하는 방식을 무엇이라 하는가?","code":"","o":["SELF JOIN","INNER JOIN","CROSS JOIN","OUTER JOIN"],"a":0,"e":"SELF JOIN(자체 조인)은 동일한 테이블에 서로 다른 별칭(Alias)을 부여하여 자기 자신과 조인하는 방식으로, 조직도나 상하관계 데이터를 조회할 때 주로 사용된다."},{"id":"w2-37","r":2,"n":37,"s":"S","q":"이미 생성되어 있는 테이블에 새로운 컬럼을 추가하거나 삭제할 때 사용하는 SQL 명령어는?","code":"","o":["ALTER TABLE","CREATE TABLE","DROP TABLE","UPDATE TABLE"],"a":0,"e":"ALTER TABLE은 이미 존재하는 테이블의 구조(컬럼 추가·삭제·변경, 제약조건 변경 등)를 수정하는 DDL 명령어이다."},{"id":"w2-38","r":2,"n":38,"s":"S","q":"SQL에서 특정 값이 지정한 범위(최솟값과 최댓값 사이)에 속하는지 조회할 때 사용하는 연산자는?","code":"","o":["BETWEEN","LIKE","IN","IS NULL"],"a":0,"e":"BETWEEN A AND B 연산자는 값이 A 이상 B 이하의 범위에 속하는지를 조건으로 조회할 때 사용한다."},{"id":"w2-39","r":2,"n":39,"s":"S","q":"문자열 데이터에서 특정 패턴(부분 문자열)이 포함되어 있는지 검색할 때 사용하는 연산자는?","code":"","o":["BETWEEN","LIKE","IN","EXISTS"],"a":1,"e":"LIKE 연산자는 '%'(임의 길이 문자열), '_'(한 글자) 등의 와일드카드를 사용하여 문자 열의 패턴을 검색할 때 사용한다."},{"id":"w2-40","r":2,"n":40,"s":"S","q":"하나의 트랜잭션 내에서 특정 지점까지만 롤백할 수 있도록 지정하는 명령어는?","code":"","o":["COMMIT","SAVEPOINT","GRANT","REVOKE"],"a":1,"e":"SAVEPOINT는 트랜잭션 내에 임시 저장 지점을 지정하여, 전체를 롤백하지 않고 지정한 저장 지점까지만 롤백할 수 있도록 해주는 TCL 명령어이다."},{"id":"w2-41","r":2,"n":41,"s":"S","q":"사용자에게 부여했던 데이터베이스 권한을 취소(회수)할 때 사용하는 SQL 명령어는?","code":"","o":["GRANT","REVOKE","DENY","DROP"],"a":1,"e":"REVOKE는 GRANT로 부여했던 권한을 취소(회수)하는 DCL 명령어이다."},{"id":"w2-42","r":2,"n":42,"s":"S","q":"여러 개의 SELECT문 결과를 하나로 합치되, 중복된 행은 자동으로 제거하는 집합 연산자는?","code":"","o":["UNION","UNION ALL","JOIN","INTERSECT"],"a":0,"e":"UNION은 여러 SELECT문의 결과를 하나로 합치면서 중복된 행을 자동으로 제거한다. 중복을 제거하지 않고 모두 포함하려면 UNION ALL을 사용한다."},{"id":"w2-43","r":2,"n":43,"s":"S","q":"외래키(FOREIGN KEY) 제약조건을 설정하는 주된 목적은?","code":"","o":["조회 속도 향상","참조 무결성 유지","데이터 압축","인덱스 자동 생성"],"a":1,"e":"외래키는 한 테이블의 값이 다른 테이블의 기본키를 참조하도록 강제하여, 존재하지 않는 값을 참조하는 것을 방지함으로써 테이블 간의 참조 무결성을 유지하는 역할을 한다."},{"id":"w2-44","r":2,"n":44,"s":"S","q":"SQL에서 특정 컬럼의 값이 NULL인 행만 조회하고자 할 때 사용하는 조건은?","code":"","o":["컬럼명 = NULL","컬럼명 IS NULL","컬럼명 == NULL","컬럼명 <> NULL"],"a":1,"e":"SQL에서 NULL은 값이 아니라 상태를 의미하므로 등호(=)로 비교할 수 없다. NULL 여부를 확인할 때는 반드시 IS NULL(또는 IS NOT NULL)을 사용해야 한다."},{"id":"w2-45","r":2,"n":45,"s":"S","q":"다음 중 트리거(Trigger)에 대한 설명으로 가장 옳은 것은?","code":"","o":["데이터 조회 속도를 높이기 위한 자료구조이다","특정 이벤트 발생 시 자동으로 실행되는 데이터베이스 객체이다","여러 테이블을 조합한 가상의 테이블이다","사용자 권한을 관리하는 명령어이다"],"a":1,"e":"트리거는 테이블에 삽입·수정·삭제와 같은 특정 이벤트가 발생했을 때, 사용자의 명시적 호출 없이 자동으로 실행되도록 정의된 데이터베이스 객체이다."},{"id":"w2-46","r":2,"n":46,"s":"I","q":"다음 중 교착상태(Deadlock)의 발생 조건에 해당하지 않는 것은?","code":"","o":["상호 배제","점유와 대기","선점 가능","순환 대기"],"a":2,"e":"교착상태는 상호 배제, 점유와 대기, 비선점(선점 불가능), 순환 대기의 네 가지 조건이 동시에 성립할 때 발생한다. 선점이 가능하다면 자원을 강제로 회수할 수 있으므로 교착상태가 발생하지 않는다."},{"id":"w2-47","r":2,"n":47,"s":"I","q":"OSI 7계층 중, 데이터의 형식 변환·암호화·압축 등을 담당하는 계층은?","code":"","o":["세션 계층","표현 계층","응용 계층","전송 계층"],"a":1,"e":"표현 계층(6계층)은 송수신 데이터의 형식을 변환하고 암호화·압축 등을 처리하여 응용 계층이 이해할 수 있는 형태로 데이터를 표현하는 역할을 한다."},{"id":"w2-48","r":2,"n":48,"s":"I","q":"다음 중 사설(Private) IP 주소 대역에 해당하는 것은?","code":"","o":["192.168.0.1","8.8.8.8","172.217.0.1","1.1.1.1"],"a":0,"e":"192.168.0.0~192.168.255.255 대역은 내부 네트워크에서 사용하는 대표적인 사설 IP 주소 대역이다. 나머지는 공인(Public) IP 주소의 예시이다."},{"id":"w2-49","r":2,"n":49,"s":"I","q":"데이터베이스 설계 단계 중, 개체와 개체 간의 관계를 개체-관계 다이어그램(ERD)으로 표현하는 단계는?","code":"","o":["개념적 설계","논리적 설계","물리적 설계","구현 단계"],"a":0,"e":"개념적 설계 단계에서는 현실 세계의 데이터를 개체(Entity)와 관계(Relationship) 로 추상화하여 ERD로 표현한다. 이후 논리적 설계에서 이를 테이블(릴레이션) 구조로 변환한다."},{"id":"w2-50","r":2,"n":50,"s":"I","q":"짧은 개발 주기를 반복하며 고객과의 피드백을 중시하는 소프트웨어 개발 방법론은?","code":"","o":["폭포수 모델","애자일(Agile)","V모델","나선형 모델"],"a":1,"e":"애자일 방법론은 짧은 주기(스프린트)로 반복적인 개발과 배포를 수행하며, 고객의 피드백을 지속적으로 반영하는 것을 핵심 가치로 삼는다."},{"id":"w2-51","r":2,"n":51,"s":"I","q":"CPU 스케줄링 기법 중, 실행 시간이 가장 짧은 프로세스를 우선적으로 처리하는 기법은?","code":"","o":["FCFS","SJF","라운드로빈","우선순위"],"a":1,"e":"SJF(Shortest Job First)는 실행에 필요한 시간이 가장 짧은 프로세스를 우선적으로 처리하여 평균 대기 시간을 최소화하는 스케줄링 기법이다."},{"id":"w2-52","r":2,"n":52,"s":"I","q":"다량의 트래픽을 특정 서버에 집중시켜 정상적인 서비스를 마비시키는 네트워크 공격은?","code":"","o":["피싱(Phishing)","DDoS","SQL 인젝션","스니핑"],"a":1,"e":"DDoS(분산 서비스 거부 공격)는 다수의 좀비 PC 등을 이용해 대량의 트래픽을 특정 서버에 집중시켜 정상적인 서비스 제공을 마비시키는 공격이다."},{"id":"w2-53","r":2,"n":53,"s":"I","q":"관계형 데이터베이스에서 하나의 속성(컬럼)이 취할 수 있는 값들의 범위를 무엇이라 하는가?","code":"","o":["도메인(Domain)","튜플(Tuple)","릴레이션(Relation)","스키마(Schema)"],"a":0,"e":"도메인은 하나의 속성이 가질 수 있는 값의 범위(값의 집합)를 의미한다. 예를 들어 \"성별\" 속성의 도메인은 {남, 여}가 될 수 있다."},{"id":"w2-54","r":2,"n":54,"s":"I","q":"다음 중 가상 메모리(Virtual Memory) 기법을 사용하는 주된 목적은?","code":"","o":["실제 물리 메모리보다 큰 프로그램을 실행할 수 있도록 지원","CPU의 처리 속도를 높이기 위해","네트워크 전송 속도를 높이기 위해","파일을 압축하여 저장하기 위해"],"a":0,"e":"가상 메모리는 보조기억장치의 일부를 마치 주기억장치처럼 사용하도록 하여, 실제 물리적인 메모리 용량보다 큰 프로그램도 실행할 수 있도록 지원하는 기법이다."},{"id":"w2-55","r":2,"n":55,"s":"I","q":"소프트웨어 테스트 중, 사용자가 실제 운영 환경과 유사한 조건에서 최종적으로 수행하는 테스트는?","code":"","o":["단위 테스트","통합 테스트","시스템 테스트","인수 테스트"],"a":3,"e":"인수 테스트는 개발 프로세스의 가장 마지막 단계에서 실제 사용자가 요구사항 충족 여부를 최종적으로 확인하는 테스트이다."},{"id":"w2-56","r":2,"n":56,"s":"I","q":"다음 중 사물인터넷(IoT)의 특징으로 옳지 않은 것은?","code":"","o":["사물 간의 인터넷 연결","센서를 통한 데이터 수집","실시간 데이터 처리","오프라인 환경에서만 동작"],"a":3,"e":"IoT는 다양한 사물이 인터넷에 연결되어 센서 데이터를 수집하고 실시간으로 처리·공유하는 기술이다. 인터넷 연결이 핵심 요소이므로 오프라인 환경에서만 동작한다는 설명은 옳지 않다."},{"id":"w2-57","r":2,"n":57,"s":"I","q":"하나의 송신자가 특정 다수의 수신자 그룹에게만 데이터를 전송하는 네트워크 전송 방식은?","code":"","o":["유니캐스트","멀티캐스트","브로드캐스트","애니캐스트"],"a":1,"e":"멀티캐스트는 하나의 송신자가 미리 지정된 특정 그룹의 여러 수신자에게만 데이터를 전송하는 방식이다. 브로드캐스트는 네트워크 내 모든 호스트에게, 유니캐스트는 단일 수신자에게 전송하는 방식이다."},{"id":"w2-58","r":2,"n":58,"s":"I","q":"다음 중 화이트박스 테스트의 커버리지 기법에 해당하지 않는 것은?","code":"","o":["구문 커버리지","결정 커버리지","조건 커버리지","경계값 분석"],"a":3,"e":"구문 커버리지, 결정 커버리지, 조건 커버리지는 코드 내부 구조를 기준으로 하는 화이트박스 테스트 기법이다. 경계값 분석은 입력값의 경계를 기준으로 하는 블랙박스(명세 기반) 테스트 기법이다."},{"id":"w2-59","r":2,"n":59,"s":"I","q":"운영체제에서 서로 다른 프로세스 간의 자원 공유와 정보 교환을 위한 기법을 통칭하는 용어는?","code":"","o":["IPC(프로세스 간 통신)","스케줄링","페이징","스풀링"],"a":0,"e":"IPC(Inter-Process Communication)는 여러 프로세스가 데이터를 주고받거나 자원을 공유하기 위해 사용하는 통신 기법을 통칭하는 용어이다."},{"id":"w2-60","r":2,"n":60,"s":"I","q":"다음 중 블록체인(Blockchain) 기술의 특징으로 옳지 않은 것은?","code":"","o":["분산 원장 기술","데이터 위변조 방지","중앙 서버의 단독 통제","합의 알고리즘을 통한 검증"],"a":2,"e":"블록체인은 여러 참여자가 원장을 분산하여 공동으로 관리하는 탈중앙화 기술로, 특정 중앙 서버가 단독으로 데이터를 통제하지 않는다는 것이 핵심 특징이다."},{"id":"w3-01","r":3,"n":1,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int i = 1, sum = 0;\n      while (i <= 5) {\n           sum += i * i;\n           i++;\n      }\n      printf(\"%d\", sum);\n      return 0;\n}","o":["15","30","55","225"],"a":2,"e":"1부터 5까지 각 수의 제곱을 더한다. 1+4+9+16+25 = 55이다."},{"id":"w3-02","r":3,"n":2,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"import java.util.Arrays;\npublic class Test {\n      public static void main(String[] args) {\n           int[] arr = {5, 2, 8, 1, 9};\n           Arrays.sort(arr);\n           System.out.println(arr[2]);\n      }\n}","o":["1","2","5","8"],"a":2,"e":"Arrays.sort(arr)로 오름차순 정렬하면 배열은 {1, 2, 5, 8, 9}가 된다. 인덱스 2(세 번째)의 값은 5이다."},{"id":"w3-03","r":3,"n":3,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"s = \"Programming\"\nprint(s[::-1])","o":["Programming","gnimmargorP","PROGRAMMING","ProgramminG"],"a":1,"e":"슬라이싱에서 step을 -1로 지정하면 문자열을 역순으로 뒤집는다. \"Programming\"을 뒤집으면 \"gnimmargorP\"가 된다."},{"id":"w3-04","r":3,"n":4,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint total(int arr[], int n) {\n      int sum = 0;\n      for (int i = 0; i < n; i++) sum += arr[i];\n      return sum;\n}\nint main() {\n      int a[4] = {10, 20, 30, 40};\n      printf(\"%d\", total(a, 4));\n      return 0;\n}","o":["60","80","100","120"],"a":2,"e":"total 함수는 배열의 모든 요소를 더해 반환한다. 10+20+30+40=100이다."},{"id":"w3-05","r":3,"n":5,"s":"P","q":"다음 중 C언어에서 두 값이 서로 같은지 비교할 때 사용하는 연산자는?","code":"","o":["=","==","!=","<>"],"a":1,"e":"==는 두 값이 같은지 비교하는 관계(비교) 연산자이다. =는 대입 연산자, !=는 다름을 비교하는 연산자이며, <>는 C언어에서 사용하지 않는 표기이다."},{"id":"w3-06","r":3,"n":6,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"class Point {\n       int x, y;\n       Point(int x, int y) {\n           this.x = x;\n           this.y = y;\n       }\n}\npublic class Test {\n       public static void main(String[] args) {\n           Point p = new Point(3, 7);\n           System.out.println(p.x + p.y);\n       }\n}","o":["3","7","10","37"],"a":2,"e":"생성자를 통해 p.x는 3, p.y는 7로 초기화된다. p.x + p.y = 3 + 7 = 10이다."},{"id":"w3-07","r":3,"n":7,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"scores = {'kim': 90, 'lee': 85, 'park': 95}\nbest = max(scores, key=scores.get)\nprint(best)","o":["kim","lee","park","95"],"a":2,"e":"max(scores, key=scores.get)는 값(value)이 가장 큰 키(key)를 반환한다. 값이 가장 큰 것은 park의 95이므로 'park'가 출력된다."},{"id":"w3-08","r":3,"n":8,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n       int a = 5, b = 0;\n       if (a > 0 && b == 0) {\n           printf(\"A\");\n       } else {\n           printf(\"B\");\n       }\n       return 0;\n}","o":["A","B","AB","오류 발생"],"a":0,"e":"a > 0(5 > 0, 참)이고 b == 0(0 == 0, 참)이므로 두 조건을 모두 만족(&&)하여 if문 내부의 \"A\"가 출력된다."},{"id":"w3-09","r":3,"n":9,"s":"P","q":"위 Java 코드의 실행 결과는?","code":"int x = 7;\nString result = (x % 2 == 0) ? \"짝수\" : \"홀수\";\nSystem.out.println(result);","o":["짝수","홀수","7","오류 발생"],"a":1,"e":"삼항 연산자는 조건이 참이면 첫 번째 값을, 거짓이면 두 번째 값을 반환한다. 7 % 2는 1(0이 아님)이므로 조건 x % 2 == 0은 거짓이 되어 \"홀수\"가 출력된다."},{"id":"w3-10","r":3,"n":10,"s":"P","q":"다음 중 Python에서 리스트(list)를 생성하는 표기법으로 옳은 것은?","code":"","o":["(1, 2, 3)","[1, 2, 3]","{1, 2, 3}","{1: 1}"],"a":1,"e":"대괄호 [ ]는 리스트를 생성하는 표기법이다. 소괄호 ( )는 튜플, 중괄호 { }는 집합 (set) 또는 딕셔너리(콜론이 있는 경우)를 생성하는 표기법이다."},{"id":"w3-11","r":3,"n":11,"s":"P","q":"함수 내부에서 선언되어 해당 함수 안에서만 사용할 수 있는 변수를 무엇이라 하는가?","code":"","o":["전역변수","지역변수","정적변수","참조변수"],"a":1,"e":"지역변수(Local Variable)는 함수나 블록 내부에서 선언되어 그 범위 안에서만 유효 하며, 함수 실행이 끝나면 소멸된다. 전역변수는 프로그램 전체에서 접근 가능한 변수이다."},{"id":"w3-12","r":3,"n":12,"s":"P","q":"Java에서 클래스가 다중 상속과 유사한 효과를 낼 수 있도록 지원하는 요소는?","code":"","o":["클래스","인터페이스","패키지","예외"],"a":1,"e":"Java는 클래스의 다중 상속을 지원하지 않지만, 하나의 클래스가 여러 개의 인터페이스를 구현(implements)할 수 있도록 하여 다중 상속과 유사한 효과를 제공한다."},{"id":"w3-13","r":3,"n":13,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"total = 0\nfor i in range(1, 10, 2):\n      total += i\nprint(total)","o":["20","25","30","45"],"a":1,"e":"range(1, 10, 2)는 1부터 9까지 2씩 증가하는 값(1, 3, 5, 7, 9)을 생성한다. 이 값들의 합은 1+3+5+7+9=25이다."},{"id":"w3-14","r":3,"n":14,"s":"P","q":"웹 페이지에 이미지를 삽입할 때 사용하는 HTML 태그는?","code":"","o":["<a>","<img>","<link>","<src>"],"a":1,"e":"<img> 태그는 src 속성에 지정된 경로의 이미지를 웹 페이지에 삽입한다. <a>는 하이퍼링크, <link>는 외부 리소스 연결에 사용되는 태그이다."},{"id":"w3-15","r":3,"n":15,"s":"P","q":"CSS에서 요소의 테두리(border)와 내용(content) 사이의 내부 여백을 지정하는 속성은?","code":"","o":["margin","padding","border","outline"],"a":1,"e":"padding은 요소의 테두리 안쪽, 내용과 테두리 사이의 여백을 지정한다. margin은 요소의 테두리 바깥쪽 여백을 지정하는 속성이다."},{"id":"w3-16","r":3,"n":16,"s":"A","q":"워드프로세서에서 문서 작성 중 맞춤법과 문법상의 오류를 검사해 주는 기능은?","code":"","o":["맞춤법 검사","메일 머지","인쇄 미리보기","목차 만들기"],"a":0,"e":"맞춤법 검사 기능은 문서 내의 철자 오류나 띄어쓰기, 문법 오류 등을 자동으로 검사하여 알려주는 기능이다."},{"id":"w3-17","r":3,"n":17,"s":"A","q":"여러 개의 파일을 하나로 묶고 크기를 줄여 저장 공간을 절약하는 작업을 무엇이라 하는가?","code":"","o":["압축","포맷","백업","스캔"],"a":0,"e":"압축은 파일의 중복되는 데이터를 효율적으로 인코딩하여 크기를 줄이고, 여러 파일 을 하나로 묶어 관리하기 쉽게 만드는 작업이다."},{"id":"w3-18","r":3,"n":18,"s":"A","q":"대부분의 인터넷 브라우저나 프로그램에서 단축키 F5를 눌렀을 때 수행되는 일반적인 기능은?","code":"","o":["새로고침","저장","인쇄","닫기"],"a":0,"e":"F5 키는 현재 페이지나 화면을 다시 불러오는 새로고침(Refresh) 기능의 대표적인 단축키이다."},{"id":"w3-19","r":3,"n":19,"s":"A","q":"스프레드시트에서 지정한 조건을 만족하는 셀의 개수를 세는 함수는?","code":"","o":["COUNTIF","SUMIF","VLOOKUP","IFERROR"],"a":0,"e":"COUNTIF 함수는 지정한 범위에서 조건을 만족하는 셀의 개수를 계산한다. SUMIF 는 조건에 맞는 값의 합계를 구하는 함수이다."},{"id":"w3-20","r":3,"n":20,"s":"A","q":"프레젠테이션 프로그램에서 발표자만 참고할 수 있도록 슬라이드에 추가로 작성하는 설명글은?","code":"","o":["슬라이드 노트(발표자 노트)","슬라이드 마스터","전환 효과","개요 보기"],"a":0,"e":"슬라이드 노트(발표자 노트)는 화면에는 표시되지 않고 발표자만 참고할 수 있도록슬라이드마다 작성하는 설명 텍스트이다."},{"id":"w3-21","r":3,"n":21,"s":"A","q":"컴퓨터의 부팅 순서나 기본적인 하드웨어 설정을 관리하는 시스템 소프트웨어는?","code":"","o":["BIOS/UEFI","워드프로세서","스프레드시트","웹 브라우저"],"a":0,"e":"BIOS(또는 최신 시스템의 UEFI)는 컴퓨터 전원이 켜질 때 하드웨어를 초기화하고 부팅 순서 등을 설정할 수 있게 해주는 펌웨어 형태의 시스템 소프트웨어이다."},{"id":"w3-22","r":3,"n":22,"s":"A","q":"인터넷에서 파일을 업로드하거나 다운로드할 때 사용하는 전통적인 파일 전송 프로토콜은?","code":"","o":["FTP","SMTP","HTTP","DNS"],"a":0,"e":"FTP(File Transfer Protocol)는 네트워크를 통해 파일을 주고받기 위한 전통적인 파일 전송 프로토콜이다."},{"id":"w3-23","r":3,"n":23,"s":"A","q":"다음 중 유선으로 네트워크를 연결하는 장치나 매체가 아닌 것은?","code":"","o":["랜 케이블","허브","스위치","블루투스"],"a":3,"e":"랜 케이블, 허브, 스위치는 유선으로 네트워크를 연결하는 장치·매체이다. 블루투스는 무선 통신 기술이다."},{"id":"w3-24","r":3,"n":24,"s":"A","q":"윈도우에서 특정 프로그램이나 파일의 속성 창을 빠르게 열 때 사용하는 마우스 동작은?","code":"","o":["왼쪽 버튼 더블 클릭","오른쪽 버튼 클릭 후 속성 선택","휠 버튼 클릭","왼쪽 버튼 드래그"],"a":1,"e":"파일이나 프로그램 아이콘에서 마우스 오른쪽 버튼을 클릭하면 나타나는 바로가기 메뉴에서 \"속성\"을 선택하여 상세 정보 창을 열 수 있다."},{"id":"w3-25","r":3,"n":25,"s":"A","q":"다음 중 클라우드 컴퓨팅의 일반적인 장점으로 옳지 않은 것은?","code":"","o":["언제 어디서나 접속 가능","초기 설치 비용 절감","인터넷 연결 없이도 사용 가능","자원의 유연한 확장"],"a":2,"e":"클라우드 컴퓨팅은 인터넷을 통해 원격 서버의 자원을 이용하는 서비스이므로 기본적으로 인터넷 연결이 필수적이다. 인터넷 연결 없이 사용 가능하다는 설명은 옳지 않다."},{"id":"w3-26","r":3,"n":26,"s":"A","q":"스프레드시트에서 데이터를 특정 기준에 따라 오름차순 또는 내림차순으로 나열하는 기능은?","code":"","o":["정렬","필터","서식","피벗"],"a":0,"e":"정렬(Sort) 기능은 선택한 데이터 범위를 지정한 기준 컬럼에 따라 오름차순 또는 내림차순으로 재배열하는 기능이다."},{"id":"w3-27","r":3,"n":27,"s":"A","q":"사용자의 파일을 암호화하여 사용할 수 없게 만든 뒤 이를 풀어주는 대가로 금전을 요구하는 악성코드는?","code":"","o":["웜(Worm)","랜섬웨어(Ransomware)","트로이 목마","스파이웨어"],"a":1,"e":"랜섬웨어는 사용자의 파일이나 시스템을 암호화하여 접근을 차단한 뒤, 이를 복구해 주는 대가로 금전(몸값, Ransom)을 요구하는 악성코드이다."},{"id":"w3-28","r":3,"n":28,"s":"A","q":"운영체제에서 인쇄 작업을 임시 저장 공간에 저장했다가 순서대로 처리하는 기능은?","code":"","o":["스풀링(Spooling)","캐싱(Caching)","버퍼링(Buffering)","페이징(Paging)"],"a":0,"e":"스풀링은 인쇄와 같은 저속 장치를 사용할 때, 데이터를 임시 저장 공간(스풀)에 저장 해 두었다가 순서대로 처리함으로써 CPU와 저속 장치 간의 속도 차이 문제를 완화하는 기법이다."},{"id":"w3-29","r":3,"n":29,"s":"A","q":"다음 중 이미지 파일의 확장자에 해당하지 않는 것은?","code":"","o":["JPG","PNG","GIF","MP3"],"a":3,"e":"JPG, PNG, GIF는 대표적인 이미지 파일 확장자이다. MP3는 음악(오디오) 파일의 확장자이다."},{"id":"w3-30","r":3,"n":30,"s":"A","q":"다음 중 강력한 비밀번호 설정 방법으로 옳지 않은 것은?","code":"","o":["영문·숫자·특수문자를 조합하여 사용","생일이나 전화번호를 사용","주기적으로 비밀번호를 변경","8자 이상의 충분한 길이로 설정"],"a":1,"e":"생일이나 전화번호는 추측하기 쉬운 개인정보이므로 비밀번호로 사용하면 보안에 취약하다. 영문·숫자·특수문자의 조합, 충분한 길이, 주기적인 변경이 강력한 비밀번호 설정의 원칙이다."},{"id":"w3-31","r":3,"n":31,"s":"S","q":"위 SQL문의 실행 결과는?\n다음과 같은 ORDERS 테이블이 있다. (1, 김민준, 50000) / (2, 이수아, 30000) / (3, 김민준, 20000) / (4, 박지우, 70000) ※(주문번호, 고객명, 금액)","code":"SELECT SUM(AMOUNT) FROM ORDERS WHERE CUSTOMER = '김민준';","o":["20000","50000","70000","100000"],"a":2,"e":"고객명이 '김민준'인 주문은 50000원, 20000원 두 건이다. SUM(AMOUNT)는 50000+20000=70000이다."},{"id":"w3-32","r":3,"n":32,"s":"S","q":"위 SQL문의 실행 결과에 포함되는 고객은?\n문제 31과 동일한 ORDERS 테이블을 사용한다.","code":"SELECT CUSTOMER, COUNT(*) FROM ORDERS GROUP BY CUSTOMER HAVING COUNT(*) >= 2;","o":["이수아","박지우","김민준","해당 없음"],"a":2,"e":"CUSTOMER별로 그룹화했을 때 김민준은 2건(50000원, 20000원)을 주문하여 COUNT(*)가 2이므로 HAVING COUNT(*) >= 2 조건을 만족한다. 이수아와 박지우는 각각 1건씩 주문하여 조건을 만족하지 못한다."},{"id":"w3-33","r":3,"n":33,"s":"S","q":"다음 중 이미 존재하는 테이블이나 컬럼의 이름을 변경할 때 ALTER TABLE 명령어와 함께 사용하는 옵션은?","code":"","o":["ADD","DROP","RENAME","MODIFY"],"a":2,"e":"RENAME 옵션은 테이블이나 컬럼의 이름을 변경할 때 사용한다. ADD는 컬럼 추가, DROP은 컬럼 삭제, MODIFY(또는 ALTER COLUMN)는 컬럼의 데이터 타입 등을 변경할 때 사용한다."},{"id":"w3-34","r":3,"n":34,"s":"S","q":"다음 중 CHECK 제약조건에 대한 설명으로 가장 옳은 것은?","code":"","o":["다른 테이블의 기본키를 참조하는 제약조건이다","컬럼에 저장될 수 있는 값의 범위나 조건을 제한하는 제약조건이다","컬럼에 NULL 값을 허용하지 않는 제약조건이다","한 테이블에 하나만 지정할 수 있는 제약조건이다"],"a":1,"e":"CHECK 제약조건은 컬럼에 입력될 수 있는 값의 범위나 조건(예: 나이 >= 0)을 지정 하여, 정의된 조건을 만족하지 않는 값은 입력되지 못하도록 제한한다."},{"id":"w3-35","r":3,"n":35,"s":"S","q":"SQL에서 특정 컬럼의 값이 지정된 여러 값 중 하나와 일치하는지 확인할 때 사용하는 연산자는?","code":"","o":["BETWEEN","LIKE","IN","IS NULL"],"a":2,"e":"IN 연산자는 컬럼의 값이 괄호 안에 지정된 여러 값들 중 하나와 일치하는지 확인할 때 사용한다. 예를 들어 WHERE DEPT IN ('영업부', '개발부')와 같이 사용한다."},{"id":"w3-36","r":3,"n":36,"s":"S","q":"두 테이블을 별도의 조인 조건 없이 결합하여 가능한 모든 행의 조합(카티션 곱)을 생성하는 조인은?","code":"","o":["INNER JOIN","CROSS JOIN","SELF JOIN","NATURAL JOIN"],"a":1,"e":"CROSS JOIN(교차 조인)은 조인 조건 없이 두 테이블의 모든 행을 조합하여 카티션 곱(Cartesian Product)을 생성한다."},{"id":"w3-37","r":3,"n":37,"s":"S","q":"테이블의 구조는 유지한 채 저장된 데이터를 모두 삭제하며, 일반적으로 DELETE보다 처리 속도가 빠른 명령어는?","code":"","o":["DROP","DELETE","TRUNCATE","ALTER"],"a":2,"e":"TRUNCATE는 테이블의 모든 행을 한 번에 삭제하되 테이블 구조는 유지하는 DDL 명령어로, 행 단위 로그를 남기는 DELETE보다 일반적으로 처리 속도가 빠르다."},{"id":"w3-38","r":3,"n":38,"s":"S","q":"SQL에서 특정 컬럼(들)을 기준으로 데이터를 그룹으로 묶을 때 사용하는 절은?","code":"","o":["ORDER BY","GROUP BY","HAVING","WHERE"],"a":1,"e":"GROUP BY 절은 지정한 컬럼의 값이 같은 행들을 하나의 그룹으로 묶어, 그룹별로 집계 함수를 적용할 수 있게 해준다."},{"id":"w3-39","r":3,"n":39,"s":"S","q":"서브쿼리가 여러 개의 행을 반환할 때, 메인 쿼리에서 비교 연산자로 직접 사용할 경우 오류가 발생할 수 있는 연산자는?","code":"","o":["IN","=","ANY","EXISTS"],"a":1,"e":"단일 값 비교 연산자인 '='는 서브쿼리가 정확히 하나의 값만 반환할 때 사용할 수 있다. 서브쿼리가 여러 행을 반환하면 '=' 대신 IN, ANY, ALL 등의 다중 행 비교 연산자를 사용해야 한다."},{"id":"w3-40","r":3,"n":40,"s":"S","q":"트랜잭션 내에서 수행한 변경 사항을 데이터베이스에 영구적으로 반영하는 명령어는?","code":"","o":["COMMIT","ROLLBACK","SAVEPOINT","GRANT"],"a":0,"e":"COMMIT은 트랜잭션에서 수행한 모든 변경 사항(INSERT, UPDATE, DELETE 등) 을 데이터베이스에 영구적으로 반영하고 트랜잭션을 종료하는 TCL 명령어이다."},{"id":"w3-41","r":3,"n":41,"s":"S","q":"정규화 과정에서, 기본키가 아닌 속성이 다른 기본키가 아닌 속성에 종속되는 이행적 함수 종속을 제거하여 도달하는 정규형은?","code":"","o":["제1정규형(1NF)","제2정규형(2NF)","제3정규형(3NF)","보이스-코드 정규형(BCNF)"],"a":2,"e":"제3정규형(3NF)은 제2정규형을 만족하면서, 기본키가 아닌 속성 간의 이행적 함수종속(A→B→C 형태)을 제거한 상태를 의미한다."},{"id":"w3-42","r":3,"n":42,"s":"S","q":"SQL에서 테이블이나 컬럼에 별칭(Alias)을 부여할 때 사용하는 키워드는?","code":"","o":["AS","IS","LIKE","ON"],"a":0,"e":"AS 키워드는 테이블이나 컬럼에 별칭을 부여할 때 사용한다. 예를 들어 'SELECT NAME AS 이름 FROM EMPLOYEE'와 같이 사용하며, AS는 생략 가능한 경우도 있다."},{"id":"w3-43","r":3,"n":43,"s":"S","q":"두 개의 SELECT문 결과 중 두 결과에 모두 공통으로 존재하는 행만 반환하는 집합 연산자는?","code":"","o":["UNION","UNION ALL","INTERSECT","MINUS"],"a":2,"e":"INTERSECT는 두 SELECT문의 결과 집합에서 공통으로 존재하는 행만 반환하는 집합 연산자이다."},{"id":"w3-44","r":3,"n":44,"s":"S","q":"다음 중 후보키(Candidate Key)에 대한 설명으로 가장 옳은 것은?","code":"","o":["테이블에서 자주 조회되는 컬럼이다","각 행을 유일하게 식별할 수 있는 최소한의 속성 집합이다","다른 테이블을 참조하는 속성이다","값이 자동으로 증가하는 속성이다"],"a":1,"e":"후보키는 테이블의 각 행을 유일하게 식별할 수 있는 속성(또는 속성의 조합) 중, 더 이상 줄일 수 없는 최소성을 만족하는 키를 의미한다. 후보키 중 하나가 선택되어 기본키가 된다."},{"id":"w3-45","r":3,"n":45,"s":"S","q":"SELECT문의 논리적 실행 순서상 가장 먼저 처리되는 절은?","code":"","o":["SELECT","FROM","WHERE","GROUP BY"],"a":1,"e":"SQL문은 작성 순서(SELECT-FROM-WHERE-GROUP BY-HAVING-ORDER BY)와 실제 논리적 실행 순서가 다르다. 실행 순서는 FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY이므로, FROM 절이 가장 먼저 처리된다."},{"id":"w3-46","r":3,"n":46,"s":"I","q":"프로세스 상태 전이 중, 실행(Running) 상태에서 준비(Ready) 상태로 전이되는 대표적인 경우는?","code":"","o":["입출력 요청 발생","시간 할당량(Time Slice) 초과로 인한 선점","작업 완료","메모리 부족"],"a":1,"e":"실행 중인 프로세스에 할당된 시간 할당량이 초과되면 스케줄러가 CPU를 회수(선점) 하여 해당 프로세스는 준비 상태로 전이되고, 다음 프로세스가 실행 상태가 된다."},{"id":"w3-47","r":3,"n":47,"s":"I","q":"OSI 7계층 중, 0과 1의 비트 신호를 전기적·광학적 신호로 변환하여 전송 매체로 내보내는 계층은?","code":"","o":["물리 계층","데이터링크 계층","네트워크 계층","전송 계층"],"a":0,"e":"물리 계층(1계층)은 비트 스트림을 전기적, 광학적, 전파 신호로 변환하여 실제 전송매체를 통해 전달하는 역할을 담당한다."},{"id":"w3-48","r":3,"n":48,"s":"I","q":"하나의 큰 네트워크를 여러 개의 작은 논리적 네트워크로 나누는 것을 무엇이라 하는가?","code":"","o":["라우팅","서브네팅(Subnetting)","포워딩","캡슐화"],"a":1,"e":"서브네팅은 하나의 네트워크 주소 공간을 서브넷 마스크를 이용해 여러 개의 작은 네트워크(서브넷)로 분할하는 것을 의미한다."},{"id":"w3-49","r":3,"n":49,"s":"I","q":"데이터베이스 정규화 과정에서, 제1정규형(1NF)을 만족하기 위해 충족해야 하는 조건은?","code":"","o":["모든 속성 값이 원자값이어야 한다","부분 함수 종속이 없어야 한다","이행적 함수 종속이 없어야 한다","다치 종속이 없어야 한다"],"a":0,"e":"제1정규형은 테이블의 모든 속성 값이 더 이상 분해할 수 없는 원자값(Atomic Value)으로만 구성되어야 한다는 조건을 만족하는 상태이다."},{"id":"w3-50","r":3,"n":50,"s":"I","q":"위험 분석을 반복적으로 수행하며 점진적으로 소프트웨어를 개발하는 생명주기 모델은?","code":"","o":["폭포수 모델","나선형 모델(Spiral Model)","V모델","프로토타입 모델"],"a":1,"e":"나선형 모델은 계획 수립, 위험 분석, 개발 및 검증, 고객 평가의 단계를 나선형으로 반복하며 점진적으로 완성도를 높여가는 소프트웨어 생명주기 모델이다."},{"id":"w3-51","r":3,"n":51,"s":"I","q":"라운드로빈(Round Robin) 스케줄링 기법의 특징으로 옳은 것은?","code":"","o":["먼저 도착한 프로세스를 끝까지 실행한다","각 프로세스에 동일한 시간 할당량을 부여하여 순차적으로 실행한다","실행 시간이 짧은 프로세스를 우선 실행한다","우선순위가 높은 프로세스만 실행한다"],"a":1,"e":"라운드로빈은 모든 프로세스에 동일한 시간 할당량(Time Quantum)을 부여하고, 이 시간이 지나면 다음 프로세스로 순환하며 실행하는 선점형 스케줄링 기법이다."},{"id":"w3-52","r":3,"n":52,"s":"I","q":"신뢰할 수 있는 기관이나 지인을 사칭하여 사용자를 속여 개인정보나 금융정보를 탈취하는 공격 기법은?","code":"","o":["피싱(Phishing)","DDoS","스니핑","파밍"],"a":0,"e":"피싱은 신뢰할 수 있는 대상(은행, 기관, 지인 등)을 사칭한 이메일이나 메시지로 사용자를 속여 개인정보나 금융정보를 탈취하는 사회공학적 공격 기법이다."},{"id":"w3-53","r":3,"n":53,"s":"I","q":"관계형 데이터베이스에서 하나의 릴레이션(테이블)에 존재하는 튜플(행)의 총 개수를 의미하는 용어는?","code":"","o":["디그리(Degree)","카디널리티(Cardinality)","도메인(Domain)","스키마(Schema)"],"a":1,"e":"카디널리티는 릴레이션(테이블)에 존재하는 튜플(행)의 개수를 의미한다. 디그리는 속성(컬럼)의 개수를 의미한다는 점에서 구분해야 한다."},{"id":"w3-54","r":3,"n":54,"s":"I","q":"캐시 메모리(Cache Memory)를 사용하는 주된 목적은?","code":"","o":["CPU와 주기억장치 간의 속도 차이를 줄이기 위해","보조기억장치의 용량을 늘리기 위해","네트워크 전송 오류를 줄이기 위해","전력 소비를 줄이기 위해"],"a":0,"e":"캐시 메모리는 처리 속도가 빠른 CPU와 상대적으로 느린 주기억장치 사이에 위치하여, 자주 사용하는 데이터를 임시로 저장함으로써 둘 사이의 속도 차이로 인한 병목 현상을 줄여준다."},{"id":"w3-55","r":3,"n":55,"s":"I","q":"상향식 통합 테스트에서, 아직 개발되지 않은 상위 모듈을 대신하여 하위 모듈을 호출하는 임시 모듈은?","code":"","o":["스텁(Stub)","드라이버(Driver)","테스트 오라클","테스트 슈트"],"a":1,"e":"드라이버는 상향식 통합 테스트에서 아직 개발되지 않은 상위 모듈을 대신하여 하위 모듈을 호출하고 결과를 전달받는 역할을 하는 임시 모듈이다."},{"id":"w3-56","r":3,"n":56,"s":"I","q":"다음 중 5세대(5G) 이동통신 기술의 특징으로 옳지 않은 것은?","code":"","o":["초고속 데이터 전송","초저지연 통신","초연결(다수 기기 동시 접속)","아날로그 신호를 이용한 전송"],"a":3,"e":"5G는 초고속, 초저지연, 초연결을 핵심 특징으로 하는 디지털 이동통신 기술이다. 아날로그 신호 전송은 과거의 통신 방식과 관련된 개념으로 5G의 특징에 해당하지 않는다."},{"id":"w3-57","r":3,"n":57,"s":"I","q":"하나의 IP 주소를 네트워크 부분과 호스트 부분으로 구분하는 역할을 하는 것은?","code":"","o":["서브넷 마스크","MAC 주소","포트 번호","게이트웨이"],"a":0,"e":"서브넷 마스크는 IP 주소에서 네트워크를 식별하는 부분과 호스트(단말)를 식별하는 부분을 구분해 주는 역할을 한다."},{"id":"w3-58","r":3,"n":58,"s":"I","q":"소프트웨어 테스트의 원칙 중, 동일한 테스트 케이스를 반복해서 사용하면 새로운 결함을 발견하는 효과가 점 점 줄어든다는 원칙은?","code":"","o":["결함 집중","살충제 패러독스","오류-부재의 궤변","테스트의 경제성"],"a":1,"e":"살충제 패러독스는 동일한 테스트 케이스를 반복 사용하면 더 이상 새로운 결함을 찾아내지 못하게 되므로, 테스트 케이스를 정기적으로 검토하고 개정해야 한다는 원칙이다."},{"id":"w3-59","r":3,"n":59,"s":"I","q":"프로세스가 요청한 자원(입출력 등)을 즉시 할당받지 못하고 그 완료를 기다리는 상태를 무엇이라 하는가?","code":"","o":["준비(Ready) 상태","실행(Running) 상태","대기(Waiting) 상태","종료(Terminated) 상태"],"a":2,"e":"대기(Waiting/Blocked) 상태는 프로세스가 입출력 완료와 같은 특정 이벤트를 기다리며 CPU를 사용하지 않는 상태를 의미한다."},{"id":"w3-60","r":3,"n":60,"s":"I","q":"인간의 신경망 구조를 모방한 인공신경망을 여러 층으로 쌓아 데이터를 학습하는 인공지능 기술은?","code":"","o":["빅데이터","딥러닝(Deep Learning)","블록체인","클라우드 컴퓨팅"],"a":1,"e":"딥러닝은 인간 뇌의 신경망 구조를 모방한 인공신경망을 여러 층(Layer)으로 깊게 쌓아, 대량의 데이터로부터 특징을 스스로 학습하는 인공지능 기술이다."},{"id":"w4-01","r":4,"n":1,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int arr[5] = {3, 7, 2, 9, 4};\n      int max = arr[0];\n      for (int i = 1; i < 5; i++) {\n           if (arr[i] > max) max = arr[i];\n      }\n      printf(\"%d\", max);\n      return 0;\n}","o":["3","7","9","4"],"a":2,"e":"배열의 각 값과 max를 비교하며 더 큰 값을 max에 저장한다. 배열 {3,7,2,9,4} 중 가장 큰 값은 9이다."},{"id":"w4-02","r":4,"n":2,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"public class Test {\n      public static void main(String[] args) {\n           int a = 10;\n           String s = \"결과: \" + a + 5;\n           System.out.println(s);\n      }\n}","o":["결과: 15","결과: 105","결과: 1050","15결과:"],"a":1,"e":"문자열 연결 연산자(+)는 왼쪽부터 순서대로 계산된다. \"결과: \" + a는 문자열 \"결과: 10\"이 되고, 여기에 + 5를 하면 문자열 \"결과: 105\"가 된다."},{"id":"w4-03","r":4,"n":3,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"def greet(name, msg=\"안녕하세요\"):\n      return f\"{name}, {msg}\"\n\nprint(greet(\"철수\"))","o":["철수","안녕하세요","철수, 안녕하세요","오류 발생"],"a":2,"e":"msg 매개변수는 기본값 \"안녕하세요\"를 가지므로, greet(\"철수\")처럼 msg를 생략하면 기본값이 사용된다. f-string에 의해 \"철수, 안녕하세요\"가 반환되어 출력된다."},{"id":"w4-04","r":4,"n":4,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int i = 10, count = 0;\n      do {\n           i--;\n           count++;\n      } while (i > 5);\n      printf(\"%d\", count);\n      return 0;\n}","o":["3","4","5","6"],"a":2,"e":"do-while문은 조건을 먼저 검사하지 않고 본문을 최소 한 번 실행한 뒤 조건을 검사한다. i는 10→9→8→7→6→5로 감소하며 count도 함께 5까지 증가하고, i가 5가 되는 순간 조건(i>5)이 거짓이 되어 반복이 종료된다. count는 5이다."},{"id":"w4-05","r":4,"n":5,"s":"P","q":"Python에서 한 줄 주석(comment)을 작성할 때 사용하는 기호는?","code":"","o":["//","#","/* */","--"],"a":1,"e":"Python에서는 '#' 기호 뒤에 오는 내용을 한 줄 주석으로 처리한다. //는 C, Java 등에서, /* */는 여러 줄 주석에서 사용되는 표기이다."},{"id":"w4-06","r":4,"n":6,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"public class Test {\n     public static void main(String[] args) {\n           int[] arr = new int[3];\n           System.out.println(arr[0]);\n     }\n}","o":["0","null","오류 발생","1"],"a":0,"e":"Java에서 int형 배열을 생성하면 각 요소는 자동으로 기본값인 0으로 초기화된다. 따라서 arr[0]은 0이 출력된다."},{"id":"w4-07","r":4,"n":7,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"i = 0\nwhile True:\n     i += 1\n     if i == 4:\n           break\nprint(i)","o":["3","4","5","무한 반복"],"a":1,"e":"i가 1씩 증가하다가 4가 되는 순간 break문에 의해 반복문을 빠져나온다. 따라서 i는 4 로 출력된다."},{"id":"w4-08","r":4,"n":8,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n     int arr[2][2] = {{1, 2}, {3, 4}};\n     int sum = 0;\n     for (int i = 0; i < 2; i++)\n           for (int j = 0; j < 2; j++)\n               sum += arr[i][j];\n     printf(\"%d\", sum);\n     return 0;\n}","o":["6","8","10","12"],"a":2,"e":"중첩 반복문이 2차원 배열의 모든 요소를 순회하며 합산한다. 1+2+3+4=10이 출력된다."},{"id":"w4-09","r":4,"n":9,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"class Counter {\n       static int count = 0;\n       Counter() { count++; }\n}\npublic class Test {\n       public static void main(String[] args) {\n            new Counter();\n            new Counter();\n            new Counter();\n            System.out.println(Counter.count);\n       }\n}","o":["0","1","2","3"],"a":3,"e":"static 변수 count는 모든 인스턴스가 공유하는 클래스 변수이다. 생성자가 호출될 때마다 count가 1씩 증가하는데, Counter 객체를 3번 생성했으므로 최종 count 값은 3이다."},{"id":"w4-10","r":4,"n":10,"s":"P","q":"다음 중 객체지향 프로그래밍(OOP)의 특징에 해당하지 않는 것은?","code":"","o":["캡슐화","상속","다형성","순차성"],"a":3,"e":"캡슐화, 상속, 다형성(추상화 포함)은 객체지향 프로그래밍의 대표적인 특징이다. 순차성은 명령이 순서대로 실행되는 절차적 프로그래밍의 특성과 관련이 있다."},{"id":"w4-11","r":4,"n":11,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"a = {1, 2, 3}\nb = {2, 3, 4}\nprint(a & b)","o":["{1, 2, 3, 4}","{2, 3}","{1}","{4}"],"a":1,"e":"집합(set) 자료형에서 '&' 연산자는 두 집합의 교집합을 반환한다. a와 b에 공통으로 존재하는 값은 2와 3이므로 {2, 3}이 출력된다."},{"id":"w4-12","r":4,"n":12,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int x = 0;\n      if (!x) {\n            printf(\"참\");\n      } else {\n            printf(\"거짓\");\n      }\n      return 0;\n}","o":["참","거짓","0","1"],"a":0,"e":"C언어에서 0은 거짓을 의미하므로 !x(논리 부정)는 참(1)이 된다. 조건식이 참이 되어 if문 내부의 \"참\"이 출력된다."},{"id":"w4-13","r":4,"n":13,"s":"P","q":"Java에서 클래스의 인스턴스(객체)를 생성할 때 사용하는 키워드는?","code":"","o":["new","class","this","extends"],"a":0,"e":"new 키워드는 클래스의 생성자를 호출하여 힙(Heap) 메모리에 새로운 인스턴스(객체)를 생성한다."},{"id":"w4-14","r":4,"n":14,"s":"P","q":"HTML에서 표(테이블)의 한 행(row)을 나타낼 때 사용하는 태그는?","code":"","o":["<table>","<tr>","<td>","<th>"],"a":1,"e":"<tr>(table row)은 표의 한 행을 나타낸다. <table>은 표 전체, <td>는 데이터 셀, <th>는 제목(헤더) 셀을 나타내는 태그이다."},{"id":"w4-15","r":4,"n":15,"s":"P","q":"CSS에서 요소를 화면에 어떻게 표시할지(블록, 인라인, 숨김 등) 지정하는 대표적인 속성은?","code":"","o":["display","position","float","visibility"],"a":0,"e":"display 속성은 요소를 block, inline, inline-block, none 등으로 지정하여 화면에 표시되는 방식을 결정한다."},{"id":"w4-16","r":4,"n":16,"s":"A","q":"워드프로세서에서 동일한 내용의 문서를 여러 수신자에게 각각 다른 이름 등으로 자동 생성하여 발송할 때 사용하는 기능은?","code":"","o":["메일 머지","매크로","상용구","스타일"],"a":0,"e":"메일 머지(Mail Merge)는 하나의 문서 서식에 별도의 명단 데이터(이름, 주소 등)를 결합하여, 수신자별로 개인화된 문서를 자동으로 생성하는 기능이다."},{"id":"w4-17","r":4,"n":17,"s":"A","q":"다음 중 컴퓨터 바이러스로부터 시스템을 보호하기 위한 방법으로 가장 거리가 먼 것은?","code":"","o":["백신 프로그램을 최신 상태로 유지","출처가 불분명한 파일 실행 자제","데이터를 정기적으로 백업","발신자를 알 수 없는 첨부파일도 모두 열어보기"],"a":3,"e":"백신 최신화, 출처 불분명 파일 실행 자제, 정기적 백업은 바이러스 예방에 도움이 되는 행동이다. 발신자를 알 수 없는 첨부파일을 모두 열어보는 것은 오히려 감염 위험을 크게 높이는 행동이다."},{"id":"w4-18","r":4,"n":18,"s":"A","q":"윈도우에서 실행 중인 여러 프로그램(창) 사이를 전환할 때 사용하는 단축키는?","code":"","o":["Alt+Tab","Ctrl+Tab","Shift+Tab","Win+Tab"],"a":0,"e":"Alt+Tab은 현재 실행 중인 여러 프로그램(창) 목록을 보여주고 전환할 수 있게 해주는 대표적인 단축키이다."},{"id":"w4-19","r":4,"n":19,"s":"A","q":"스프레드시트에서 여러 개의 조건을 모두 만족하는 값들의 합계를 구하는 함수는?","code":"","o":["SUMIF","SUMIFS","COUNTIFS","AVERAGEIF"],"a":1,"e":"SUMIFS 함수는 두 개 이상의 조건을 모두 만족하는 값들만 합산할 때 사용한다. SUMIF는 단일 조건만 지정할 수 있다."},{"id":"w4-20","r":4,"n":20,"s":"A","q":"다음 중 프레젠테이션 제작 시 청중의 집중을 방해할 수 있는 요소로 가장 거리가 먼 것은?","code":"","o":["지나치게 많은 텍스트","과도한 애니메이션 효과","적절한 여백과 간결한 구성","가독성이 낮은 작은 글꼴"],"a":2,"e":"과도한 텍스트, 지나친 애니메이션, 작은 글꼴은 청중의 집중을 방해하는 요소이다. 반대로 적절한 여백과 간결한 구성은 오히려 가독성과 전달력을 높이는 바람직한 요소이다."},{"id":"w4-21","r":4,"n":21,"s":"A","q":"다음 중 운영체제의 파일 관리 기능에 해당하는 것은?","code":"","o":["파일 생성, 삭제, 이름 변경 등 관리","문서의 맞춤법 검사","웹 페이지 렌더링","이미지 파일 편집"],"a":0,"e":"운영체제는 파일의 생성, 삭제, 복사, 이름 변경, 권한 관리 등 파일과 관련된 전반적인 관리 기능을 제공한다."},{"id":"w4-22","r":4,"n":22,"s":"A","q":"웹 브라우저에서 자주 방문하는 사이트를 등록해 두고 빠르게 접속할 수 있도록 하는 기능은?","code":"","o":["즐겨찾기(북마크)","캐시 삭제","시크릿 모드","팝업 차단"],"a":0,"e":"즐겨찾기(북마크)는 자주 방문하는 웹사이트의 주소를 등록해 두고 메뉴에서 바로 선택하여 빠르게 접속할 수 있도록 하는 기능이다."},{"id":"w4-23","r":4,"n":23,"s":"A","q":"다음 중 컴퓨터 네트워크의 데이터 전송 속도를 나타내는 단위는?","code":"","o":["bps","dpi","rpm","fps"],"a":0,"e":"bps(bits per second)는 초당 전송되는 비트 수를 나타내는 네트워크 전송 속도 단위이다. dpi는 인쇄 해상도, rpm은 분당 회전수, fps는 초당 프레임 수를 나타내는 단위이다."},{"id":"w4-24","r":4,"n":24,"s":"A","q":"윈도우에서 삭제한 파일을 완전히 지우기 전에 임시로 보관하는 장소는?","code":"","o":["휴지통","임시 폴더","다운로드 폴더","내 문서"],"a":0,"e":"휴지통(Recycle Bin)은 삭제된 파일을 즉시 완전히 삭제하지 않고 임시로 보관하여, 필요시 복원할 수 있도록 하는 공간이다."},{"id":"w4-25","r":4,"n":25,"s":"A","q":"다음 중 윈도우 프로그램의 실행(설치) 파일 확장자로 옳은 것은?","code":"","o":[".exe",".txt",".jpg",".mp4"],"a":0,"e":".exe는 윈도우에서 실행 가능한 프로그램 파일의 확장자이다. .txt는 텍스트, .jpg는 이미지, .mp4는 동영상 파일의 확장자이다."},{"id":"w4-26","r":4,"n":26,"s":"A","q":"스프레드시트에서 지정한 조건에 따라 셀의 배경색이나 글꼴 색 등의 서식을 자동으로 다르게 지정하는 기능은?","code":"","o":["조건부 서식","자동 필터","피벗 테이블","매크로"],"a":0,"e":"조건부 서식은 셀의 값이 특정 조건을 만족할 때 자동으로 지정된 서식(색상, 글꼴 등) 을 적용하는 기능이다."},{"id":"w4-27","r":4,"n":27,"s":"A","q":"문자메시지(SMS)를 이용해 악성 링크 클릭을 유도하여 개인정보를 탈취하는 공격 기법은?","code":"","o":["피싱(Phishing)","스미싱(Smishing)","파밍(Pharming)","스푸핑(Spoofing)"],"a":1,"e":"스미싱은 SMS(문자메시지)와 피싱(Phishing)의 합성어로, 문자메시지에 포함된 악성 링크를 클릭하도록 유도하여 개인정보나 금융정보를 탈취하는 공격 기법이다."},{"id":"w4-28","r":4,"n":28,"s":"A","q":"운영체제에서 특정 하드웨어 장치를 인식하고 정상적으로 제어할 수 있도록 해주는 소프트웨어는?","code":"","o":["장치 드라이버","컴파일러","인터프리터","스케줄러"],"a":0,"e":"장치 드라이버는 프린터, 그래픽카드 등 특정 하드웨어 장치와 운영체제 사이의 통신 을 중개하여, 운영체제가 해당 장치를 인식하고 제어할 수 있도록 해주는 소프트웨어이다."},{"id":"w4-29","r":4,"n":29,"s":"A","q":"다음 중 동영상 파일의 확장자에 해당하지 않는 것은?","code":"","o":["MP4","AVI","MOV","BMP"],"a":3,"e":"MP4, AVI, MOV는 대표적인 동영상 파일 확장자이다. BMP는 압축되지 않은 비트맵 이미지 파일의 확장자이다."},{"id":"w4-30","r":4,"n":30,"s":"A","q":"다음 중 개인정보가 유출된 것으로 의심될 때 취해야 할 조치로 가장 적절한 것은?","code":"","o":["관련 계정의 비밀번호를 즉시 변경한다","별다른 조치 없이 지켜본다","비밀번호를 더 간단하게 변경한다","계정을 그대로 계속 사용한다"],"a":0,"e":"개인정보 유출이 의심될 경우 가장 먼저 취해야 할 조치는 관련 계정의 비밀번호를 즉 시 변경하고, 필요시 관계 기관에 신고하는 것이다."},{"id":"w4-31","r":4,"n":31,"s":"S","q":"위 SQL문의 실행 결과는?\n다음과 같은 BOOK 테이블이 있다. (1, 자바의정석, 30000, IT) / (2, 태백산맥, 15000, 소설) / (3, SQL첫걸음, 25000, IT) / (4, 어린왕자, 12000, 소설) ※(도서번호, 제목, 가격, 분류)","code":"SELECT COUNT(*) FROM BOOK WHERE PRICE >= 20000;","o":["1","2","3","4"],"a":1,"e":"가격이 20000 이상인 도서는 자바의정석(30000), SQL첫걸음(25000) 두 권이므로 COUNT(*)의 결과는 2이다."},{"id":"w4-32","r":4,"n":32,"s":"S","q":"위 SQL문의 실행 결과는?\n문제 31과 동일한 BOOK 테이블을 사용한다.","code":"SELECT AVG(PRICE) FROM BOOK WHERE CATEGORY = 'IT';","o":["20000","25000","27500","30000"],"a":2,"e":"CATEGORY가 'IT'인 도서는 자바의정석(30000), SQL첫걸음(25000)이다. 평균은 (30000+25000)/2 = 27500이다."},{"id":"w4-33","r":4,"n":33,"s":"S","q":"다음 중 특정 사용자에게 데이터베이스 객체에 대한 접근 권한을 부여하는 SQL 명령어는?","code":"","o":["GRANT","REVOKE","COMMIT","ROLLBACK"],"a":0,"e":"GRANT는 사용자나 역할에게 테이블 조회, 수정 등의 권한을 부여하는 DCL 명령어이다."},{"id":"w4-34","r":4,"n":34,"s":"S","q":"MySQL에서 조회 결과를 특정 컬럼 기준으로 정렬한 후, 상위 일부 행만 조회하고자 할 때 사용하는 절은?","code":"","o":["TOP","LIMIT","ROWNUM","FETCH"],"a":1,"e":"MySQL에서는 LIMIT 절을 이용해 정렬된 결과 중 원하는 개수의 행만 제한하여 조회할 수 있다. (SQL Server는 TOP, Oracle은 ROWNUM 또는 FETCH를 주로 사용한다.)"},{"id":"w4-35","r":4,"n":35,"s":"S","q":"SQL에서 컬럼 값이 NULL일 때 이를 지정한 다른 값으로 대체하여 출력할 때 사용하는 함수는?","code":"","o":["NVL","SUBSTR","ROUND","LENGTH"],"a":0,"e":"NVL(컬럼, 대체값) 함수는 컬럼 값이 NULL인 경우 지정한 대체값으로 바꾸어 출력한다(MySQL에서는 IFNULL, 표준 SQL에서는 COALESCE 함수를 사용한다)."},{"id":"w4-36","r":4,"n":36,"s":"S","q":"두 테이블에 이름이 동일한 컬럼이 있을 때, 이를 기준으로 자동으로 조인 조건을 설정해 주는 조인은?","code":"","o":["NATURAL JOIN","CROSS JOIN","SELF JOIN","OUTER JOIN"],"a":0,"e":"NATURAL JOIN은 두 테이블에서 이름과 데이터 타입이 동일한 컬럼을 자동으로 찾아 그 컬럼을 기준으로 조인을 수행한다."},{"id":"w4-37","r":4,"n":37,"s":"S","q":"SQL에서 문자열의 일부를 지정한 위치와 길이만큼 추출할 때 사용하는 함수는?","code":"","o":["SUBSTR","CONCAT","TRIM","UPPER"],"a":0,"e":"SUBSTR(문자열, 시작위치, 길이) 함수는 문자열에서 지정한 위치부터 지정한 길이 만큼의 부분 문자열을 추출한다."},{"id":"w4-38","r":4,"n":38,"s":"S","q":"다음 중 트랜잭션의 특성(ACID)에 해당하지 않는 것은?","code":"","o":["원자성(Atomicity)","일관성(Consistency)","고립성(Isolation)","가용성(Availability)"],"a":3,"e":"트랜잭션의 ACID 특성은 원자성(Atomicity), 일관성(Consistency), 고립성 (Isolation), 지속성(Durability)이다. 가용성(Availability)은 ACID에 포함되지 않는다."},{"id":"w4-39","r":4,"n":39,"s":"S","q":"두 테이블을 조인할 때, 조인 조건을 명시적으로 지정하기 위해 사용하는 절은?","code":"","o":["ON","WHERE 조건만 사용 가능","WITH","USING만 사용 가능"],"a":0,"e":"JOIN 구문에서 ON 절은 두 테이블 간의 조인 조건을 명시적으로 지정하는 데 사용된다(예: A INNER JOIN B ON A.id = B.a_id)."},{"id":"w4-40","r":4,"n":40,"s":"S","q":"데이터베이스 무결성 제약조건 중, 기본키가 NULL 값이나 중복 값을 가질 수 없도록 보장하는 무결성은?","code":"","o":["개체 무결성","참조 무결성","도메인 무결성","사용자 정의 무결성"],"a":0,"e":"개체 무결성은 기본키가 NULL 값이나 중복된 값을 가지지 않도록 보장하여, 각 튜플 (행)을 유일하게 식별할 수 있도록 하는 제약조건이다."},{"id":"w4-41","r":4,"n":41,"s":"S","q":"이미 존재하는 컬럼의 데이터 타입이나 크기를 변경할 때 ALTER TABLE과 함께 사용하는 옵션은?","code":"","o":["ADD","DROP","RENAME","MODIFY"],"a":3,"e":"MODIFY(또는 데이터베이스 종류에 따라 ALTER COLUMN) 옵션은 이미 존재하는 컬럼의 데이터 타입이나 크기, 제약조건 등을 변경할 때 사용한다."},{"id":"w4-42","r":4,"n":42,"s":"S","q":"다음 중 EXISTS 연산자에 대한 설명으로 가장 옳은 것은?","code":"","o":["서브쿼리의 결과가 존재하는지 여부를 확인하는 연산자이다","두 값이 같은지 비교하는 연산자이다","문자열 패턴을 검색하는 연산자이다","컬럼의 합계를 구하는 연산자이다"],"a":0,"e":"EXISTS는 서브쿼리를 실행한 결과 행이 하나라도 존재하면 참(TRUE), 존재하지 않으면 거짓(FALSE)을 반환하는 연산자로, 주로 상관 서브쿼리와 함께 사용된다."},{"id":"w4-43","r":4,"n":43,"s":"S","q":"SQL에서 두 개 이상의 문자열(컬럼 값 포함)을 하나로 결합할 때 사용하는 함수는?","code":"","o":["CONCAT","SUBSTR","TRIM","LENGTH"],"a":0,"e":"CONCAT(문자열1, 문자열2, ...) 함수는 여러 개의 문자열을 순서대로 이어 붙여 하나의 문자열로 결합한다."},{"id":"w4-44","r":4,"n":44,"s":"S","q":"다음 중 UPDATE문의 기본 구문 순서로 옳은 것은?","code":"","o":["UPDATE 테이블 SET 컬럼=값 WHERE 조건","SET 컬럼=값 UPDATE 테이블 WHERE 조건","UPDATE 테이블 WHERE 조건 SET 컬럼=값","WHERE 조건 UPDATE 테이블 SET 컬럼=값"],"a":0,"e":"UPDATE문은 'UPDATE 테이블명 SET 컬럼명=값 WHERE 조건' 순서로 작성한다. WHERE 절을 생략하면 테이블의 모든 행이 변경되므로 주의해야 한다."},{"id":"w4-45","r":4,"n":45,"s":"S","q":"다음 중 정규화되지 않은 데이터베이스에서 일반적으로 발생할 수 있는 이상현상(Anomaly)에 해당하지 않는 것은?","code":"","o":["삽입 이상","삭제 이상","갱신 이상","검색 이상"],"a":3,"e":"정규화 이론에서 다루는 대표적인 이상현상은 삽입 이상, 삭제 이상, 갱신 이상 세 가지이다. 검색(조회) 이상은 정규화 이상현상으로 분류되지 않는다."},{"id":"w4-46","r":4,"n":46,"s":"I","q":"다음 중 프로세스와 스레드에 대한 설명으로 가장 옳은 것은?","code":"","o":["하나의 프로세스는 여러 개의 스레드를 가질 수 있다","하나의 스레드는 여러 개의 프로세스를 가질 수 있다","프로세스와 스레드는 완전히 동일한 개념이다","스레드는 독립적인 메모리 공간을 항상 별도로 가진다"],"a":0,"e":"하나의 프로세스는 실행 흐름의 단위인 여러 개의 스레드를 가질 수 있으며, 같은 프로세스 내의 스레드들은 메모리 공간(코드, 데이터, 힙 영역)을 공유한다."},{"id":"w4-47","r":4,"n":47,"s":"I","q":"OSI 7계층 중, 통신하는 두 시스템 간의 논리적 연결(세션)을 수립, 유지, 종료하는 역할을 담당하는 계층은?","code":"","o":["전송 계층","세션 계층","표현 계층","응용 계층"],"a":1,"e":"세션 계층(5계층)은 통신 장치 간의 세션(대화)을 수립하고 유지하며 종료하는 역할을 담당한다."},{"id":"w4-48","r":4,"n":48,"s":"I","q":"내부 네트워크와 외부 네트워크 사이에서 트래픽을 검사하여 비인가 접근을 차단하는 보안 장비 또는 소프트웨어는?","code":"","o":["라우터","스위치","방화벽(Firewall)","허브"],"a":2,"e":"방화벽은 미리 정의된 보안 규칙에 따라 내부 네트워크와 외부 네트워크 사이의 트래픽을 검사하고, 비인가 접근이나 유해 트래픽을 차단하는 보안 장비/소프트웨어이다."},{"id":"w4-49","r":4,"n":49,"s":"I","q":"데이터베이스 3단계 스키마 구조 중, 개별 사용자나 응용 프로그램의 관점에서 필요한 데이터만 정의한 스키마는?","code":"","o":["외부 스키마","개념 스키마","내부 스키마","물리 스키마"],"a":0,"e":"외부 스키마는 개별 사용자나 응용 프로그램이 필요로 하는 데이터베이스의 논리적구조만을 정의한 스키마로, 사용자마다 서로 다른 외부 스키마를 가질 수 있다."},{"id":"w4-50","r":4,"n":50,"s":"I","q":"소프트웨어 형상 관리(SCM)에서, 정식으로 검토되고 승인된 특정 시점의 형상을 의미하는 용어는?","code":"","o":["형상 항목(SCI)","기준선(Baseline)","저장소(Repository)","브랜치(Branch)"],"a":1,"e":"기준선(Baseline)은 정식으로 검토되고 승인된 특정 시점의 형상으로, 이후의 모든 변경은 정해진 절차를 통해서만 가능하도록 통제하는 기준이 된다."},{"id":"w4-51","r":4,"n":51,"s":"I","q":"우선순위 스케줄링 기법에서, 낮은 우선순위를 가진 프로세스가 계속 CPU를 할당받지 못하는 현상은?","code":"","o":["교착상태(Deadlock)","기아(Starvation) 현상","스래싱(Thrashing)","컨텍스트 스위칭"],"a":1,"e":"기아 현상은 우선순위가 낮은 프로세스가 우선순위가 높은 프로세스들에 밀려 계속해서 CPU를 할당받지 못하는 상태를 의미한다. 이를 방지하기 위해 에이징(Aging) 기법 등이 사용된다."},{"id":"w4-52","r":4,"n":52,"s":"I","q":"다음 중 무선 네트워크(Wi-Fi)의 보안을 강화하기 위한 암호화 방식으로 옳은 것은?","code":"","o":["WPA2","HTTP","FTP","SMTP"],"a":0,"e":"WPA2는 무선랜(Wi-Fi) 통신 구간의 데이터를 암호화하여 보안을 강화하는 대표적인 무선 보안 프로토콜이다. HTTP, FTP, SMTP는 각각 웹, 파일 전송, 메일 전송을 위한 프로토콜이다."},{"id":"w4-53","r":4,"n":53,"s":"I","q":"관계형 데이터베이스에서 하나의 릴레이션이 가지는 속성(컬럼)의 총 개수를 의미하는 용어는?","code":"","o":["카디널리티(Cardinality)","디그리(Degree)","도메인(Domain)","튜플(Tuple)"],"a":1,"e":"디그리(차수)는 릴레이션(테이블)이 가지는 속성(컬럼)의 개수를 의미한다. 카디널리티는 튜플(행)의 개수를 의미한다는 점에서 구분된다."},{"id":"w4-54","r":4,"n":54,"s":"I","q":"여러 개의 디스크를 하나로 묶어 성능 향상 및 데이터의 안정성(중복성)을 확보하는 저장장치 구성 기술은?","code":"","o":["RAID","DNS","VPN","NAT"],"a":0,"e":"RAID(Redundant Array of Independent Disks)는 여러 개의 디스크를 하나의 논리적 단위로 구성하여 데이터 처리 속도를 높이거나, 데이터를 중복 저장하여 안정성을 높이는 기술이다."},{"id":"w4-55","r":4,"n":55,"s":"I","q":"소프트웨어의 결함을 수정한 후, 그 수정이 기존의 다른 기능에 부정적인 영향을 미치지 않았는지 확인하기 위해 수행하는 테스트는?","code":"","o":["단위 테스트","회귀 테스트(Regression Test)","알파 테스트","베타 테스트"],"a":1,"e":"회귀 테스트는 소스 코드를 변경(결함 수정, 기능 추가 등)한 후, 기존에 정상 동작하던 기능들이 여전히 올바르게 동작하는지 재검증하기 위해 수행하는 테스트이다."},{"id":"w4-56","r":4,"n":56,"s":"I","q":"현실과 가상이 융합된 3차원 가상세계에서 사회·경제·문화적 활동이 이루어지는 공간을 의미하는 용어는?","code":"","o":["빅데이터","메타버스(Metaverse)","블록체인","클라우드 컴퓨팅"],"a":1,"e":"메타버스는 초월을 의미하는 Meta와 세계를 의미하는 Universe의 합성어로, 현실 과 가상이 융합된 3차원 가상공간에서 다양한 사회·경제·문화 활동이 이루어지는 것을 의미하는 용어이다."},{"id":"w4-57","r":4,"n":57,"s":"I","q":"네트워크 통신에서, 데이터가 송신자로부터 수신자에게 도달하기까지 걸리는 지연 시간을 의미하는 용어는?","code":"","o":["대역폭(Bandwidth)","지연시간(Latency)","처리량(Throughput)","가용성(Availability)"],"a":1,"e":"지연시간(Latency)은 데이터가 송신자로부터 수신자까지 전달되는 데 걸리는 시간 을 의미한다. 대역폭은 단위 시간당 전송 가능한 데이터의 양을 의미한다."},{"id":"w4-58","r":4,"n":58,"s":"I","q":"입력값, 실행 조건, 기대 결과 등으로 구성되는 명세 기반 테스트의 산출물은?","code":"","o":["테스트 계획서","테스트 케이스","테스트 시나리오","테스트 요약 보고서"],"a":1,"e":"테스트 케이스는 명세 기반 테스트의 산출물로, 특정 목적을 달성하거나 요구사항 위 반 여부를 확인하기 위한 입력값, 실행 조건, 기대 결과 등으로 구성된다."},{"id":"w4-59","r":4,"n":59,"s":"I","q":"운영체제의 메모리 관리 기법 중, 프로세스를 논리적 의미를 가지는 가변 크기의 단위로 나누어 관리하는 기법은?","code":"","o":["페이징(Paging)","세그멘테이션(Segmentation)","스와핑(Swapping)","캐싱(Caching)"],"a":1,"e":"세그멘테이션은 프로그램을 논리적 의미 단위(함수, 배열 등)의 가변 크기 세그먼트로 나누어 관리하는 기법이다. 페이징은 고정 크기의 페이지 단위로 나누어 관리한다는 점에서 차이가 있다."},{"id":"w4-60","r":4,"n":60,"s":"I","q":"현실 세계의 사물이나 시스템을 가상 공간에 동일하게 구현하여 시뮬레이션하는 기술을 의미하는 용어는?","code":"","o":["디지털 트윈(Digital Twin)","증강현실(AR)","가상현실(VR)","핀테크(Fintech)"],"a":0,"e":"디지털 트윈은 현실 세계의 사물, 시스템, 프로세스를 가상 공간에 동일하게 복제(모델링)하여, 실제 변화에 대응하는 시뮬레이션과 예측 분석에 활용하는 기술이다."},{"id":"w5-01","r":5,"n":1,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int a = 3, b = 8, temp;\n      temp = a;\n      a = b;\n      b = temp;\n      printf(\"%d %d\", a, b);\n      return 0;\n}","o":["38","83","33","88"],"a":1,"e":"temp에 a의 값(3)을 저장한 뒤, a에 b의 값(8)을 대입하고, b에 temp에 저장해 두었던 원래 a의 값(3)을 대입한다. 이는 두 변수의 값을 맞바꾸는(swap) 전형적인 코드로, 결과는 a=8, b=3이 되어 \"8 3\"이 출력된다."},{"id":"w5-02","r":5,"n":2,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"public class Test {\n      public static void main(String[] args) {\n           String s1 = \"Hello\";\n           String s2 = \"HELLO\";\n           System.out.println(s1.equalsIgnoreCase(s2));\n      }\n}","o":["true","false","Hello","오류 발생"],"a":0,"e":"equalsIgnoreCase()는 대소문자를 구분하지 않고 두 문자열의 내용이 같은지 비교 하는 메서드이다. \"Hello\"와 \"HELLO\"는 대소문자만 다를 뿐 내용이 같으므로 true가 출력된다."},{"id":"w5-03","r":5,"n":3,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"name = \"민지\"\nage = 20\nprint(\"%s는 %d살입니다\" % (name, age))","o":["민지는 20살입니다","%s는 %d살입니다","민지 20","오류 발생"],"a":0,"e":"'%' 연산자를 이용한 문자열 포맷팅에서 %s는 문자열, %d는 정수로 치환된다. name(민지)과 age(20)이 각각 대입되어 '민지는 20살입니다'가 출력된다."},{"id":"w5-04","r":5,"n":4,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int arr[3] = {10, 20, 30};\n      printf(\"%d\", *arr + 1);\n      return 0;\n}","o":["11","20","21","30"],"a":0,"e":"단항 연산자 *(역참조)는 +보다 우선순위가 높으므로 *arr + 1은 (*arr) + 1로 계산된다. *arr은 arr[0]인 10을 의미하므로 10 + 1 = 11이 출력된다."},{"id":"w5-05","r":5,"n":5,"s":"P","q":"다음 중 Java에서 배열을 선언하고 생성하는 방법으로 옳은 것은?","code":"","o":["int arr[5];","int[] arr = new int[5];","array arr(5);","int arr = new array[5];"],"a":1,"e":"Java에서 배열은 \"자료형[] 배열이름 = new 자료형[크기];\" 형식으로 선언과 동시에 생성하는 것이 일반적인 방법이다."},{"id":"w5-06","r":5,"n":6,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"lst = [1, 2, 3]\nlst.insert(1, 100)\nprint(lst)","o":["[1, 2, 3, 100]","[100, 1, 2, 3]","[1, 100, 2, 3]","[1, 2, 100, 3]"],"a":2,"e":"insert(인덱스, 값) 메서드는 지정한 인덱스 위치에 값을 삽입하고 기존 요소들을 뒤로밀어낸다. insert(1, 100)은 인덱스 1 자리에 100을 삽입하므로 결과는 [1, 100, 2, 3]이 된다."},{"id":"w5-07","r":5,"n":7,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n       int a = 10, b = 20;\n       int max = (a > b) ? a : b;\n       printf(\"%d\", max);\n       return 0;\n}","o":["10","20","0","1"],"a":1,"e":"삼항 연산자 (a > b) ? a : b는 조건 a > b가 거짓(10 > 20은 거짓)이므로 두 번째 값인 b(20)를 반환한다. max는 20이 된다."},{"id":"w5-08","r":5,"n":8,"s":"P","q":"다음 중 Python에서 예외 처리를 위해 사용하는 구문이 아닌 것은?","code":"","o":["try","except","finally","def"],"a":3,"e":"try, except, finally는 예외 처리 구문을 구성하는 키워드이다. def는 함수를 정의할 때 사용하는 키워드로 예외 처리와는 관련이 없다."},{"id":"w5-09","r":5,"n":9,"s":"P","q":"위 Java 프로그램의 실행 결과는?","code":"public class Test {\n       public static void main(String[] args) {\n           int[] arr = {2, 4, 6};\n           int sum = 0;\n           for (int n : arr) {\n                  sum += n;\n           }\n           System.out.println(sum);\n       }\n}","o":["6","10","12","14"],"a":2,"e":"향상된 for문(for-each)은 배열의 각 요소를 순서대로 n에 대입하며 반복한다. 2+4+6=12가 sum에 누적되어 출력된다."},{"id":"w5-10","r":5,"n":10,"s":"P","q":"다음 중 C언어에서 변수의 값을 프로그램 실행 중에 변경할 수 없도록 지정하는 키워드는?","code":"","o":["static","const","extern","volatile"],"a":1,"e":"const 키워드는 변수를 선언할 때 함께 사용하여, 이후 해당 변수의 값을 변경할 수 없는 상수처럼 만든다."},{"id":"w5-11","r":5,"n":11,"s":"P","q":"위 Python 프로그램의 실행 결과는?","code":"x = 5\ny = 10\nprint(x > 0 or y < 5)","o":["True","False","5","10"],"a":0,"e":"or 연산자는 두 조건 중 하나라도 참이면 True를 반환한다. x > 0(5 > 0)은 참이므로, y < 5의 결과와 관계없이 전체 식은 True가 된다."},{"id":"w5-12","r":5,"n":12,"s":"P","q":"Java에서 자식 클래스에서 부모 클래스의 생성자나 메서드를 명시적으로 호출할 때 사용하는 키워드는?","code":"","o":["this","super","extends","implements"],"a":1,"e":"super 키워드는 자식 클래스에서 부모 클래스의 생성자(super())나 메서드, 필드에 접근할 때 사용한다."},{"id":"w5-13","r":5,"n":13,"s":"P","q":"위 C 프로그램의 실행 결과는?","code":"#include <stdio.h>\nint main() {\n      int arr[4] = {12, 5, 9, 3};\n      int min = arr[0];\n      for (int i = 1; i < 4; i++) {\n            if (arr[i] < min) min = arr[i];\n      }\n      printf(\"%d\", min);\n      return 0;\n}","o":["3","5","9","12"],"a":0,"e":"배열의 각 값과 min을 비교하며 더 작은 값을 min에 저장한다. 배열 {12,5,9,3} 중 가장 작은 값은 3이다."},{"id":"w5-14","r":5,"n":14,"s":"P","q":"순서가 없는 글머리 기호 목록을 만들 때 사용하는 HTML 태그는?","code":"","o":["<ol>","<ul>","<li>","<dl>"],"a":1,"e":"<ul>(unordered list)은 순서가 없는 글머리 기호 목록을 만드는 태그이다. <ol>은 순서가 있는 목록, <li>는 목록의 각 항목, <dl>은 정의 목록을 나타내는 태그이다."},{"id":"w5-15","r":5,"n":15,"s":"P","q":"CSS 스타일을 적용하기 위해 HTML 요소에 특정 그룹을 지정할 때 흔히 사용하는 속성은?","code":"","o":["id","class","style","name"],"a":1,"e":"class 속성은 여러 요소에 동일한 이름을 부여하여 CSS의 클래스 선택자(.클래스명) 로 한꺼번에 스타일을 적용할 수 있게 해준다. id는 문서 내에서 유일해야 하는 식별자이다."},{"id":"w5-16","r":5,"n":16,"s":"A","q":"문서의 각 항목과 해당 페이지 번호를 정리하여, 원하는 위치로 빠르게 이동할 수 있도록 돕는 워드프로세서 기능은?","code":"","o":["목차","메일 머지","상용구","각주"],"a":0,"e":"목차(Table of Contents)는 문서의 제목이나 항목들을 페이지 번호와 함께 정리하여, 원하는 부분으로 빠르게 이동할 수 있도록 도와주는 기능이다."},{"id":"w5-17","r":5,"n":17,"s":"A","q":"다음 중 컴퓨터 정기 점검 항목으로 옳지 않은 것은?","code":"","o":["디스크 조각 모음","백신 프로그램 검사","운영체제 및 소프트웨어 업데이트","중요 파일을 무작위로 삭제"],"a":3,"e":"디스크 조각 모음, 백신 검사, 소프트웨어 업데이트는 컴퓨터를 안정적으로 유지하기 위한 바람직한 정기 점검 항목이다. 중요 파일을 무작위로 삭제하는 것은 데이터 손실을 유발하는 위험한 행동이다."},{"id":"w5-18","r":5,"n":18,"s":"A","q":"대부분의 프로그램에서 단축키 Ctrl+A를 눌렀을 때 수행되는 기능은?","code":"","o":["전체 선택","전체 삭제","전체 저장","전체 인쇄"],"a":0,"e":"Ctrl+A는 문서나 폴더의 모든 내용(텍스트, 파일 등)을 한 번에 선택하는 전체 선택 (Select All) 기능의 단축키이다."},{"id":"w5-19","r":5,"n":19,"s":"A","q":"스프레드시트에서 지정한 범위 중 숫자가 입력된 셀의 개수만 세는 함수는?","code":"","o":["COUNT","COUNTA","COUNTBLANK","SUM"],"a":0,"e":"COUNT 함수는 지정한 범위에서 숫자 데이터가 입력된 셀의 개수만 센다. COUNTA는 비어 있지 않은 모든 셀(문자 포함)의 개수를, COUNTBLANK는 빈 셀의 개수를 센다."},{"id":"w5-20","r":5,"n":20,"s":"A","q":"프레젠테이션 프로그램에서 모든 슬라이드에 공통으로 적용되는 배경, 글꼴, 레이아웃 등의 디자인을 일괄 관리하는 기능은?","code":"","o":["슬라이드 마스터","슬라이드 노트","슬라이드 쇼","개요 보기"],"a":0,"e":"슬라이드 마스터는 프레젠테이션 전체 슬라이드에 공통으로 적용되는 배경, 글꼴, 로고 등의 디자인 요소를 한 곳에서 일괄적으로 관리할 수 있게 해주는 기능이다."},{"id":"w5-21","r":5,"n":21,"s":"A","q":"컴퓨터의 전원 관리 옵션 중, 현재 작업 상태를 메모리에 저장한 채 저전력 상태로 전환하는 기능은?","code":"","o":["절전 모드(Sleep)","시스템 종료","다시 시작","최대 절전 모드"],"a":0,"e":"절전 모드는 현재 실행 중인 작업 상태를 메모리(RAM)에 유지한 채 화면과 일부 장치의 전원만 차단하는 저전력 상태로, 빠르게 이전 작업 상태로 복귀할 수 있다."},{"id":"w5-22","r":5,"n":22,"s":"A","q":"다음 중 웹 브라우저의 쿠키(Cookie)에 대한 설명으로 가장 옳은 것은?","code":"","o":["웹사이트가 사용자의 로그인 정보나 방문 기록 등을 저장하기 위해 사용자 컴퓨터에 저장하는 작은 데이터 파일이다","컴퓨터 바이러스의 한 종류이다","웹 서버의 물리적인 저장 장치이다","네트워크 전송 속도를 측정하는 프로그램이다"],"a":0,"e":"쿠키는 웹사이트가 사용자의 로그인 상태, 장바구니 정보, 방문 기록 등을 기억하기 위해 사용자의 브라우저(컴퓨터)에 저장하는 작은 크기의 데이터 파일이다."},{"id":"w5-23","r":5,"n":23,"s":"A","q":"다음 중 이더넷(Ethernet)에 대한 설명으로 가장 옳은 것은?","code":"","o":["유선 근거리 통신망(LAN)에서 가장 널리 사용되는 통신 규격이다","무선으로만 데이터를 전송하는 기술이다","이메일을 전송하는 프로토콜이다","이미지 파일의 압축 방식이다"],"a":0,"e":"이더넷은 랜 케이블을 이용한 유선 근거리 통신망(LAN)에서 데이터를 주고받기 위해 가장 널리 사용되는 표준 통신 규격이다."},{"id":"w5-24","r":5,"n":24,"s":"A","q":"윈도우 파일 탐색기에서 선택한 파일이나 폴더의 이름을 변경할 때 사용하는 단축키는?","code":"","o":["F1","F2","F5","F11"],"a":1,"e":"F2 키는 선택된 파일이나 폴더의 이름을 바로 편집할 수 있는 상태로 전환해 주는 단축키이다."},{"id":"w5-25","r":5,"n":25,"s":"A","q":"압축 프로그램에서 압축 파일에 암호(비밀번호)를 설정하는 주된 목적은?","code":"","o":["압축 파일 내용에 대한 접근을 허가된 사용자로 제한하기 위해","압축 파일의 크기를 더 줄이기 위해","압축 속도를 높이기 위해","파일의 확장자를 변경하기 위해"],"a":0,"e":"압축 파일에 암호를 설정하면, 올바른 암호를 입력한 사용자만 압축을 해제하여 내용을 확인할 수 있으므로 접근을 제한하고 보안을 강화하는 효과가 있다."},{"id":"w5-26","r":5,"n":26,"s":"A","q":"스프레드시트에서 특정 행이나 열을 화면에 고정하여, 스크롤해도 항상 보이도록 하는 기능은?","code":"","o":["틀 고정","셀 병합","자동 필터","조건부 서식"],"a":0,"e":"틀 고정(Freeze Panes)은 지정한 행이나 열을 고정하여, 나머지 부분을 스크롤하더라도 고정된 행·열(예: 제목 행)은 항상 화면에 표시되도록 하는 기능이다."},{"id":"w5-27","r":5,"n":27,"s":"A","q":"다음 중 사회공학적 공격 기법에 해당하지 않는 것은?","code":"","o":["피싱(Phishing)","스미싱(Smishing)","파밍(Pharming)","포트 스캐닝(Port Scanning)"],"a":3,"e":"피싱, 스미싱, 파밍은 사람의 심리를 이용해 정보를 탈취하는 사회공학적 공격 기법이다. 포트 스캐닝은 대상 시스템의 열린 포트를 탐색하는 기술적인 정찰 기법으로 사회공학적 기법으로 분류되지 않는다."},{"id":"w5-28","r":5,"n":28,"s":"A","q":"운영체제에서 여러 사용자가 하나의 시스템을 동시에 사용할 수 있도록 지원하는 방식은?","code":"","o":["다중 사용자 시스템(Multi-user)","단일 사용자 시스템","임베디드 시스템","실시간 시스템"],"a":0,"e":"다중 사용자 시스템은 여러 사용자가 동시에 하나의 컴퓨터 시스템에 접속하여 자원을 공유하며 작업할 수 있도록 지원하는 운영체제 방식이다."},{"id":"w5-29","r":5,"n":29,"s":"A","q":"다음 중 문서 파일의 확장자로 옳지 않은 것은?","code":"","o":["DOCX","HWP","PDF","PNG"],"a":3,"e":"DOCX, HWP, PDF는 대표적인 문서 파일 확장자이다. PNG는 이미지 파일의 확장자이다."},{"id":"w5-30","r":5,"n":30,"s":"A","q":"다음 중 안전한 인터넷 사용 습관으로 옳지 않은 것은?","code":"","o":["출처가 명확한 사이트에서만 파일을 다운로드한다","공용 와이파이에서는 금융 거래를 자제한다","모든 사이트에 동일한 비밀번호를 사용한다","운영체제와 소프트웨어를 최신 버전으로 유지한다"],"a":2,"e":"모든 사이트에 동일한 비밀번호를 사용하면 한 사이트에서 정보가 유출되었을 때 다른 모든 계정도 함께 위험에 노출되므로, 사이트별로 서로 다른 비밀번호를 사용하는 것이 안전하다."},{"id":"w5-31","r":5,"n":31,"s":"S","q":"위 SQL문의 실행 결과는?\n다음과 같은 PRODUCT 테이블이 있다. (1, 마우스, 50, 15000) / (2, 키보드, 30, 25000) / (3, 모니터, 10, 150000) / (4, 스피커, 0, 20000) ※(제품번호, 제품명, 재고수량, 가격)","code":"SELECT COUNT(*) FROM PRODUCT WHERE STOCK = 0;","o":["0","1","2","3"],"a":1,"e":"재고수량(STOCK)이 0인 제품은 스피커 하나뿐이므로 COUNT(*)의 결과는 1이다."},{"id":"w5-32","r":5,"n":32,"s":"S","q":"위 SQL문의 실행 결과는?\n문제 31과 동일한 PRODUCT 테이블을 사용한다.","code":"SELECT NAME FROM PRODUCT WHERE STOCK > 0 ORDER BY PRICE DESC LIMIT 1;","o":["마우스","키보드","모니터","스피커"],"a":2,"e":"재고가 0보다 큰(STOCK > 0) 제품은 마우스, 키보드, 모니터이다. 이 중 가격 (PRICE)이 가장 높은 제품은 150000원인 모니터이므로, 내림차순 정렬 후 1건만 조회하면 모니터가 반환된다."},{"id":"w5-33","r":5,"n":33,"s":"S","q":"기본키를 구성하는 속성이 하나가 아니라 두 개 이상의 컬럼으로 이루어진 경우를 무엇이라 하는가?","code":"","o":["단일키","복합키(Composite Key)","외래키","후보키"],"a":1,"e":"복합키는 두 개 이상의 속성(컬럼)을 조합하여 하나의 기본키로 사용하는 경우를 의미한다."},{"id":"w5-34","r":5,"n":34,"s":"S","q":"다음 중 SQL에서 현재 날짜와 시간을 반환하는 함수(또는 값)로 옳은 것은?","code":"","o":["SYSDATE","LENGTH()","ROUND()","UPPER()"],"a":0,"e":"SYSDATE(Oracle) 또는 NOW()(MySQL) 등은 시스템의 현재 날짜와 시간을 반환하는 함수이다. LENGTH()는 문자열 길이, ROUND()는 반올림, UPPER()는 대문자 변환 함수이다."},{"id":"w5-35","r":5,"n":35,"s":"S","q":"SQL에서 숫자를 지정한 소수 자릿수로 반올림할 때 사용하는 함수는?","code":"","o":["ROUND","TRUNC","CEIL","FLOOR"],"a":0,"e":"ROUND(숫자, 자릿수) 함수는 지정한 소수 자릿수를 기준으로 반올림한 값을 반환한다."},{"id":"w5-36","r":5,"n":36,"s":"S","q":"다음 중 뷰(VIEW)에 대한 설명으로 옳지 않은 것은?","code":"","o":["특정 사용자에게 필요한 컬럼만 보여주어 보안성을 높일 수 있다","복잡한 조인 쿼리를 단순화하여 재사용할 수 있다","실제 데이터를 저장하기 때문에 조회 속도가 원본 테이블보다 항상 빠르다","기반 테이블의 논리적 구조 변경으로부터 사용자를 어느 정도 보호해 준다(논리적 독립성)"],"a":2,"e":"뷰는 실제 데이터를 저장하지 않고, SELECT문의 정의만 저장해 두었다가 조회 시점에 실행하는 가상의 테이블이다. 따라서 뷰 자체가 조회 속도를 항상 빠르게 해준다는 설명은 옳지 않다."},{"id":"w5-37","r":5,"n":37,"s":"S","q":"SQL에서 문자열 데이터를 모두 대문자로 변환할 때 사용하는 함수는?","code":"","o":["UPPER","LOWER","TRIM","REPLACE"],"a":0,"e":"UPPER(문자열) 함수는 문자열에 포함된 모든 알파벳을 대문자로 변환하여 반환한다. LOWER()는 반대로 소문자로 변환하는 함수이다."},{"id":"w5-38","r":5,"n":38,"s":"S","q":"서브쿼리 중, 메인 쿼리의 행마다 값을 참조하여 반복적으로 실행되는 서브쿼리를 무엇이라 하는가?","code":"","o":["단일 행 서브쿼리","다중 행 서브쿼리","연관 서브쿼리(Correlated Subquery)","스칼라 서브쿼리"],"a":2,"e":"연관 서브쿼리는 메인 쿼리의 각 행에 있는 값을 서브쿼리 내부에서 참조하기 때문에, 메인 쿼리의 행 수만큼 반복적으로 실행되는 서브쿼리이다."},{"id":"w5-39","r":5,"n":39,"s":"S","q":"두 개의 SELECT문 결과 중, 첫 번째 결과에서 두 번째 결과에 포함된 행을 제외한 나머지만 반환하는 집합 연산자는?","code":"","o":["UNION","INTERSECT","MINUS","UNION ALL"],"a":2,"e":"MINUS(표준 SQL에서는 EXCEPT)는 첫 번째 SELECT문의 결과에서 두 번째 SELECT문의 결과와 공통된 행을 제외한 나머지 행만 반환하는 집합 연산자이다."},{"id":"w5-40","r":5,"n":40,"s":"S","q":"다음 중 데이터베이스 인덱스에 대한 설명으로 옳지 않은 것은?","code":"","o":["조회(SELECT) 속도를 향상시킬 수 있다","삽입·삭제·갱신 시 추가적인 유지보수 비용이 발생할 수 있다","모든 컬럼에 인덱스를 많이 설정할수록 무조건 좋다","특정 컬럼을 기준으로 생성하여 검색을 빠르게 한다"],"a":2,"e":"인덱스가 많아지면 조회 속도는 향상될 수 있지만, 데이터 삽입·삭제·수정 시마다 인덱스도 함께 갱신해야 하므로 오히려 성능이 저하될 수 있다. 따라서 인덱스를 무조건 많이 설정하는 것이 항상 좋은 것은 아니다."},{"id":"w5-41","r":5,"n":41,"s":"S","q":"테이블을 새로 생성할 때, 컬럼의 이름과 데이터 타입, 제약조건 등을 정의하는 SQL 명령어는?","code":"","o":["CREATE TABLE","ALTER TABLE","DROP TABLE","INSERT INTO"],"a":0,"e":"CREATE TABLE은 새로운 테이블을 정의하며, 이때 각 컬럼의 이름, 데이터 타입, 제약조건 등을 함께 지정한다."},{"id":"w5-42","r":5,"n":42,"s":"S","q":"DML 명령어 중, 테이블에 이미 저장되어 있는 데이터를 수정할 때 사용하는 명령어는?","code":"","o":["INSERT","UPDATE","DELETE","SELECT"],"a":1,"e":"UPDATE는 테이블에 이미 존재하는 행의 컬럼 값을 수정할 때 사용하는 DML 명령어이다."},{"id":"w5-43","r":5,"n":43,"s":"S","q":"SQL에서 두 개 이상의 컬럼을 기준으로 그룹화할 때, GROUP BY 절에 나열하는 방법으로 옳은 것은?","code":"","o":["컬럼명을 콤마(,)로 구분하여 나열한다","컬럼명을 공백으로만 구분하여 나열한다","하나의 컬럼만 지정할 수 있다","AND로 연결하여 나열한다"],"a":0,"e":"GROUP BY 절에 여러 컬럼을 지정할 때는 'GROUP BY 컬럼1, 컬럼2'와 같이 콤마로 구분하여 나열하며, 나열된 컬럼들의 조합이 같은 행끼리 하나의 그룹으로 묶인다."},{"id":"w5-44","r":5,"n":44,"s":"S","q":"다음 중 트랜잭션이 시작되는 시점에 대한 설명으로 가장 옳은 것은?","code":"","o":["하나의 논리적 작업 단위를 구성하는 최초의 DML문이 실행될 때 시작된다","데이터베이스 서버가 부팅될 때 시작된다","사용자가 로그아웃할 때 시작된다","매일 자정에 자동으로 시작된다"],"a":0,"e":"트랜잭션은 하나의 논리적인 작업 단위를 구성하는 첫 번째 DML문(INSERT, UPDATE, DELETE 등)이 실행되는 시점에 시작되며, COMMIT 또는 ROLLBACK으로 종료된다."},{"id":"w5-45","r":5,"n":45,"s":"S","q":"SQL에서 특정 조건을 만족하지 않는 경우(부정)를 표현할 때 사용하는 연산자는?","code":"","o":["AND","OR","NOT","IN"],"a":2,"e":"NOT 연산자는 조건식 앞에 붙여 그 결과를 반전시켜, 조건을 만족하지 않는 경우를 표현할 때 사용한다(예: WHERE NOT (DEPT = '영업부'))."},{"id":"w5-46","r":5,"n":46,"s":"I","q":"다음 중 여러 프로세스(또는 스레드)가 공유 자원에 동시에 접근할 때 발생하는 문제를 해결하기 위한 대표적인 기법은?","code":"","o":["세마포어(Semaphore)","페이징(Paging)","캐싱(Caching)","스풀링(Spooling)"],"a":0,"e":"세마포어는 공유 자원에 대한 접근을 제어하여 여러 프로세스(스레드) 간의 동기화 문제를 해결하는 대표적인 기법이다."},{"id":"w5-47","r":5,"n":47,"s":"I","q":"OSI 7계층 중, 사용자와 가장 가까운 계층으로 웹 브라우저나 이메일 프로그램 등이 직접 이용하는 계층은?","code":"","o":["전송 계층","세션 계층","표현 계층","응용 계층"],"a":3,"e":"응용 계층(7계층)은 사용자가 직접 상호작용하는 응용 프로그램(웹 브라우저, 이메일 클라이언트 등)이 네트워크 서비스를 이용할 수 있도록 인터페이스를 제공하는 최상위 계층이다."},{"id":"w5-48","r":5,"n":48,"s":"I","q":"다음 중 공개키(비대칭키) 암호화 방식에 대한 설명으로 가장 옳은 것은?","code":"","o":["암호화에 사용하는 키와 복호화에 사용하는 키가 서로 다르다","암호화와 복호화에 동일한 하나의 키만 사용한다","암호화 없이 데이터를 그대로 전송한다","키를 사용하지 않고 알고리즘만으로 암호화한다"],"a":0,"e":"공개키 암호화 방식은 공개키(암호화용)와 개인키(복호화용)라는 서로 다른 한 쌍의 키를 사용하는 비대칭 암호화 방식이다."},{"id":"w5-49","r":5,"n":49,"s":"I","q":"데이터베이스 설계 단계 중, 개념적 설계의 결과(ERD 등)를 특정 DBMS가 지원하는 테이블 구조로 변환하는 단계는?","code":"","o":["개념적 설계","논리적 설계","물리적 설계","요구사항 분석"],"a":1,"e":"논리적 설계 단계에서는 개념적 설계에서 도출된 개체와 관계를 특정 DBMS의 자료구조(관계형 데이터베이스의 경우 테이블)로 변환하는 작업을 수행한다."},{"id":"w5-50","r":5,"n":50,"s":"I","q":"사용자 요구사항을 초기에 시제품(프로토타입)으로 신속하게 만들어 사용자의 피드백을 받으며 개선해 나가는 소프트웨어 개발 모델은?","code":"","o":["폭포수 모델","프로토타입 모델","V모델","스크럼(애자일)"],"a":1,"e":"프로토타입 모델은 요구사항이 불명확할 때, 핵심 기능만 담은 시제품을 빠르게 제작 하여 사용자의 피드백을 받고 이를 반영해 점진적으로 완성해 나가는 개발 모델이다."},{"id":"w5-51","r":5,"n":51,"s":"I","q":"다중 프로그래밍 환경에서 메모리 부족으로 인해 페이지 교체 작업에 대부분의 시간을 소모하여 시스템 성능이 급격히 저하되는 현상은?","code":"","o":["교착상태(Deadlock)","기아 현상(Starvation)","스래싱(Thrashing)","세그멘테이션"],"a":2,"e":"스래싱은 메모리(페이지 프레임)가 부족하여 프로세스들이 실제 작업보다 페이지 교체(입출력)에 더 많은 시간을 소비하게 되어, 전체 시스템의 처리 성능이 급격히 떨어지는 현상이다."},{"id":"w5-52","r":5,"n":52,"s":"I","q":"다음 중 대칭키(비밀키) 암호화 방식의 특징으로 가장 옳은 것은?","code":"","o":["암호화와 복호화에 동일한 키를 사용한다","암호화와 복호화에 서로 다른 키를 사용한다","키가 필요하지 않다","두 개 이상의 키 쌍이 필요하다"],"a":0,"e":"대칭키 암호화 방식은 암호화할 때와 복호화할 때 동일한 하나의 키(비밀키)를 사용 하는 방식이다."},{"id":"w5-53","r":5,"n":53,"s":"I","q":"관계형 데이터베이스에서 두 개 이상의 속성을 묶어 기본키로 사용하는 경우, 이 키를 무엇이라 하는가?","code":"","o":["단일키","대체키","복합키(Composite Key)","슈퍼키"],"a":2,"e":"복합키는 하나의 속성만으로는 각 행을 유일하게 식별할 수 없을 때, 두 개 이상의 속성을 조합하여 기본키로 사용하는 키를 의미한다."},{"id":"w5-54","r":5,"n":54,"s":"I","q":"다음 중 컴퓨터의 처리 성능을 향상시키는 병렬 처리 기술과 가장 거리가 먼 것은?","code":"","o":["멀티코어 프로세서","클러스터링","분산 처리","순차 처리"],"a":3,"e":"멀티코어 프로세서, 클러스터링, 분산 처리는 여러 처리 단위를 동시에 활용하여 성능 을 높이는 병렬 처리 기술이다. 순차 처리는 작업을 하나씩 차례로 처리하는 방식으로 병렬 처리와는 거리가 멀다."},{"id":"w5-55","r":5,"n":55,"s":"I","q":"개발사의 통제된 환경에서 실제 고객(사용자) 일부를 초청하여 수행하는 테스트는?","code":"","o":["알파 테스트","베타 테스트","단위 테스트","시스템 테스트"],"a":0,"e":"알파 테스트는 개발자(개발사)의 통제된 환경 내부에서 실제 사용자를 초청하여 진행 하는 테스트이다. 베타 테스트는 통제되지 않은 실제 사용 환경에서 다수의 사용자가 참여하여 수행한다."},{"id":"w5-56","r":5,"n":56,"s":"I","q":"다음 중 엣지 컴퓨팅(Edge Computing)에 대한 설명으로 가장 옳은 것은?","code":"","o":["모든 데이터를 반드시 중앙 서버에서만 처리하는 방식이다","데이터가 발생하는 현장(단말)에 가까운 곳에서 데이터를 처리하는 방식이다","데이터를 암호화하여 저장하는 기술이다","네트워크 속도를 인위적으로 늦추는 기술이다"],"a":1,"e":"엣지 컴퓨팅은 데이터를 중앙의 클라우드 서버까지 보내지 않고, 데이터가 발생하는 현장(기기, 단말)과 가까운 곳에서 실시간으로 처리하여 지연시간을 줄이는 컴퓨팅 방식이다."},{"id":"w5-57","r":5,"n":57,"s":"I","q":"네트워크에서 전송할 데이터를 일정한 크기의 작은 단위로 나누어 전송하는 방식을 무엇이라 하는가?","code":"","o":["회선 교환 방식","패킷 교환 방식","아날로그 전송 방식","단방향 전송 방식"],"a":1,"e":"패킷 교환 방식은 전송할 데이터를 패킷이라는 일정한 크기의 단위로 나누어 전송하고, 수신 측에서 이를 다시 조립하는 방식으로, 현재 인터넷의 기본적인 데이터 전송 방식이다."},{"id":"w5-58","r":5,"n":58,"s":"I","q":"소프트웨어 테스트 원칙 중, 결함을 발견하지 못했다고 해서 소프트웨어에 결함이 없다고 확신할 수 없다는 원칙은?","code":"","o":["결함 집중(파레토 법칙)","살충제 패러독스","오류-부재의 궤변","테스트의 경제성 원칙"],"a":2,"e":"오류-부재의 궤변은 테스트를 통해 결함을 발견하지 못했더라도, 그것이 소프트웨어에 결함이 전혀 없다는 것을 의미하지는 않는다는 원칙이다. 요구사항을 충족하지 못하면 결함이 없어도 사용자가 만족하지 않을 수 있다."},{"id":"w5-59","r":5,"n":59,"s":"I","q":"두 개 이상의 프로세스가 서로 상대방이 점유한 자원의 반납을 무한정 기다리며 진행이 멈추는 상태는?","code":"","o":["교착상태(Deadlock)","기아 현상","스래싱","컨텍스트 스위칭"],"a":0,"e":"교착상태는 두 개 이상의 프로세스가 서로 상대방이 점유하고 있는 자원을 요청하며 무한정 대기하는 상태로, 상호 배제·점유와 대기·비선점·순환 대기의 네 가지 조건이 동시에 성립할 때 발생한다."},{"id":"w5-60","r":5,"n":60,"s":"I","q":"다음 중 디지털 전환(Digital Transformation)에 대한 설명으로 가장 옳은 것은?","code":"","o":["디지털 기술을 활용하여 기존의 비즈니스 모델과 프로세스를 혁신하는 것이다","아날로그 신호를 디지털 신호로 단순 변환하는 것만을 의미한다","컴퓨터를 처음 도입하는 것을 의미한다","종이 문서를 스캔하여 파일로 저장하는 것만을 의미한다"],"a":0,"e":"디지털 전환은 단순한 디지털화(아날로그→디지털 변환)를 넘어, 디지털 기술을 전략적으로 활용하여 조직의 비즈니스 모델, 프로세스, 문화 전반을 혁신하는 것을 의미한다."}];
window.SQ=[{"id":"s1-01","r":1,"n":1,"type":"C - 출력 예측","pt":8,"q":"위 C 프로그램의 실행 결과를 쓰시오.","code":"#include <stdio.h>\nint main() {\n      int i, sum = 0;\n      for (i = 1; i <= 5; i++) {\n            sum += i * 2;\n      }\n      printf(\"%d\\n\", sum);\n      return 0;\n}","a":"30","acode":"","e":"i가 1부터 5까지 증가하면서 각 i의 2배 값을 sum에 누적한다. (1+2+3+4+5)×2 = 15×2 = 30이 출력된다.","g":"C"},{"id":"s1-02","r":1,"n":2,"type":"C - 빈칸 채우기","pt":8,"q":"다음은 1부터 10까지의 합을 구하는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"#include <stdio.h>\nint main() {\n      int i, sum = 0;\n      for (i = 1; i <= 10; i++) {\n            ( ① )\n      }\n      printf(\"%d\", sum);\n      return 0;\n}","a":"","acode":"sum += i;","e":"반복문이 실행될 때마다 sum에 현재 i의 값을 누적해서 더해야(sum += i; 또는 sum = sum + i;) 1부터 10까지의 합계를 구할 수 있다.","g":"C"},{"id":"s1-03","r":1,"n":3,"type":"Java - 출력 예측","pt":8,"q":"위 Java 프로그램의 실행 결과를 쓰시오.","code":"public class Test {\n      public static void main(String[] args) {\n            int[] nums = {4, 8, 15, 16, 23};\n            int result = 0;\n            for (int i = 0; i < nums.length; i++) {\n                 if (nums[i] % 2 == 0) {\n                      result += nums[i];\n                 }\n            }\n            System.out.println(result);\n      }\n}","a":"28","acode":"","e":"배열 nums의 요소 중 짝수인 값(4, 8, 16)만 골라 result에 더한다. 4+8+16=28이 출력된다.","g":"J"},{"id":"s1-04","r":1,"n":4,"type":"Java - 디버깅","pt":9,"q":"다음 프로그램은 1부터 n까지의 팩토리얼(n!)을 구하려는 의도로 작성되었으나, 실행하면 항상 결과가 0으로 출력되는 오류가 있다. 오류가 있는 줄을 찾아 올바르게 수정하시오.","code":"public class Test {\n      public static void main(String[] args) {\n            int n = 5;\n            int result = 0;\n            for (int i = 1; i <= n; i++) {\n                 result *= i;\n            }\n            System.out.println(result);\n      }\n}","a":"","acode":"int result = 0;   →   int result = 1;","e":"result의 초깃값이 0이면 반복문에서 어떤 값을 곱하더라도 항상 0이 된다(0 × i = 0). 곱셈의 항등원인 1로 초기화해야 5! = 120이 올바르게 계산된다.","g":"J"},{"id":"s1-05","r":1,"n":5,"type":"Python - 출력 예측","pt":8,"q":"위 Python 프로그램의 실행 결과를 쓰시오.","code":"def process(lst):\n   result = []\n   for x in lst:\n         if x > 0:\n              result.append(x * x)\n   return result\n\nprint(process([-2, 3, -1, 4, 0]))","a":"[9, 16]","acode":"","e":"x > 0을 만족하는 값(3, 4)만 제곱하여 result 리스트에 추가한다. -2, -1, 0은 조건을 만족하지 않으므로 제외되어 최종 결과는 [9, 16]이다.","g":"Y"},{"id":"s1-06","r":1,"n":6,"type":"Python - 빈칸 채우기","pt":9,"q":"다음은 리스트에서 최댓값을 찾는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"def find_max(lst):\n   max_val = lst[0]\n   for x in lst:\n         if x > max_val:\n              ( ① )\n   return max_val\n\nprint(find_max([3, 7, 2, 9, 4]))","a":"","acode":"max_val = x","e":"현재 값 x가 지금까지의 최댓값(max_val)보다 크면 max_val을 x로 갱신해야 리스트 전체에서 최댓값 을 올바르게 찾을 수 있다.","g":"Y"},{"id":"s1-07","r":1,"n":7,"type":"SQL - DDL 작성","pt":8,"q":"다음 조건을 만족하는 CREATE TABLE문을 작성하시오.\n- 테이블명: MEMBER\n- 컬럼: ID(정수, 기본키) / NAME(가변길이 문자열 20자, NOT NULL) / JOIN_DATE(날짜)\n위 조건을 만족하는 CREATE TABLE문을 작성하시오.","code":"","a":"","acode":"CREATE TABLE MEMBER (\n     ID INT PRIMARY KEY,\n     NAME VARCHAR(20) NOT NULL,\n     JOIN_DATE DATE\n);","e":"ID 컬럼에 PRIMARY KEY 제약조건을 지정하여 기본키로 설정하고, NAME 컬럼에는 NOT NULL 제약조건을 지정하여 값이 반드시 입력되도록 한다.","g":"Q"},{"id":"s1-08","r":1,"n":8,"type":"SQL - DML 작성","pt":9,"q":"EMPLOYEE 테이블(NAME, DEPT, SALARY)에서 SALARY가 3000 이상인 사원의 NAME과 SALARY 를 SALARY 기준 내림차순으로 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT NAME, SALARY\nFROM EMPLOYEE\nWHERE SALARY >= 3000\nORDER BY SALARY DESC;","e":"WHERE 절로 SALARY >= 3000 조건을 지정하고, ORDER BY SALARY DESC로 결과를 급여 내림차순으로 정렬한다.","g":"Q"},{"id":"s1-09","r":1,"n":9,"type":"SQL - JOIN 작성","pt":9,"q":"다음 두 테이블이 있다.\nSTUDENT(S_ID, NAME), ENROLL(S_ID, COURSE)\n두 테이블을 INNER JOIN으로 연결하여, 각 학생의 이름(NAME)과 수강 과목(COURSE)을 함께 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT S.NAME, E.COURSE\nFROM STUDENT S\nINNER JOIN ENROLL E ON S.S_ID = E.S_ID;","e":"STUDENT와 ENROLL 테이블에 공통으로 존재하는 S_ID 컬럼을 기준으로 INNER JOIN을 수행하여, 각 학생의 이름과 수강 과목을 함께 조회한다.","g":"Q"},{"id":"s1-10","r":1,"n":10,"type":"응용SW/테스트 - 서술형","pt":8,"q":"화이트박스 테스트 기법 중, 프로그램 내 모든 조건문의 참(True)과 거짓(False) 분기가 각각 한 번 이상 실행되도록 테스트 케이스를 설계하는 커버리지 기법의 명칭을 쓰시오.","code":"","a":"결정 커버리지(Decision Coverage, 분기 커버리지)","acode":"","e":"결정 커버리지는 프로그램 내 모든 조건문(if, while 등)에서 참과 거짓 분기가 각각 최소 한 번 이상 실행되도록 테스트 케이스를 설계하는 화이트박스 테스트 기법이다.","g":"T"},{"id":"s1-11","r":1,"n":11,"type":"응용SW/테스트 - 서술형","pt":8,"q":"하향식 통합 테스트에서, 아직 개발되지 않은 하위 모듈을 대신하여 임시로 값을 반환하는 역할을 하는 모듈의 명칭을 쓰시오.","code":"","a":"스텁(Stub)","acode":"","e":"스텁은 하향식 통합 테스트를 진행할 때, 아직 완성되지 않은 하위 모듈을 대신하여 상위 모듈이 호출할 수 있도록 임시로 값을 반환해 주는 모듈이다.","g":"T"},{"id":"s1-12","r":1,"n":12,"type":"응용SW/테스트 - 서술형","pt":8,"q":"결함 관리 프로세스에서, 결함이 등록(Open)된 이후 담당자에게 배정되는 상태를 무엇이라 하는지 쓰시오.\nⅠ. 문제","code":"","a":"할당(Assigned)","acode":"","e":"결함의 상태는 일반적으로 등록(Open) → 할당(Assigned) → 수정(Fixed) → 확인(재테스트) → 종료 (Closed)의 순서로 진행되며, 필요시 재오픈(Reopened)될 수 있다.","g":"T"},{"id":"s2-01","r":2,"n":1,"type":"C - 출력 예측","pt":8,"q":"위 C 프로그램의 실행 결과를 쓰시오.","code":"#include <stdio.h>\nint main() {\n      int arr[5] = {1, 2, 3, 4, 5};\n      int sum = 0;\n      for (int i = 0; i < 5; i++) {\n            if (i % 2 == 1) sum += arr[i];\n      }\n      printf(\"%d\", sum);\n      return 0;\n}","a":"6","acode":"","e":"인덱스 i가 홀수(1, 3)일 때의 배열 값만 더한다. arr[1]=2, arr[3]=4이므로 2+4=6이 출력된다.","g":"C"},{"id":"s2-02","r":2,"n":2,"type":"C - 빈칸 채우기","pt":8,"q":"다음은 배열에서 짝수의 개수를 세는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"#include <stdio.h>\nint main() {\n      int arr[6] = {3, 8, 5, 2, 9, 4};\n      int count = 0;\n      for (int i = 0; i < 6; i++) {\n            if (arr[i] % 2 == 0) {\n                 ( ① )\n            }\n      }\n      printf(\"%d\", count);\n      return 0;\n}","a":"","acode":"count++;","e":"배열 요소가 짝수 조건을 만족할 때마다 count를 1씩 증가(count++; 또는 count = count + 1;)시켜야 짝수의 개수를 셀 수 있다.","g":"C"},{"id":"s2-03","r":2,"n":3,"type":"Java - 출력 예측","pt":8,"q":"위 Java 프로그램의 실행 결과를 쓰시오.","code":"public class Test {\n      public static void main(String[] args) {\n            String s = \"Programming\";\n            System.out.println(s.substring(3, 7));\n      }\n}","a":"gram","acode":"","e":"substring(3, 7)은 인덱스 3부터 6까지(7은 포함하지 않음)의 문자를 추출한다. 'Programming'에서 인덱스 3~6에 해당하는 문자는 g, r, a, m이므로 'gram'이 출력된다.","g":"J"},{"id":"s2-04","r":2,"n":4,"type":"Java - 디버깅","pt":9,"q":"다음 프로그램은 배열의 최댓값을 찾으려는 의도로 작성되었으나, 오류로 인해 항상 배열의 첫 번째 값만 출력된다. 오류가 있는 줄을 찾아 올바르게 수정하시오.","code":"public class Test {\n      public static void main(String[] args) {\n            int[] arr = {5, 12, 8, 20, 3};\n            int max = arr[0];\n            for (int i = 0; i < arr.length; i++) {\n                 if (arr[i] > max) {\n                      int max = arr[i];\n                 }\n            }\n            System.out.println(max);\n      }\n}","a":"","acode":"int max = arr[i];   →   max = arr[i];","e":"if문 내부에서 'int max'로 다시 선언하면 바깥의 max와는 별개인 새 지역변수가 생성되어 블록을 벗어 나면 사라지므로 바깥의 max는 갱신되지 않는다. 새로 선언하지 않고 이미 선언된 max 변수에 값만 대입해야최댓값이 올바르게 갱신된다.","g":"J"},{"id":"s2-05","r":2,"n":5,"type":"Python - 출력 예측","pt":8,"q":"위 Python 프로그램의 실행 결과를 쓰시오.","code":"def count_vowels(word):\n   vowels = \"aeiou\"\n   count = 0\n   for ch in word:\n         if ch in vowels:\n              count += 1\n   return count\n\nprint(count_vowels(\"beautiful\"))","a":"5","acode":"","e":"'beautiful'의 각 문자 중 모음(a, e, i, o, u)에 해당하는 것은 e, a, u, i, u로 총 5개이다.","g":"Y"},{"id":"s2-06","r":2,"n":6,"type":"Python - 빈칸 채우기","pt":9,"q":"다음은 리스트의 모든 요소를 곱한 값을 구하는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"def product(lst):\n   result = 1\n   for x in lst:\n         ( ① )\n   return result\n\nprint(product([2, 3, 4]))","a":"","acode":"result *= x","e":"각 요소 x를 result에 누적하여 곱해야(result *= x; 또는 result = result * x) 리스트 전체 요소의 곱을 구할 수 있다. result의 초깃값이 1인 이유는 곱셈의 항등원이기 때문이다.","g":"Y"},{"id":"s2-07","r":2,"n":7,"type":"SQL - DDL 작성","pt":8,"q":"이미 생성되어 있는 PRODUCT 테이블에 다음 조건을 만족하는 컬럼을 추가하는 SQL문을 작성하시오.\n- 추가할 컬럼: DISCOUNT_RATE(정수형), 값이 입력되지 않으면 기본값 0이 저장되도록 지정\n위 조건을 만족하는 SQL문을 작성하시오.","code":"","a":"","acode":"ALTER TABLE PRODUCT ADD DISCOUNT_RATE INT DEFAULT 0;","e":"ALTER TABLE ~ ADD 구문으로 기존 테이블에 새 컬럼을 추가할 수 있으며, DEFAULT 0을 지정하면 값이 입력되지 않을 때 자동으로 0이 저장된다.","g":"Q"},{"id":"s2-08","r":2,"n":8,"type":"SQL - DML 작성","pt":9,"q":"ORDERS 테이블(CUSTOMER, AMOUNT)에서 고객별 총 주문 금액(AMOUNT의 합)을 구하되, 총 금액이 50000 이상인 고객만 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT CUSTOMER, SUM(AMOUNT)\nFROM ORDERS\nGROUP BY CUSTOMER\nHAVING SUM(AMOUNT) >= 50000;","e":"CUSTOMER별로 그룹화(GROUP BY)한 뒤 SUM(AMOUNT)으로 합계를 구하고, 그룹화된 결과에 조건을 적용하는 HAVING 절로 합계가 50000 이상인 고객만 필터링한다.","g":"Q"},{"id":"s2-09","r":2,"n":9,"type":"SQL - 서브쿼리 작성","pt":9,"q":"EMPLOYEE 테이블(NAME, DEPT, SALARY)에서, 전체 사원의 평균 급여보다 높은 급여를 받는 사원의 NAME을 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT NAME\nFROM EMPLOYEE\nWHERE SALARY > (SELECT AVG(SALARY) FROM EMPLOYEE);","e":"서브쿼리 (SELECT AVG(SALARY) FROM EMPLOYEE)로 전체 사원의 평균 급여를 구한 뒤, 메인 쿼리의 WHERE 절에서 이 값보다 SALARY가 큰 사원만 조회한다.","g":"Q"},{"id":"s2-10","r":2,"n":10,"type":"응용SW/테스트 - 서술형","pt":8,"q":"테스트 오라클의 4가지 종류 중, 전체 입력값이 아닌 일부(샘플)에 대해서만 기대 결과를 제공하는 오라클의 명칭을 쓰시오.","code":"","a":"샘플링 오라클(Sampling Oracle)","acode":"","e":"샘플링 오라클은 모든 입력값에 대한 기대 결과를 제공하는 참 오라클과 달리, 전체 입력값 중 일부(샘플) 에 대해서만 기대 결과를 제공하는 오라클이다.","g":"T"},{"id":"s2-11","r":2,"n":11,"type":"응용SW/테스트 - 서술형","pt":8,"q":"코드 검토 기법인 인스펙션과 워크스루의 차이점 중, 체크리스트 사용 여부에 대해 서술하시오.","code":"","a":"인스펙션은 체크리스트를 사용하고, 워크스루는 체크리스트를 사용하지 않는다.","acode":"","e":"인스펙션은 정해진 체크리스트를 기준으로 검토를 진행하는 공식적인 검토 기법인 반면, 워크스루는 저자(작성자)가 주도하는 검토 회의로 체크리스트를 사용하지 않는다는 차이가 있다.","g":"T"},{"id":"s2-12","r":2,"n":12,"type":"응용SW/테스트 - 서술형","pt":8,"q":"소프트웨어 형상 관리에서, 정식으로 검토되고 승인된 특정 시점의 형상을 지칭하는 용어를 쓰시오.\nⅠ. 문제","code":"","a":"기준선(Baseline)","acode":"","e":"기준선은 정식으로 검토되고 승인된 특정 시점의 형상 항목을 의미하며, 이후의 모든 변경은 정해진 절차를 통해서만 가능하도록 통제하는 기준이 된다.","g":"T"},{"id":"s3-01","r":3,"n":1,"type":"C - 출력 예측","pt":8,"q":"위 C 프로그램의 실행 결과를 쓰시오.","code":"#include <stdio.h>\nint main() {\n      int n = 7, count = 0;\n      while (n > 0) {\n            n = n / 2;\n            count++;\n      }\n      printf(\"%d\", count);\n      return 0;\n}","a":"3","acode":"","e":"n은 7→3→1→0(정수 나눗셈)으로 변화하며, 이 과정에서 count는 3번 증가한다(7/2=3, 3/2=1, 1/2=0). n이 0이 되는 순간 반복이 종료되어 count는 3이 된다.","g":"C"},{"id":"s3-02","r":3,"n":2,"type":"C - 빈칸 채우기","pt":8,"q":"다음은 두 정수 중 더 작은 값을 찾는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"#include <stdio.h>\nint main() {\n      int a = 15, b = 9, min;\n      if (a < b) {\n            min = a;\n      } else {\n            ( ① )\n      }\n      printf(\"%d\", min);\n      return 0;\n}","a":"","acode":"min = b;","e":"a가 b보다 작지 않은 경우(else)에는 b가 더 작거나 같은 값이므로 min에 b를 대입해야 두 값 중 작은 값을 올바르게 구할 수 있다.","g":"C"},{"id":"s3-03","r":3,"n":3,"type":"Java - 출력 예측","pt":8,"q":"위 Java 프로그램의 실행 결과를 쓰시오.","code":"public class Test {\n      public static void main(String[] args) {\n            int a = 10;\n            int b = 3;\n            System.out.println(a / b + \" \" + a % b);\n      }\n}","a":"31","acode":"","e":"정수형 나눗셈이므로 a / b는 10 / 3 = 3(소수점 이하 버림)이고, a % b는 10을 3으로 나눈 나머지인 1 이다. 문자열 연결에 의해 \"3 1\"이 출력된다.","g":"J"},{"id":"s3-04","r":3,"n":4,"type":"Java - 디버깅","pt":9,"q":"다음 프로그램은 1부터 10까지의 숫자 중 짝수만 출력하려는 의도로 작성되었으나, 실행하면 홀수가 출력된다. 오류가 있는 줄을 찾아 올바르게 수정하시오.","code":"public class Test {\n      public static void main(String[] args) {\n            for (int i = 1; i <= 10; i++) {\n                 if (i % 2 == 1) {\n                      System.out.print(i + \" \");\n                 }\n            }\n      }\n}","a":"","acode":"if (i % 2 == 1) {   →   if (i % 2 == 0) {","e":"i % 2 == 1은 i가 홀수일 때 참이 되는 조건이다. 짝수만 출력하려면 나머지가 0인 경우를 확인하는 i % 2 == 0으로 조건을 수정해야 한다.","g":"J"},{"id":"s3-05","r":3,"n":5,"type":"Python - 출력 예측","pt":8,"q":"위 Python 프로그램의 실행 결과를 순서대로 쓰시오.","code":"def is_palindrome(s):\n      return s == s[::-1]\n\nprint(is_palindrome(\"level\"))\nprint(is_palindrome(\"hello\"))","a":"True, False (순서대로)","acode":"","e":"s[::-1]은 문자열을 뒤집은 결과이다. 'level'은 뒤집어도 동일하므로 True, 'hello'는 뒤집으면 'olleh'로 원래와 다르므로 False가 출력된다.","g":"Y"},{"id":"s3-06","r":3,"n":6,"type":"Python - 빈칸 채우기","pt":9,"q":"다음은 리스트에서 특정 값의 위치(인덱스)를 찾는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"def find_index(lst, target):\n   for i in range(len(lst)):\n         if lst[i] == target:\n              ( ① )\n   return -1\n\nprint(find_index([10, 20, 30, 40], 30))","a":"","acode":"return i","e":"lst[i]가 target과 일치하는 순간의 인덱스 i를 즉시 반환(return i)해야 target이 위치한 인덱스를 올바르게 찾을 수 있다. 찾지 못하면 반복문이 끝난 뒤 -1이 반환된다.","g":"Y"},{"id":"s3-07","r":3,"n":7,"type":"SQL - DDL 작성","pt":8,"q":"다음 조건을 만족하도록 EMPLOYEE 테이블의 제약조건을 변경하는 SQL문을 작성하시오.\n- 테이블명: EMPLOYEE\n- 변경 내용: EMAIL 컬럼에 UNIQUE 제약조건 추가\n위 조건을 만족하는 SQL문을 작성하시오.","code":"","a":"","acode":"ALTER TABLE EMPLOYEE ADD CONSTRAINT UQ_EMAIL UNIQUE (EMAIL);","e":"ALTER TABLE ~ ADD CONSTRAINT 구문을 이용해 이미 존재하는 테이블의 특정 컬럼에 UNIQUE 제약조건을 추가로 지정할 수 있다.","g":"Q"},{"id":"s3-08","r":3,"n":8,"type":"SQL - DML 작성","pt":9,"q":"BOOK 테이블(TITLE, CATEGORY, PRICE)에서, CATEGORY가 '소설'이거나 PRICE가 20000 이하인도서의 TITLE을 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT TITLE\nFROM BOOK\nWHERE CATEGORY = '소설' OR PRICE <= 20000;","e":"두 조건(CATEGORY='소설', PRICE<=20000) 중 하나라도 만족하면 결과에 포함되어야 하므로 OR 연산자로 두 조건을 연결한다.","g":"Q"},{"id":"s3-09","r":3,"n":9,"type":"SQL - 서브쿼리 작성","pt":9,"q":"DEPT_MASTER(DEPT_NAME) 테이블과 EMPLOYEE(NAME, DEPT_NAME) 테이블이 있다. DEPT_MASTER에는 존재하지만 EMPLOYEE에는 소속된 사원이 한 명도 없는 부서명을 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT DEPT_NAME\nFROM DEPT_MASTER\nWHERE DEPT_NAME NOT IN (SELECT DEPT_NAME FROM EMPLOYEE);","e":"서브쿼리로 EMPLOYEE 테이블에 실제로 존재하는 부서명 목록을 구한 뒤, NOT IN 연산자를 이용해 DEPT_MASTER의 부서명 중 그 목록에 포함되지 않는(사원이 없는) 부서명만 조회한다.","g":"Q"},{"id":"s3-10","r":3,"n":10,"type":"응용SW/테스트 - 서술형","pt":8,"q":"통합 테스트 방식 중, 최하위 모듈부터 상위 모듈 방향으로 점진적으로 통합하며 테스트하는 방식의 명칭과, 이때 필요한 임시 모듈의 명칭을 각각 쓰시오.","code":"","a":"상향식 통합 테스트, 드라이버(Driver)","acode":"","e":"상향식 통합은 최하위 모듈에서 상위 모듈로 통합해 나가는 방식으로, 아직 개발되지 않은 상위 모듈을 대신하여 하위 모듈을 호출하는 드라이버가 필요하다.","g":"T"},{"id":"s3-11","r":3,"n":11,"type":"응용SW/테스트 - 서술형","pt":8,"q":"결함의 심각도(Severity)와 우선순위(Priority)의 차이를 한 문장으로 서술하시오.","code":"","a":"심각도는 결함이 시스템에 미치는 기술적 영향의 크기를 의미하고, 우선순위는 그 결함을 얼마나 빨리 수정","acode":"해야 하는지를 나타내는 순위를 의미한다.","e":"심각도가 높아도 우선순위가 낮을 수 있고(예: 매우 드물게 발생하는 심각한 오류), 반대로 심각도는 낮지만 우선순위가 높은 경우(예: 첫 화면의 사소한 오타)도 있을 수 있다는 점에서 두 개념은 구분된다.","g":"T"},{"id":"s3-12","r":3,"n":12,"type":"응용SW/테스트 - 서술형","pt":8,"q":"데이터베이스 정규화 과정에서, 테이블의 모든 속성 값이 원자값(더 이상 분해할 수 없는 값)으로만 구성되어야 한다는 조건을 만족하는 정규형의 명칭을 쓰시오.\nⅠ. 문제","code":"","a":"제1정규형(1NF)","acode":"","e":"제1정규형은 정규화의 가장 기본이 되는 단계로, 테이블의 모든 속성이 원자값으로만 구성되어야 한다는 조건을 만족해야 한다.","g":"T"},{"id":"s4-01","r":4,"n":1,"type":"C - 출력 예측","pt":8,"q":"위 C 프로그램의 실행 결과를 쓰시오.","code":"#include <stdio.h>\nint main() {\n      int arr[4] = {1, 2, 3, 4};\n      int *p = arr;\n      int sum = 0;\n      for (int i = 0; i < 4; i++) {\n            sum += *(p + i);\n      }\n      printf(\"%d\", sum);\n      return 0;\n}","a":"10","acode":"","e":"포인터 p는 배열 arr의 첫 주소를 가리킨다. *(p+i)는 arr[i]와 같은 의미이므로, 반복문은 arr의 모든 요소(1,2,3,4)를 더한다. 1+2+3+4=10이 출력된다.","g":"C"},{"id":"s4-02","r":4,"n":2,"type":"C - 빈칸 채우기","pt":8,"q":"다음은 두 변수의 값을 서로 교환(swap)하는 함수이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"#include <stdio.h>\nvoid swap(int *a, int *b) {\n      int temp = *a;\n      *a = *b;\n      ( ① )\n}\nint main() {\n      int x = 3, y = 9;\n      swap(&x, &y);\n      printf(\"%d %d\", x, y);\n      return 0;\n}","a":"","acode":"*b = temp;","e":"temp에 저장해 두었던 원래 *a의 값을 *b에 대입해야 두 변수의 값이 올바르게 교환된다. 이 코드가 없으면 *b의 값이 *a로 덮어써진 뒤 원래 값을 복원할 수 없다.","g":"C"},{"id":"s4-03","r":4,"n":3,"type":"Java - 출력 예측","pt":8,"q":"위 Java 프로그램의 실행 결과를 쓰시오.","code":"public class Test {\n      public static void main(String[] args) {\n            int n = 4;\n            int result = 1;\n            int i = 1;\n            while (i <= n) {\n                 result = result * i;\n                 i++;\n            }\n            System.out.println(result);\n      }\n}","a":"24","acode":"","e":"이 프로그램은 4의 팩토리얼(4!)을 계산한다. 1×1×2×3×4 = 24가 출력된다.","g":"J"},{"id":"s4-04","r":4,"n":4,"type":"Java - 디버깅","pt":9,"q":"다음 프로그램은 두 정수를 나눈 몫과 나머지를 각각 출력하려는 의도로 작성되었으나, 실행하면 프로그램이 비정상 종료(예외 발생)된다. 오류의 원인을 쓰고, 이를 해결하기 위해 코드를 어떻게 수정해야 하는지 서술하시오.\n오류의 원인과 해결 방법을 서술하시오.","code":"public class Test {\n      public static void main(String[] args) {\n            int a = 10;\n            int b = 0;\n            System.out.println(a / b);\n      }\n}","a":"0으로 나누었기 때문에 ArithmeticException(산술 예외)이 발생한다. b의 값이 0인지 미리 검사하거나,","acode":"try-catch문으로 예외를 처리하도록 수정해야 한다.","e":"정수를 0으로 나누는 연산은 수학적으로 정의되지 않으므로 Java에서는 ArithmeticException을 발생시킨다. b가 0인 경우를 사전에 조건문으로 걸러내거나, try-catch 구문을 사용해 예외 발생 시 적절히 처리하도록 코드를 수정해야 한다.","g":"J"},{"id":"s4-05","r":4,"n":5,"type":"Python - 출력 예측","pt":8,"q":"위 Python 프로그램의 실행 결과를 쓰시오.","code":"def merge_dict(d1, d2):\n   result = d1.copy()\n   result.update(d2)\n   return result\n\na = {'x': 1, 'y': 2}\nb = {'y': 20, 'z': 30}\nprint(merge_dict(a, b))","a":"{'x': 1, 'y': 20, 'z': 30}","acode":"","e":"update() 메서드는 d1의 복사본에 d2의 키-값 쌍을 병합하되, 동일한 키('y')가 있으면 d2의 값(20)으로 덮어쓴다. 결과는 {'x': 1, 'y': 20, 'z': 30}이다.","g":"Y"},{"id":"s4-06","r":4,"n":6,"type":"Python - 빈칸 채우기","pt":9,"q":"다음은 리스트에서 중복된 값을 제거하는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"def remove_duplicates(lst):\n   result = []\n   for x in lst:\n         if x not in result:\n              ( ① )\n   return result\n\nprint(remove_duplicates([1, 2, 2, 3, 1, 4]))","a":"","acode":"result.append(x)","e":"result 리스트에 아직 x가 없는 경우에만 x를 추가(result.append(x))해야 중복 없이 처음 등장한 순서대로 값을 모을 수 있다.","g":"Y"},{"id":"s4-07","r":4,"n":7,"type":"SQL - DDL 작성","pt":8,"q":"다음 조건을 만족하는 CREATE TABLE문을 작성하시오.\n- 테이블명: ORDERS\n- 컬럼: ORDER_ID(정수, 기본키), CUSTOMER_ID(정수, NOT NULL), AMOUNT(정수, 0 이상의 값만 허용)\n위 조건을 만족하는 CREATE TABLE문을 작성하시오.","code":"","a":"","acode":"CREATE TABLE ORDERS (\n     ORDER_ID INT PRIMARY KEY,\n     CUSTOMER_ID INT NOT NULL,\n     AMOUNT INT CHECK (AMOUNT >= 0)\n);","e":"ORDER_ID에 PRIMARY KEY를, CUSTOMER_ID에 NOT NULL을 지정하고, AMOUNT 컬럼에는 CHECK 제약조건을 이용해 0 이상의 값만 저장될 수 있도록 제한한다.","g":"Q"},{"id":"s4-08","r":4,"n":8,"type":"SQL - DML 작성","pt":9,"q":"STUDENT 테이블(NAME, GRADE, SCORE)에서 학년(GRADE)별 평균 점수(SCORE)를 구하고, 그 결과를 평균 점수가 높은 순으로 정렬하여 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT GRADE, AVG(SCORE)\nFROM STUDENT\nGROUP BY GRADE\nORDER BY AVG(SCORE) DESC;","e":"GROUP BY GRADE로 학년별 그룹을 만들고 AVG(SCORE)로 평균을 구한 뒤, ORDER BY AVG(SCORE) DESC로 평균 점수가 높은 순으로 정렬한다.","g":"Q"},{"id":"s4-09","r":4,"n":9,"type":"SQL - 서브쿼리 작성","pt":9,"q":"PRODUCT 테이블(NAME, PRICE)에서, 가격(PRICE)이 가장 높은 제품의 이름(NAME)을 조회하는 SELECT문을, 서브쿼리를 이용하여 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT NAME\nFROM PRODUCT\nWHERE PRICE = (SELECT MAX(PRICE) FROM PRODUCT);","e":"서브쿼리 (SELECT MAX(PRICE) FROM PRODUCT)로 전체 제품 중 최고 가격을 구한 뒤, 메인 쿼리 에서 그 가격과 일치하는 제품의 이름을 조회한다.","g":"Q"},{"id":"s4-10","r":4,"n":10,"type":"응용SW/테스트 - 서술형","pt":8,"q":"블랙박스 테스트 기법 중, 입력값을 유효한 값과 유효하지 않은 값으로 나누어 각 부분 집합에서 대표값을 선정하여 테스트하는 기법의 명칭을 쓰시오.","code":"","a":"동등 분할(Equivalence Partitioning)","acode":"","e":"동등 분할은 입력 조건을 유효한 클래스와 유효하지 않은 클래스로 나누고, 각 클래스에서 대표값을 하나씩 선정하여 테스트하는 블랙박스 테스트 기법이다.","g":"T"},{"id":"s4-11","r":4,"n":11,"type":"응용SW/테스트 - 서술형","pt":8,"q":"순환 복잡도(Cyclomatic Complexity)를 구하는 공식을 노드(N)와 에지(E)를 이용하여 쓰시오.","code":"","a":"V(G) = E - N + 2","acode":"","e":"순환 복잡도는 흐름 그래프의 에지(Edge) 수에서 노드(Node) 수를 빼고 2를 더하는 방식(V(G) = E -N + 2)으로 계산하며, 이 값은 해당 프로그램을 완전히 테스트하기 위해 필요한 최소한의 독립적인 테스트 경로 수를 의미한다.","g":"T"},{"id":"s4-12","r":4,"n":12,"type":"응용SW/테스트 - 서술형","pt":8,"q":"OSI 7계층 중, IP 주소를 기반으로 데이터의 경로를 설정(라우팅)하는 역할을 담당하는 계층의 명칭을 쓰시오.\nⅠ. 문제","code":"","a":"네트워크 계층","acode":"","e":"네트워크 계층(3계층)은 송신지와 수신지 사이의 여러 경로 중 최적의 경로를 선택하는 라우팅 기능을 담당하며, 대표적인 장비로 라우터가 있다.","g":"T"},{"id":"s5-01","r":5,"n":1,"type":"C - 출력 예측","pt":8,"q":"위 C 프로그램의 실행 결과를 쓰시오.","code":"#include <stdio.h>\nint main() {\n         int arr[3][2] = {{1, 2}, {3, 4}, {5, 6}};\n         int sum = 0;\n         for (int i = 0; i < 3; i++) {\n             sum += arr[i][1];\n         }\n         printf(\"%d\", sum);\n         return 0;\n}","a":"12","acode":"","e":"각 행의 두 번째 열(인덱스 1)의 값만 더한다. arr[0][1]=2, arr[1][1]=4, arr[2][1]=6이므로 2+4+6=12가 출력된다.","g":"C"},{"id":"s5-02","r":5,"n":2,"type":"C - 빈칸 채우기","pt":8,"q":"다음은 1부터 n까지의 수 중 3의 배수의 개수를 세는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 조건식을 쓰시오.","code":"#include <stdio.h>\nint main() {\n         int n = 20, count = 0;\n         for (int i = 1; i <= n; i++) {\n             if ( ① ) {\n                 count++;\n             }\n         }\n         printf(\"%d\", count);\n         return 0;\n}","a":"","acode":"i % 3 == 0","e":"i를 3으로 나눈 나머지가 0인 경우가 3의 배수이므로, 조건식은 i % 3 == 0이 되어야 한다.","g":"C"},{"id":"s5-03","r":5,"n":3,"type":"Java - 출력 예측","pt":8,"q":"위 Java 프로그램의 실행 결과를 쓰시오.","code":"public class Test {\n      public static void main(String[] args) {\n            StringBuilder sb = new StringBuilder();\n            for (int i = 1; i <= 3; i++) {\n                 sb.append(i).append(\"-\");\n            }\n            System.out.println(sb.toString());\n      }\n}","a":"1-2-3-","acode":"","e":"StringBuilder의 append() 메서드는 문자열을 이어 붙인다. i가 1, 2, 3으로 반복되며 각각 숫자와 \"-\"를 이어 붙이므로 최종 결과는 \"1-2-3-\"이 된다.","g":"J"},{"id":"s5-04","r":5,"n":4,"type":"Java - 디버깅","pt":9,"q":"다음 프로그램은 배열의 모든 요소의 평균을 구하려는 의도로 작성되었으나, 실행 결과가 항상 정수로만 표시 되어 소수점 이하 값이 유실된다. 오류가 있는 줄을 찾아 올바르게 수정하시오.","code":"public class Test {\n      public static void main(String[] args) {\n            int[] arr = {1, 2, 3, 4};\n            int sum = 0;\n            for (int i = 0; i < arr.length; i++) {\n                 sum += arr[i];\n            }\n            int average = sum / arr.length;\n            System.out.println(average);\n      }\n}","a":"","acode":"int average = sum / arr.length;   →   double average = (double) sum /\narr.length;","e":"sum과 arr.length가 모두 int(정수형)이므로 나눗셈 결과도 정수로 계산되어 소수점 이하가 버려진다. sum 또는 arr.length 중 하나를 double로 형변환한 뒤 나눗셈을 수행하고, average의 자료형도 double로 선언해야 소수점 이하 값을 포함한 정확한 평균을 구할 수 있다.","g":"J"},{"id":"s5-05","r":5,"n":5,"type":"Python - 출력 예측","pt":8,"q":"위 Python 프로그램의 실행 결과를 쓰시오.","code":"def apply_discount(price, rate):\n   return price - price * rate\n\nprices = [10000, 20000, 30000]\nresult = [apply_discount(p, 0.1) for p in prices]\nprint(result)","a":"[9000.0, 18000.0, 27000.0]","acode":"","e":"리스트 컴프리헨션은 prices의 각 가격에 10%(0.1) 할인을 적용한 결과를 새 리스트로 만든다. 10000×0.9=9000.0, 20000×0.9=18000.0, 30000×0.9=27000.0이 되어 [9000.0, 18000.0, 27000.0]이 출력된다.","g":"Y"},{"id":"s5-06","r":5,"n":6,"type":"Python - 빈칸 채우기","pt":9,"q":"다음은 두 리스트의 같은 위치에 있는 값끼리 더한 새로운 리스트를 만드는 프로그램이다. ( ① )에 들어갈 알맞은 코드를 작성하시오.\n( ① )에 들어갈 코드를 쓰시오.","code":"def add_lists(a, b):\n   result = []\n   for i in range(len(a)):\n         result.append( ① )\n   return result\n\nprint(add_lists([1, 2, 3], [10, 20, 30]))","a":"","acode":"a[i] + b[i]","e":"같은 인덱스 i에 위치한 두 리스트의 값을 더한 값(a[i] + b[i])을 result에 추가해야 두 리스트를 같은 위치끼리 더한 결과를 만들 수 있다.","g":"Y"},{"id":"s5-07","r":5,"n":7,"type":"SQL - DDL 작성","pt":8,"q":"다음 조건을 만족하는 CREATE TABLE문을 작성하시오.\n- 테이블명: DEPT\n- 컬럼: DEPT_ID(정수, 기본키), DEPT_NAME(가변길이 문자열 30자, 중복 불가)\n위 조건을 만족하는 CREATE TABLE문을 작성하시오.","code":"","a":"","acode":"CREATE TABLE DEPT (\n     DEPT_ID INT PRIMARY KEY,\n     DEPT_NAME VARCHAR(30) UNIQUE\n);","e":"DEPT_ID에 PRIMARY KEY를 지정해 기본키로 설정하고, DEPT_NAME에는 UNIQUE 제약조건을 지정하여 중복된 부서명이 입력되지 않도록 한다.","g":"Q"},{"id":"s5-08","r":5,"n":8,"type":"SQL - DML 작성","pt":9,"q":"EMPLOYEE 테이블(NAME, DEPT, HIRE_DATE)에서 2020년 이후(2020년 포함)에 입사한 사원의 NAME과 HIRE_DATE를 HIRE_DATE 오름차순으로 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT NAME, HIRE_DATE\nFROM EMPLOYEE\nWHERE HIRE_DATE >= '2020-01-01'\nORDER BY HIRE_DATE ASC;","e":"HIRE_DATE가 2020년 1월 1일 이후(포함)인 사원을 WHERE 절로 필터링하고, ORDER BY HIRE_DATE ASC로 입사일 오름차순 정렬한다.","g":"Q"},{"id":"s5-09","r":5,"n":9,"type":"SQL - 서브쿼리 작성","pt":9,"q":"ENROLL 테이블(STUDENT_NAME, COURSE)에서, 2개 이상의 과목을 수강하는 학생의 이름 (STUDENT_NAME)을 중복 없이 조회하는 SELECT문을 작성하시오.\n위 조건을 만족하는 SELECT문을 작성하시오.","code":"","a":"","acode":"SELECT STUDENT_NAME\nFROM ENROLL\nGROUP BY STUDENT_NAME\nHAVING COUNT(*) >= 2;","e":"STUDENT_NAME별로 그룹화한 뒤 COUNT(*)로 수강 과목 수를 계산하고, HAVING COUNT(*) >= 2 조건으로 2개 이상의 과목을 수강하는 학생만 필터링한다. GROUP BY 자체가 학생별로 묶어주므로 중복 없이 조회된다.","g":"Q"},{"id":"s5-10","r":5,"n":10,"type":"응용SW/테스트 - 서술형","pt":8,"q":"테스트 원칙 중, 동일한 테스트 케이스를 반복적으로 사용하면 새로운 결함을 발견하는 효과가 점점 감소한다는 원칙의 명칭을 쓰시오.","code":"","a":"살충제 패러독스(Pesticide Paradox)","acode":"","e":"살충제 패러독스는 동일한 테스트 케이스를 반복 사용하면 그 케이스로는 더 이상 새로운 결함을 찾을 수 없게 되므로, 테스트 케이스를 정기적으로 검토하고 개정해야 한다는 원칙이다.","g":"T"},{"id":"s5-11","r":5,"n":11,"type":"응용SW/테스트 - 서술형","pt":8,"q":"인수 테스트 중, 개발사의 통제된 환경에서 실제 사용자가 참여하여 수행하는 테스트와, 통제되지 않은 실제 사용 환경에서 다수의 사용자가 참여하여 수행하는 테스트의 명칭을 각각 쓰시오.","code":"","a":"알파 테스트, 베타 테스트","acode":"","e":"알파 테스트는 개발사 내부의 통제된 환경에서 실제 사용자가 참여하여 진행하며, 베타 테스트는 통제되지 않은 실제 사용 환경에서 다수의 사용자가 참여하여 진행한다.","g":"T"},{"id":"s5-12","r":5,"n":12,"type":"응용SW/테스트 - 서술형","pt":8,"q":"형상 관리 도구 중, 중앙 저장소 방식이 아니라 각 개발자의 로컬 저장소에도 전체 버전 이력이 복제되어 저장 되는 분산 버전 관리 시스템의 대표적인 도구명을 쓰시오.","code":"","a":"Git","acode":"","e":"Git은 분산 버전 관리 시스템(DVCS)으로, 중앙 저장소뿐만 아니라 각 개발자의 로컬 저장소에도 전체 버전 이력이 복제되어 저장된다는 점이 CVS·SVN과 근본적으로 다르다.","g":"T"}];
window.CARDS=[{"id":"k001","d":"C·Java·Python","f":"C 언어를 만든 사람과 해는?","b":["1972년, 벨 연구소, 데니스 리치","유닉스(UNIX) 운영체제를 만들려고 개발"]},{"id":"k002","d":"C·Java·Python","f":"컴파일러 vs 인터프리터","b":["컴파일러: 전체를 한꺼번에 번역, 목적 프로그램 생성, 실행 빠름 (C, C++, Java)","인터프리터: 한 줄씩 해석·실행, 목적 프로그램 없음, 실행 느림 (Python, JavaScript)"]},{"id":"k003","d":"C·Java·Python","f":"C 서식 지정자 %d %f %c %s %x","b":["%d 정수","%f 실수","%c 문자 하나","%s 문자열","%x 16진수","\\n 줄바꿈"]},{"id":"k004","d":"C·Java·Python","f":"C에서 7 / 2 와 7 % 2 는?","b":["7 / 2 = 3 (정수끼리 나누면 소수점 버림)","7 % 2 = 1 (나머지)","7 / 2.0 = 3.5 (실수가 섞이면 실수 결과)"]},{"id":"k005","d":"C·Java·Python","f":"전위 ++a vs 후위 a++","b":["전위 ++a: 먼저 1 늘리고 그 값을 사용","후위 a++: 지금 값을 먼저 쓰고 나중에 1 늘림","a=5일 때 b=a++ → b=5, a=6"]},{"id":"k006","d":"C·Java·Python","f":"scanf(\"%d\", &a)에서 &의 뜻은?","b":["주소 연산자","입력값을 저장할 변수의 메모리 주소를 넘겨줌"]},{"id":"k007","d":"C·Java·Python","f":"포인터 int *p = &x; 에서 *p는?","b":["p는 x의 주소를 저장","*p는 그 주소에 있는 값 = x","*p = *p + 5 → x가 5 늘어남"]},{"id":"k008","d":"C·Java·Python","f":"시프트 연산 3 << 1 과 8 >> 1 은?","b":["<< 1은 2를 곱한 효과 → 3 << 1 = 6",">> 1은 2로 나눈 효과 → 8 >> 1 = 4"]},{"id":"k009","d":"C·Java·Python","f":"객체지향의 4가지 특징은?","b":["캡슐화","상속성","다형성","추상화"]},{"id":"k010","d":"C·Java·Python","f":"Java 접근 제어자 3가지는?","b":["public, private, protected","static은 접근 제어자가 아님 (클래스 차원의 멤버)"]},{"id":"k011","d":"C·Java·Python","f":"Python 슬라이싱 lst[1:4]는?","b":["인덱스 1, 2, 3 (4는 포함 안 함)","예: [10,20,30,40,50][1:4] → [20, 30, 40]"]},{"id":"k012","d":"C·Java·Python","f":"Python range(1, 10, 2)는?","b":["1부터 9까지 2씩 → 1, 3, 5, 7, 9","끝 숫자 10은 포함 안 함"]},{"id":"k013","d":"C·Java·Python","f":"팩토리얼 계산에서 결과 변수 시작값은?","b":["1로 시작 (곱셈의 항등원)","0으로 시작하면 무엇을 곱해도 0"]},{"id":"k014","d":"C·Java·Python","f":"합계 계산에서 결과 변수 시작값은?","b":["0으로 시작 (덧셈의 항등원)","sum += i; 또는 sum = sum + i;"]},{"id":"k015","d":"C·Java·Python","f":"1의 보수와 2의 보수","b":["1의 보수: 0과 1을 뒤집기","2의 보수: 1의 보수 + 1","+5 = 00000101 → -5 = 11111011"]},{"id":"k016","d":"C·Java·Python","f":"2진수 1101을 10진수로","b":["1×8 + 1×4 + 0×2 + 1×1 = 13"]},{"id":"k017","d":"SQL","f":"SQL 명령어 4가지 분류는?","b":["DDL(정의): CREATE, ALTER, DROP, TRUNCATE","DML(조작): SELECT, INSERT, UPDATE, DELETE","DCL(제어): GRANT, REVOKE","TCL(트랜잭션): COMMIT, ROLLBACK, SAVEPOINT"]},{"id":"k018","d":"SQL","f":"SELECT 문의 기본 순서는?","b":["SELECT 열 FROM 테이블","WHERE 조건","GROUP BY 묶기","HAVING 묶은 뒤 조건","ORDER BY 정렬 (ASC 오름, DESC 내림)"]},{"id":"k019","d":"SQL","f":"WHERE vs HAVING","b":["WHERE: 행을 고르는 조건 (묶기 전)","HAVING: GROUP BY로 묶은 그룹의 조건 (집계 함수 사용)"]},{"id":"k020","d":"SQL","f":"집계 함수 5가지","b":["COUNT 개수","SUM 합계","AVG 평균","MAX 최댓값","MIN 최솟값"]},{"id":"k021","d":"SQL","f":"CREATE TABLE 기본 모양","b":["CREATE TABLE 이름 (","  ID INT PRIMARY KEY,","  NAME VARCHAR(20) NOT NULL",");"]},{"id":"k022","d":"SQL","f":"제약조건 종류","b":["PRIMARY KEY 기본키 (중복·NULL 안 됨)","FOREIGN KEY 외래키 (다른 테이블 참조)","NOT NULL 빈 값 금지","UNIQUE 중복 금지","CHECK 조건 검사","DEFAULT 기본값"]},{"id":"k023","d":"SQL","f":"INSERT · UPDATE · DELETE 모양","b":["INSERT INTO 표 (열) VALUES (값)","UPDATE 표 SET 열 = 값 WHERE 조건","DELETE FROM 표 WHERE 조건"]},{"id":"k024","d":"SQL","f":"DROP vs TRUNCATE vs DELETE","b":["DROP: 테이블 자체를 없앰","TRUNCATE: 구조는 두고 데이터 전부 삭제","DELETE: 조건에 맞는 행만 삭제"]},{"id":"k025","d":"SQL","f":"INNER JOIN 기본 모양","b":["SELECT A.NAME, B.COURSE","FROM STUDENT A INNER JOIN ENROLL B","ON A.S_ID = B.S_ID;"]},{"id":"k026","d":"SQL","f":"GRANT · REVOKE","b":["GRANT 권한 ON 테이블 TO 사용자; → 권한 주기","REVOKE 권한 ON 테이블 FROM 사용자; → 권한 빼앗기"]},{"id":"k027","d":"SQL","f":"COMMIT · ROLLBACK","b":["COMMIT: 작업을 확정 저장","ROLLBACK: 확정 전 상태로 되돌리기","SAVEPOINT: 되돌릴 지점 표시"]},{"id":"k028","d":"SQL","f":"뷰(VIEW)란?","b":["실제 데이터를 저장하지 않는 가상의 테이블","하나 이상의 테이블로부터 정의"]},{"id":"k029","d":"SQL","f":"키의 종류","b":["슈퍼키: 유일성O, 최소성X","후보키: 유일성O, 최소성O","기본키: 후보키 중 선택, NULL 불가","대체키: 기본키가 아닌 후보키","외래키: 다른 테이블 참조"]},{"id":"k030","d":"SQL","f":"스키마 3단계","b":["외부 스키마: 개인 사용자 관점","개념 스키마: 조직 전체 관점","내부 스키마: 물리적 저장 관점"]},{"id":"k031","d":"SQL","f":"DBMS 구조의 발전","b":["계층형(트리) → 망형(그래프) → 관계형(테이블, 가장 보편적)"]},{"id":"k032","d":"운영체제·네트워크","f":"운영체제 4대 성능 평가 항목","b":["처리 능력(Throughput): 클수록 좋음","반환 시간(Turnaround Time): 작을수록 좋음","사용 가능도(Availability): 클수록 좋음","신뢰도(Reliability): 클수록 좋음"]},{"id":"k033","d":"운영체제·네트워크","f":"프로세스 5대 상태","b":["생성 → 준비 → 실행 → 대기 → 종료"]},{"id":"k034","d":"운영체제·네트워크","f":"프로세스 상태 전이 용어","b":["디스패치: 준비 → 실행","보류: 실행 → 대기","깨움: 대기 → 준비","시간 제한: 실행 → 준비"]},{"id":"k035","d":"운영체제·네트워크","f":"선점형 vs 비선점형 스케줄링","b":["선점형: RR(라운드 로빈), SRT, 다단계 큐, 다단계 피드백 큐","비선점형: FIFO(FCFS), SJF, HRN, 우선순위"]},{"id":"k036","d":"운영체제·네트워크","f":"OSI 7계층과 대표 장비","b":["1 물리: 허브·리피터","2 데이터링크: 브리지·스위치","3 네트워크: 라우터","4 전송: TCP/UDP","5 세션 · 6 표현(압축·암호화) · 7 응용","\"물-데-네-전-세-표-응\""]},{"id":"k037","d":"운영체제·네트워크","f":"TCP vs UDP","b":["TCP: 신뢰성 있는 1:1 연결 (FTP, Telnet, HTTP, SMTP)","UDP: 신뢰성은 낮지만 빠름 (DNS, 스트리밍, 게임)","구분 기준: 확인 절차가 있느냐"]},{"id":"k038","d":"운영체제·네트워크","f":"IP 주소 클래스 첫 옥텟","b":["A: 0~127 (대형)","B: 128~191 (중형)","C: 192~223 (소형)","D: 224~239 (멀티캐스트)","E: 240~254 (연구용)"]},{"id":"k039","d":"운영체제·네트워크","f":"라우팅 프로토콜","b":["거리 벡터: RIP, IGRP","링크 상태: OSPF","대형 ISP 사이: BGP"]},{"id":"k040","d":"운영체제·네트워크","f":"리눅스 기본 명령어 7가지","b":["cd 경로 변경 · ls 목록 · cp 복사","mkdir 디렉터리 만들기 · rm 삭제","chmod 권한 설정 · cat 파일 내용 보기"]},{"id":"k041","d":"운영체제·네트워크","f":"윈도우 ↔ 리눅스 명령어","b":["dir ↔ ls","copy ↔ cp","del ↔ rm","attrib ↔ chmod","type ↔ cat","tracert ↔ traceroute"]},{"id":"k042","d":"운영체제·네트워크","f":"ping · traceroute · who","b":["ping: 네트워크 상태 점검","traceroute: 경로 추적","who: 접속한 사용자 확인"]},{"id":"k043","d":"운영체제·네트워크","f":"ps · kill · pwd","b":["ps: 프로세스 목록","kill: 프로세스 종료 (PID 확인!)","pwd: 현재 경로 확인"]},{"id":"k044","d":"테스트·결함","f":"V모델의 짝","b":["요구사항 분석 ↔ 인수 테스트","시스템 설계 ↔ 시스템 테스트","모듈 설계 ↔ 통합 테스트","구현 ↔ 단위 테스트"]},{"id":"k045","d":"테스트·결함","f":"테스트 7원칙","b":["계획 단계부터 시작","결함을 찾는 활동","완전한 테스트는 불가능","상황에 따라 다름","결함 집중(파레토 법칙)","살충제 패러독스","오류-부재의 궤변"]},{"id":"k046","d":"테스트·결함","f":"테스트 레벨 4가지","b":["단위: 개발자, 모듈 하나","통합: 모듈 간 상호작용","시스템: 전체 시스템, 기능·비기능","인수: 사용자, 알파·베타 테스트"]},{"id":"k047","d":"테스트·결함","f":"드라이버 vs 스텁","b":["드라이버: 상향식 통합에서 아직 없는 상위 모듈 대신","스텁: 하향식 통합에서 아직 없는 하위 모듈 대신 (임시 값을 돌려줌)"]},{"id":"k048","d":"테스트·결함","f":"알파 vs 베타 테스트","b":["알파: 개발자 곁, 통제된 내부 환경","베타: 실제 사용자 환경, 통제되지 않음"]},{"id":"k049","d":"테스트·결함","f":"블랙박스 기법 5가지","b":["동등 분할","경계값 분석","결정 테이블 테스트","상태 전이 테스트","유스케이스 테스트"]},{"id":"k050","d":"테스트·결함","f":"화이트박스 커버리지","b":["구문(Statement): 모든 문장 한 번 이상","결정/분기(Decision): 모든 조건문의 참·거짓 분기 한 번 이상","조건(Condition): 각 개별 조건의 참·거짓","조건/결정: 둘 다"]},{"id":"k051","d":"테스트·결함","f":"테스트 오라클 4가지","b":["참 오라클: 모든 입력값","샘플링 오라클: 일부 입력값","휴리스틱 오라클: 샘플링 + 나머지 추정","일관성 검사 오라클: 변경 전후 비교"]},{"id":"k052","d":"테스트·결함","f":"테스트 케이스 구성 요소","b":["식별자","테스트 대상","사전 조건","입력값","기대 결과"]},{"id":"k053","d":"테스트·결함","f":"결함 용어 흐름","b":["에러(Error): 사람의 실수","오류/폴트(Fault): 코드에 남은 흔적","실패(Failure): 실행 결과가 다름","결함(Defect): 이 모두를 포괄"]},{"id":"k054","d":"테스트·결함","f":"결함 상태 흐름","b":["등록(Open) → 할당(Assigned) → 수정(Fixed) → 확인 → 종료(Closed)","필요하면 재오픈"]},{"id":"k055","d":"테스트·결함","f":"결함 심각도 3단계","b":["High · Medium · Low"]},{"id":"k056","d":"테스트·결함","f":"결함 분류 4가지","b":["시스템 결함","기능 결함","GUI 결함","문서 결함"]},{"id":"k057","d":"테스트·결함","f":"형상 관리 5대 활동","b":["형상 식별 → 버전 관리 → 변경 통제 → 형상 감사 → 상태 보고"]},{"id":"k058","d":"테스트·결함","f":"형상 관리 도구","b":["CVS → SVN → Git (시대순)","Git은 분산 버전 관리(DVCS)"]},{"id":"k059","d":"테스트·결함","f":"인스펙션 vs 워크스루","b":["인스펙션: 동료, 체크리스트 사용, 모든 결함 제거","워크스루: 저자가 주도, 체크리스트 없음"]},{"id":"k060","d":"테스트·결함","f":"결합도와 응집도 원칙","b":["결합도는 낮게","응집도는 높게"]},{"id":"k061","d":"테스트·결함","f":"정적 분석 vs 동적 분석","b":["정적: 프로그램을 실행하지 않고 코드를 분석","동적: 프로그램을 실행하면서 분석"]},{"id":"k062","d":"테스트·결함","f":"회귀 테스트란?","b":["고친 뒤 다른 곳에 새 오류가 생기지 않았는지 다시 확인하는 테스트"]}];
